const V255_ICON_TEXT={cart:'⌂',utensils:'⌁',coffee:'◌',bag:'◈',home2:'⌂',wrench:'⌘',sofa:'◫',bolt2:'⌁',droplet2:'◍',wifi2:'◔',smartphone:'▣',flame2:'◇',car2:'▤',bus2:'▥',fuel:'▧',heart2:'♡',pills:'◍',microscope:'◔',tooth:'◌',dumbbell:'▭',book2:'▤',graduation:'◫',badge2:'◉',shirt:'◈',gift2:'✦',ticket:'◭',gamepad:'◪',plane2:'△',bed2:'▤',box2:'▣',monitor2:'▥',laptop2:'▦',cloud2:'◔',shield3:'⬒',paw2:'✣',handHeart:'♡',refresh2:'◌',alert2:'△',sparkles:'✦',percent2:'％',megaphone2:'◍',truck2:'▧',tools2:'⌘',coins2:'◎',banknote2:'▤',trend2:'↗',handshake2:'◈',cup2:'◌',music2:'♪',film2:'◫',briefcase:'▣',play:'▷',map:'◇',cpu:'▦',headphones:'◖'};
function v255TaxonomyKindForCategory(name){if(name&&categoryMap('gasto')[name])return 'gasto';if(name&&categoryMap('ingreso')[name])return 'ingreso';return 'gasto'}
function v255TaxonomyIconName(kind,category='',subcategory=''){const pack=V255_TAXONOMY[kind]||{};const key=`${category}||${subcategory}`;const em=db&&db.categoryEmoji||{};const own=subcategory&&em[`${kind}||${category}||${subcategory}`],parent=em[`${kind}||${category}`];if(own)return 'emoji:'+own;const builtin=(subcategory&&pack.subcategories&&pack.subcategories[key]);if(!builtin&&parent)return 'emoji:'+parent;return builtin||((pack.categories||{})[category])||(kind==='ingreso'?'banknote2':'receipt')}
function v255TaxonomyOptionLabel(kind,category,subcategory=''){const iconName=v255TaxonomyIconName(kind,category,subcategory);const label=subcategory||category||'';return `${String(iconName).startsWith('emoji:')?String(iconName).slice(6):(V255_ICON_TEXT[iconName]||'•')} ${label}`.trim()}
function v255TaxonomyBadge(kind,category,subcategory='',opts={}){const label=(opts.subOnly&&subcategory)?subcategory:(subcategory||category||'Sin categoría');const iconName=v255TaxonomyIconName(kind,category,subcategory);const cls=`v255-tax-badge${subcategory?' sub':''}${opts.compact?' compact':''}`;const title=subcategory?`${category} / ${subcategory}`:category||label;return `<span class="${cls}" title="${sanitize(title)}"><span class="v255-tax-ico">${icon(iconName)}</span><span class="v255-tax-label">${sanitize(label)}</span></span>`}
function v255TransactionCategoryCell(t){const kind=['income','bank_reward','card_reward'].includes(t.type)?'ingreso':'gasto';const cat=t.category||(['income','bank_reward','card_reward'].includes(t.type)?'Otros ingresos':(['loan_payment','card_payment'].includes(t.type)?'Deudas e intereses':'Otros gastos'));return `${v255TaxonomyBadge(kind,cat,'',{compact:true})}${v5NeedsAppleCategory(t)?`<button type="button" class="v5-apple-cat-action" data-v5-apple="categorize" data-id="${sanitize(String(t.id))}">Cambiar categoría</button>`:''}${t.subcategory?`<div class="subtitle">${v255TaxonomyBadge(kind,cat,t.subcategory,{compact:true,subOnly:true})}</div>`:''}`}
function v255DecorateTaxonomyUI(){const root=document.getElementById('app');if(!root)return;root.querySelectorAll('label').forEach(label=>{const catSel=label.querySelector('select[name="category"]');if(catSel){const parentForm=catSel.form||label.closest('form');let preview=label.querySelector('.v255-tax-select-preview');if(!preview){preview=document.createElement('div');preview.className='v255-tax-select-preview';label.appendChild(preview)}const kind=()=>{if(catSel.id==='customParent')return document.getElementById('customKind')?.value||'gasto';if(catSel.id==='txCategory')return parentForm?.elements?.type?.value==='income'?'ingreso':'gasto';if(['recCategory','budgetCategory'].includes(catSel.id))return 'gasto';if(parentForm?.elements?.kind?.value==='ingreso')return 'ingreso';return v255TaxonomyKindForCategory(catSel.value)};const paint=()=>{preview.innerHTML=catSel.value?`<span class="v255-tax-select-note">Categoría</span>${v255TaxonomyBadge(kind(),catSel.value)}`:''};paint();catSel.addEventListener('change',paint)}const subSel=label.querySelector('select[name="subcategory"]');if(subSel){const parentForm=subSel.form||label.closest('form');const catSel=parentForm?.querySelector('select[name="category"]');let preview=label.querySelector('.v255-tax-select-preview');if(!preview){preview=document.createElement('div');preview.className='v255-tax-select-preview';label.appendChild(preview)}const kind=()=>{if(catSel?.id==='txCategory')return parentForm?.elements?.type?.value==='income'?'ingreso':'gasto';if(['recCategory','budgetCategory'].includes(catSel?.id))return 'gasto';if(parentForm?.elements?.kind?.value==='ingreso')return 'ingreso';return v255TaxonomyKindForCategory(catSel?.value)};const paint=()=>{preview.innerHTML=(subSel.value&&catSel?.value)?`<span class="v255-tax-select-note">Subcategoría</span>${v255TaxonomyBadge(kind(),catSel.value,subSel.value,{subOnly:true})}`:''};paint();subSel.addEventListener('change',paint);if(catSel)catSel.addEventListener('change',paint)}})}

let v1235TodayAt=0,v1235Today='';
const today=()=>{const n=Date.now();if(n-v1235TodayAt<1000&&v1235Today)return v1235Today;let r;try{r=window.FinanzasReglas.hoy()}catch(_){r=dateStr(new Date())}v1235TodayAt=n;v1235Today=r;return r};
/* Año y mes actuales salen del mismo «hoy» del producto (America/Santo_Domingo), no de la zona del dispositivo. */
const nowYear=()=>Number(today().slice(0,4)),nowMonth=()=>Number(today().slice(5,7));
const dateStr=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const dateObj=s=>{if(!s)return new Date(2000,0,1);let [y,m,d]=String(s).slice(0,10).split('-').map(Number);return new Date(y,m-1,d||1)};
const addDays=(s,n)=>{let d=dateObj(s);d.setDate(d.getDate()+n);return dateStr(d)};
const monthDay=(y,m,day)=>dateStr(new Date(y,m-1,Math.min(Math.max(1,day),new Date(y,m,0).getDate())));
const plusMonths=(s,n)=>{let d=dateObj(s);return monthDay(d.getFullYear(),d.getMonth()+1+n,d.getDate())};
const periodStart=(y,m)=>`${y}-${String(m).padStart(2,'0')}-01`;
const periodEnd=(y,m)=>dateStr(new Date(y,m,0));
const diffDays=(a,b)=>Math.round((dateObj(a)-dateObj(b))/86400000);
const v1235PrettyFmt=new Intl.DateTimeFormat('es-DO',{day:'2-digit',month:'short',year:'numeric'});
const prettyDate=s=>s?v1235PrettyFmt.format(dateObj(s)):'—';
const num=v=>Number.isFinite(+v)?+v:0;const rnd=v=>Math.round((num(v)+Number.EPSILON)*100)/100;
/* Reglas con vigencia e instantáneas: solo se agrega, nunca se edita ni se borra. */
function financeRuleAt(key,subject,date){try{return window.FinanzasReglas.reglaVigente(db.ruleVersions||[],key,date||today(),subject||'*')}catch(_){return undefined}}
function financeRuleList(key,subject){return (db.ruleVersions||[]).filter(v=>v.clave===key&&v.sujeto===(subject||'*')).sort((a,b)=>a.desde.localeCompare(b.desde))}
function financeRuleAdd(key,subject,value,from){
 const R=window.FinanzasReglas;db.ruleVersions=Array.isArray(db.ruleVersions)?db.ruleVersions:[];
 const made=R.nuevaVigencia(db.ruleVersions,{clave:key,sujeto:subject||'*',valor:value,desde:from});
 const item=made[made.length-1];const entry={id:uuid(),clave:item.clave,sujeto:item.sujeto,valor:JSON.parse(JSON.stringify(item.valor)),desde:item.desde,creada:item.creada};
 db.ruleVersions.push(entry);return entry;
}
/* Registro de auditoría: quién, cuándo (UTC), qué cambió y el valor anterior. Solo se agrega. */
function financeAudit(entity,recordId,action,before,after){
 try{
  db.auditLog=Array.isArray(db.auditLog)?db.auditLog:[];
  const copy=o=>o==null?null:JSON.parse(JSON.stringify(o));
  db.auditLog.push({id:uuid(),en:new Date().toISOString(),usuario:(typeof f33User!=='undefined'&&f33User&&f33User.id)||null,entidad:entity,idRegistro:String(recordId),accion:action,antes:copy(before),despues:copy(after)});
 }catch(_){}
}
function financeAuditDiff(entity,recordId,prev,next,fields){
 const a={},b={};
 for(const k of fields){if(String(prev?.[k]??'')!==String(next?.[k]??'')){a[k]=prev?.[k]??null;b[k]=next?.[k]??null}}
 if(Object.keys(a).length)financeAudit(entity,recordId,'edición',a,b);
}
/* Condiciones de una tarjeta (límites, sobregiro, tasas, comisión por avance, anualidad) con vigencia.
   Cada cambio agrega una vigencia desde su fecha; el pasado conserva las condiciones que tenía. */
const CONDICIONES_TARJETA=['limitDOP','limitUSD','overdraftDOP','overdraftUSD','aprDOP','aprUSD','advanceFeePct','annualFeeAmount','annualFeeCurrency'];
function cardConditionAt(c,field,date){
 const r=financeRuleAt('tarjeta.condiciones',c.id,date||today());
 return (r&&r[field]!==undefined&&r[field]!==null)?r[field]:c[field];
}
function cardConditionChanges(c){
 const list=financeRuleList('tarjeta.condiciones',c.id),out=[];
 for(let i=1;i<list.length;i++){
  const prev=list[i-1].valor,next=list[i].valor;
  for(const k of CONDICIONES_TARJETA){if(prev[k]!==null&&prev[k]!==undefined&&String(prev[k])!==String(next[k]??''))out.push({desde:list[i].desde,campo:k,antes:prev[k],despues:next[k]})}
 }
 return out.sort((a,b)=>b.desde.localeCompare(a.desde));
}
const ETIQUETA_CONDICION={limitDOP:'Límite RD$',limitUSD:'Límite US$',overdraftDOP:'Sobregiro RD$',overdraftUSD:'Sobregiro US$',aprDOP:'Tasa anual RD$ (%)',aprUSD:'Tasa anual US$ (%)',advanceFeePct:'Comisión por avance (%)',annualFeeAmount:'Anualidad',annualFeeCurrency:'Moneda de la anualidad'};
function cardChangeHistoryPanel(c){
 const rows=cardConditionChanges(c);
 const fmt=(k,v)=>/^(limit|overdraft|annualFeeAmount)/.test(k)?money(num(v),k.endsWith('USD')?'USD':'DOP',0):String(v??'—');
 const body=rows.length?rows.map(r=>`<div class="mini-row"><div><div class="mini-title">${sanitize(ETIQUETA_CONDICION[r.campo]||r.campo)}</div><div class="mini-sub">Vigente desde ${sanitize(prettyDate(r.desde))}</div></div><strong>${sanitize(fmt(r.campo,r.antes))} → ${sanitize(fmt(r.campo,r.despues))}</strong></div>`).join(''):'<p class="tiny muted">Sin cambios de condiciones. Si modificas el límite, las tasas o la comisión, el cambio rige desde ese día y el historial anterior no se altera.</p>';
 return `<div class="panel section card-condition-history"><div class="panel-head"><h3>Antigüedad e historial de la tarjeta</h3></div>${antiguedadRow(c,'card')}${body}</div>`;
}
/* Cuentas y préstamos muestran su antigüedad al final del detalle (el efectivo no tiene antigüedad). */
function accountDetail(a){
 let original=originalAccountDetail(a);if(a.kind==='cash')original=original.replaceAll(`data-act="editAccount" data-id="${a.id}"`,`data-act="editCashWallet" data-id="${a.id}"`).replace('Editar cuenta','Editar efectivo RD$ / US$');
 const dates=Array.from({length:8},(_,i)=>{let dt=dateObj(today());dt.setDate(1);dt.setMonth(dt.getMonth()-(7-i));return dateStr(new Date(dt.getFullYear(),dt.getMonth()+1,0));});
 const values=dates.map(d=>getAccountBalance(a,d));
 const max=Math.max(1,...values),min=Math.min(0,...values),span=Math.max(1,max-min);
 const coords=values.map((v,i)=>[22+i*87,126-(v-min)/span*105]);
 const line=coords.map(([x,y],i)=>`${i?'L':'M'}${x},${y.toFixed(1)}`).join(' ');
 const plot=`<section class="account-history" aria-label="Evolución histórica de la cuenta"><div class="panel-head"><div><h3>Cómo ha evolucionado tu saldo</h3><p class="subtle">Últimos ocho cierres mensuales · ${sanitize(a.currency)} · saldos calculados de tus registros</p></div><span class="pill">Saldo actual ${money(getAccountBalance(a),a.currency,2)}</span></div><svg viewBox="0 0 660 160" class="account-evolution-svg" role="img" aria-label="Evolución del saldo de ${sanitize(a.name)}">${[.25,.5,.75].map(i=>`<line x1="15" x2="653" y1="${126-i*105}" y2="${126-i*105}" stroke="currentColor" opacity=".12" stroke-dasharray="4 6"/>`).join('')}<path d="${line}" fill="none" stroke="#5986eb" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>${coords.map(([x,y],i)=>`<g tabindex="0" data-chart-tip="${prettyDate(dates[i])}|Saldo: ${money(values[i],a.currency,2)}"><circle cx="${x}" cy="${y}" r="4" fill="#5687ed" stroke="white" stroke-width="2"/><rect x="${x-20}" y="14" width="40" height="123" fill="transparent"/></g><text x="${x}" y="154" text-anchor="middle" font-size="10" fill="currentColor" opacity=".75">${dateObj(dates[i]).toLocaleDateString('es-DO',{month:'short'})}</text>`).join('')}</svg></section>`;
 return original.replace('<div class="gap"></div>',plot+'<div class="gap"></div>');
}
function loanDetail(l){
  let b=loanBundle(l),a=b.actual,status=a.settled?'Liquidado':diffDays(a.next,today())<0?'Cuota vencida':'Activo',next=a.settled?'Sin cuotas pendientes':prettyDate(a.next);
  let tabs=[['vision','Visión general'],['amort','Amortización'],['payments','Historial real'],['simulate','Simulador de abonos']];
  let tab=loanWorkspace.tab||'vision';
  let body=tab==='vision'?loanVision(l,b)+loanConditions(l):tab==='amort'?loanAmortView(l,b):tab==='payments'?loanPaymentHistory(l,b):loanSimulator(l,b);
  const pct=num(l.principal)>0?Math.max(0,Math.min(100,a.paidPrincipal/num(l.principal)*100)):0,dis=a.settled||l.archived?'disabled':'';
  const stat=(k,v,sub)=>`<div class="vbd-stat"><small>${k}</small><strong>${v}</strong>${sub?`<em>${sub}</em>`:''}</div>`;
  const late=status==='Cuota vencida';
   return `<section class="loan-workspace vbd vbd-loan" id="loan-workspace">
    <div class="vbd-top"><button type="button" class="vbd-back" data-act="closeLoanDetails">${icon('arrow')}<span>Volver a mi cartera</span></button>
     <div class="vbd-top-actions"><button type="button" class="vbd-btn is-primary" data-act="payLoan" data-id="${l.id}" ${dis}><span>Registrar cuota</span></button><button type="button" class="vbd-btn" data-act="extraLoan" data-id="${l.id}" ${dis}><span>Abono extraordinario</span></button>
      <details class="vbd-menu"><summary aria-label="Más acciones">···</summary><div><button type="button" data-act="editLoan" data-id="${l.id}">Editar ficha</button><button type="button" data-act="productArchive" data-kind="loan" data-id="${l.id}">${l.archived?'Reactivar':'Cancelar'}</button></div></details></div></div>
    <div class="vbd-loan-hero">
     <article class="vbd-face"><span class="vbd-kicker">${sanitize(bankOf(l))} · ${sanitize(l.currency)}<em class="vbd-chip${late?' is-late':a.settled?' is-done':''}">${status}</em></span><h2>${sanitize(l.name)}</h2><p>Capital original ${money(l.principal,l.currency,2)} · ${num(l.rate).toFixed(2)}% anual · ${v49LoanPeriodCount(l)} ${v49LoanPeriodsPerMonth(l)===2?'quincenas':'cuotas mensuales'}${l.originationDate?' · desde '+prettyDate(l.originationDate):''}</p>
      <div class="vbd-loan-bal"><div class="vbd-ring" role="progressbar" aria-label="Capital amortizado" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct.toFixed(1)}" style="--p:${pct.toFixed(2)}"><div><b>${pct.toFixed(1)}%</b><small>pagado</small></div></div><div class="vbd-amt"><small>SALDO PENDIENTE</small><strong>${money(a.balance,l.currency,2)}</strong><span>Capital reducido ${money(a.paidPrincipal,l.currency)}</span></div></div></article>
     <div class="vbd-statgrid">${stat('PRÓXIMO VENCIMIENTO',next,a.settled?'':whenTxt(a.next))}${stat('CUOTA CONTRACTUAL',money(loanStatus(l).installment,l.currency,2))}${stat('CUOTAS',a.periods+' <i>/ '+v49LoanPeriodCount(l)+'</i>','registradas / pactadas')}${stat('INTERESES Y CARGOS A LA FECHA',money(a.interest+a.insurance+a.fees+a.estimatedHistoricInterest+a.estimatedHistoricInsurance+a.estimatedHistoricFees,l.currency,2),'Confirmados '+money(a.interest,l.currency,2))}${stat('INTERESES FUTUROS ESTIMADOS',money(l.archived?0:b.baseline.interest,l.currency,2))}${stat('ABONOS EXTRAORDINARIOS',money(a.extras,l.currency,2),'Reducen capital')}</div></div>
    <nav class="vbd-tabs" role="tablist" aria-label="Detalle de préstamo">${tabs.map(([key,title])=>`<button type="button" role="tab" aria-selected="${key===tab}" class="loan-tab vbd-tab ${key===tab?'on':''}" data-act="loanTab" data-id="${key}">${title}</button>`).join('')}</nav>
    <div class="loan-tab-content vbd-loan-body">${body}</div>
    ${num(l.reportedBalance)>0?`<div class="vbd-note-card"><span>${icon('shield')}</span><strong>Saldo confirmado por banco (${prettyDate(l.balanceAsOf||today())}): ${money(l.reportedBalance,l.currency,2)}. Diferencia frente al registro: ${money(a.balance-num(l.reportedBalance),l.currency,2)}.</strong></div>`:''}</section>`;
}
function originalAccountDetail(a){let t=recentTx().filter(t=>t.accountId===a.id||t.toAccountId===a.id).slice(0,12);return `<div class="panel section"><div class="panel-head"><h3>Detalle · ${sanitize(a.name)} (${a.currency})</h3><div class="hstack">${a.kind==='cash'?'':productControls('account',a.id,a.archived)}<button class="btn sm soft" data-act="editAccount" data-id="${a.id}">Editar cuenta</button><button class="btn sm ghost" data-act="closeAccountDetails">Cerrar</button></div></div><div class="stats-inline"><div class="stat-box"><span class="small-label">SALDO INICIAL</span><div class="val">${money(a.opening,a.currency,2)}</div><span class="tiny muted">Desde ${prettyDate(a.opened)}</span></div><div class="stat-box"><span class="small-label">SALDO ACTUAL</span><div class="val">${money(getAccountBalance(a),a.currency,2)}</div><span class="tiny muted">Incluye todas las operaciones</span></div><div class="stat-box"><span class="small-label">INTERÉS POTENCIAL / MES</span><div class="val">${money(Math.max(0,getAccountBalance(a))*num(a.annualRate)/1200,a.currency,2)}</div><span class="tiny muted">Estimación simple; para cobros reales registra un ingreso.</span></div><div class="stat-box"><span class="small-label">MOVIMIENTOS</span><div class="val">${t.length}${t.length>=12?'+':''}</div><span class="tiny muted">Últimos 12 visibles</span></div></div><div class="gap"></div>${smallTxTable(t)}</div>`}
function loanVision(l,b){
  const a=b.actual,totalFees=a.interest+a.insurance+a.fees;
  return `<div class="loan-vision-v2"><div class="glass-loan loan-right-panel"><div class="loan-panel-title"><h3>Tu progreso real</h3><p>Desde la firma hasta hoy</p></div><div class="loan-big-progress">${Math.min(100,num(l.principal)?a.paidPrincipal/l.principal*100:0).toFixed(1)}<small>%</small></div><div class="loan-progress large"><span style="width:${Math.min(100,num(l.principal)?a.paidPrincipal/l.principal*100:0)}%"></span></div><div class="loan-double-fact"><span>Capital reducido (histórico + registrado)</span><b>${money(a.paidPrincipal,l.currency,2)}</b></div><div class="loan-double-fact"><span>Intereses y cargos pagados</span><b>${money(totalFees,l.currency,2)}</b></div><div class="loan-double-fact"><span>Capital extraordinario</span><b>${money(a.extras,l.currency,2)}</b></div><button class="loan-inline-button" data-act="loanTab" data-id="payments">Explorar pagos reales ${icon('arrow')}</button></div>${loanComparison(l,b)}</div>`;
}
function loanConditions(l){let arr=l.conditionHistory||[];return `<div class="glass-loan loan-conditions"><div class="loan-panel-title"><h3>Condiciones originales y vigentes</h3><p>El contrato original no se sobrescribe cuando cambian las condiciones del banco.</p></div><div class="condition-grid"><div><span>TASA ORIGINAL</span><strong>${num(l.rate).toFixed(3)}%</strong></div><div><span>TASA VIGENTE</span><strong>${num(l.currentRate??l.rate).toFixed(3)}%</strong></div><div><span>SEGURO ACTUAL</span><strong>${money(l.insuranceMonthly||0,l.currency,2)}</strong></div><div><span>CAMBIOS REGISTRADOS</span><strong>${arr.length}</strong></div></div><div class="hstack" style="margin:15px 0"><button class="btn sm soft" data-act="editLoan" data-id="${l.id}">Actualizar condiciones</button>${productControls('loan',l.id,l.archived)}</div>${arr.length?`<div class="table-wrap"><table><thead><tr><th>Registrado</th><th>Vigente desde</th><th>Tasa anterior</th><th>Nueva tasa</th><th>Seguro anterior</th><th>Nuevo seguro</th><th>Cuota anterior</th><th>Nueva cuota</th></tr></thead><tbody>${arr.slice().reverse().map(x=>`<tr><td>${prettyDate(x.at.slice(0,10))}</td><td>${prettyDate(x.effectiveFrom)}</td><td>${num(x.fromRate).toFixed(3)}%</td><td>${num(x.toRate).toFixed(3)}%</td><td>${money(x.fromInsurance,l.currency,2)}</td><td>${money(x.toInsurance,l.currency,2)}</td><td>${x.fromInstallment===undefined?'—':money(x.fromInstallment,l.currency,2)}</td><td>${x.toInstallment===undefined?'—':money(x.toInstallment,l.currency,2)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="footnote">Todavía no existen revisiones de tasa, seguro o comisiones.</p>'}</div>`}
function loanAmortView(l,b){
  let mode=loanWorkspace.plan,rows=mode==='original'?b.original.rows:mode==='strategy'?[...b.actual.rows,...b.scenario.rows]:[...b.actual.rows,...b.baseline.rows];
  let sized=loanGroupedRows(rows,loanWorkspace.period);
  return `<div class="glass-loan loan-amort-panel"><div class="loan-panel-title loan-with-actions"><div><h3>Amortización inteligente</h3><p>Desde el primer día, hasta la liquidación.</p></div><button class="btn sm ghost" data-act="loanCsv" data-id="${l.id}">Exportar CSV ${icon('arrow')}</button></div><div class="v1248-strip"><span><small>CUOTAS REALES</small><b>${b.actual.rows.length}</b></span><span><small>PROYECTADAS</small><b>${(mode==='original'?b.original.rows:mode==='strategy'?b.scenario.rows:b.baseline.rows).length}</b></span><span><small>LIQUIDACIÓN</small><b>${prettyDate(mode==='original'?b.original.end:mode==='strategy'?b.scenario.end:b.baseline.end).replace(/ de (\d{4})$/,' $1')}</b></span></div><div class="loan-control-line"><div class="loan-segment">${[['original','Original'],['actual','Real + proyectado'],['strategy','Con estrategia']].map(([k,label])=>`<button data-act="loanPlan" data-id="${k}" class="${mode===k?'selected':''}">${label}</button>`).join('')}</div><div class="loan-segment">${[[1,'Mensual'],[3,'Trimestral'],[6,'Semestral'],[12,'Anual']].map(([n,label])=>`<button data-act="loanPeriod" data-id="${n}" class="${loanWorkspace.period===n?'selected':''}">${label}</button>`).join('')}</div></div><div class="loan-table-scroll"><table class="loan-data-table"><thead><tr><th>Período</th><th>Estado</th><th class="right">Saldo inicial</th><th class="right">Capital ordinario</th><th class="right">Intereses</th><th class="right">Seguro</th><th class="right">Abonos extra</th><th class="right">Pago total</th><th class="right">Saldo final</th></tr></thead><tbody>${sized.length?sized.map(r=>`<tr class="${r.kind.includes('real')?'loan-actual-row':''}"><td class="v1248-when">${loanWorkspace.period===1?prettyDate(r.date):r.label}</td><td class="v1248-state"><span class="loan-mini-state">${sanitize(r.kind)}</span></td><td class="right" data-l="Saldo inicial">${money(r.opening,l.currency,2)}</td><td class="right" data-l="Capital">${money(r.principal,l.currency,2)}</td><td class="right" data-l="Intereses">${money(r.interest,l.currency,2)}</td><td class="right" data-l="Seguro y cargos">${money(r.insurance+num(r.fee),l.currency,2)}</td><td class="right loan-extra-cell" data-l="Abonos extra">${money(r.extra,l.currency,2)}</td><td class="right" data-l="Pago total">${money(r.payment,l.currency,2)}</td><td class="right loan-balance-cell" data-l="Saldo final">${money(r.balance,l.currency,2)}</td></tr>`).join(''):'<tr><td colspan="9">No hay períodos disponibles.</td></tr>'}</tbody></table></div><div class="loan-small-note">La amortización calcula intereses y capital de cada cuota según el contrato. Los saldos bancarios informados se concilian explícitamente y no generan pagos falsos. La tasa puede diferir si el banco calcula por días exactos. La agregación trimestral, semestral y anual suma los pagos dentro de cada período.</div></div>`;
}
function loanPaymentHistory(l,b){
  let a=b.actual;
  return `<div class="glass-loan loan-history">${a.historicReduction>0?`<div class="v83-opening-banner"><span>HISTORIAL PREVIO · SALDO DE APERTURA</span><strong>${money(a.historicReduction,l.currency,2)} de capital reducido antes del registro</strong><small>Capital original menos el saldo de apertura. Los intereses se calcularon vencimiento por vencimiento según la cuota y tasa. Cualquier diferencia con el saldo del banco se muestra como conciliación, nunca como pago bancario registrado.</small></div>`:''}<div class="loan-panel-title loan-with-actions"><div><h3>Historial de cuotas</h3><p>Los pagos confirmados se distinguen de las cuotas históricas reconstruidas. Las estimaciones no mueven cuentas.</p></div><div class="loan-action-row"><button class="btn sm soft" data-act="extraLoan" data-id="${l.id}">+ Abono</button><button class="btn sm loan-primary" data-act="payLoan" data-id="${l.id}">+ Cuota</button></div></div><div class="loan-mini-summary"><span><small>Capital reducido desde origen</small><strong>${money(a.paidPrincipal,l.currency,2)}</strong></span><span><small>Interés pagado</small><strong>${money(a.interest,l.currency,2)} confirmado · ${money(a.estimatedHistoricInterest,l.currency,2)} estimado</strong></span>${Math.abs(a.historicAdjustment)>.009?`<span><small>Diferencia modelo / banco · conciliación (no pago)</small><strong>${money(Math.abs(a.historicAdjustment),l.currency,2)}</strong></span>`:''}<span><small>Seguro</small><strong>${money(a.insurance,l.currency,2)}</strong></span><span><small>Comisiones</small><strong>${money(a.fees,l.currency,2)}</strong></span></div><div class="loan-table-scroll"><table class="loan-data-table"><thead><tr><th>Fecha</th><th>Operación</th><th class="right">Capital</th><th class="right">Intereses</th><th class="right">Seguro + cargos</th><th class="right">Importe</th><th class="right">Saldo después</th><th></th></tr></thead><tbody>${a.rows.length?a.rows.map(r=>`<tr><td class="v1248-when">${prettyDate(r.date)}</td><td class="v1248-state"><span class="loan-mini-state">${sanitize(r.kind)}</span></td><td class="right" data-l="Capital">${money(r.principal,l.currency,2)}</td><td class="right" data-l="Intereses">${money(r.interest,l.currency,2)}</td><td class="right" data-l="Seguro y cargos">${money(r.insurance+r.fee,l.currency,2)}</td><td class="right" data-l="Pago total">${money(r.payment,l.currency,2)}</td><td class="right loan-balance-cell" data-l="Saldo después">${money(r.balance,l.currency,2)}</td><td class="v1248-act">${r.txId?`<button class="loan-delete" data-act="deleteTransaction" data-id="${r.txId}" title="Eliminar movimiento">×</button>`:`<small title="Cálculo contractual; no representa un movimiento bancario">Calculado</small>`}</td></tr>`).join(''):'<tr><td colspan="8"><div class="loan-empty-small">Todavía no has registrado pagos. El préstamo conservará su plan original hasta que añadas el primer movimiento.</div></td></tr>'}</tbody></table></div></div>`;
}
function loanSimulator(l,b){
  let s=b.simOpt,fmt=v=>money(v,l.currency,2),hasStrategy=num(s.amount)>0,bad=b.scenario.error;
  return `<div class="loan-simulator"><div class="glass-loan loan-sim-inputs"><span class="loan-overline">LABORATORIO DE ABONOS</span><h3>Diseña otro final para tu préstamo.</h3><p>Modifica importes y frecuencia sin tocar el historial financiero real. Para reducir la cuota, el banco debe aprobar la reamortización.</p><div class="loan-sim-fields"><label>Abono adicional (${l.currency})<input id="loanSimAmount" class="field" type="number" min="0" step="0.01" value="${s.amount}"/></label><label>Frecuencia<select id="loanSimFrequency" class="field">${[[0,'Una sola vez'],[1,'Mensual'],[2,'Cada 2 meses'],[3,'Trimestral'],[6,'Semestral'],[12,'Anual']].map(([v,t])=>`<option value="${v}" ${num(s.frequency)===v?'selected':''}>${t}</option>`).join('')}</select></label><label>Comenzar en<input id="loanSimStart" class="field" type="date" value="${s.start||b.actual.next}" min="${today()}"/></label><label>Objetivo<select id="loanSimMode" class="field"><option value="term" ${s.mode==='term'?'selected':''}>Reducir plazo</option><option value="payment" ${s.mode==='payment'?'selected':''}>Reducir cuota (requiere banco)</option></select></label></div><div class="loan-sim-actions"><button class="btn loan-primary" data-act="loanCalculate">Calcular impacto ${icon('arrow')}</button><button class="btn sm ghost" data-act="loanSimReset">Restablecer</button></div></div>
  <div class="glass-loan loan-sim-results"><span class="loan-overline">IMPACTO PROYECTADO</span><h3>${bad?'Revisa la simulación':'El ahorro posible.'}</h3>${bad?`<p class="loan-error">${sanitize(bad)}</p>`:`<div class="loan-saving">${fmt(b.projectedInterestSavings+b.projectedInsuranceSavings)}</div><p>Menos intereses y seguros futuros respecto a continuar sin nuevos abonos.</p><div class="loan-sim-facts"><div><span>Intereses evitados</span><strong>${fmt(b.projectedInterestSavings)}</strong></div><div><span>Seguros evitados</span><strong>${fmt(b.projectedInsuranceSavings)}</strong></div><div><span>Abonos extra previstos</span><strong>${fmt(b.scenario.extra)}</strong></div><div><span>Meses adelantados</span><strong>${b.monthsAdvanced>0?b.monthsAdvanced+' meses':'Sin cambio'}</strong></div><div><span>Liquidación sin estrategia</span><strong>${prettyDate(b.baseline.end)}</strong></div><div><span>Liquidación con estrategia</span><strong>${prettyDate(b.scenario.end)}</strong></div></div>`}<div class="loan-small-note">La cifra no incluye rendimientos alternativos del dinero ni penalidades de prepago. Las condiciones reales pueden diferir.</div></div></div>${loanComparison(l,b)}`;
}


function loanComparison(l,b){
  let curr=b.actual.interest+b.actual.estimatedHistoricInterest+b.baseline.interest,currIns=b.actual.insurance+b.actual.estimatedHistoricInsurance+b.baseline.insurance,currFee=b.actual.fees+b.actual.estimatedHistoricFees+b.baseline.fees;
  let sim=b.actual.interest+b.actual.estimatedHistoricInterest+b.scenario.interest,simIns=b.actual.insurance+b.actual.estimatedHistoricInsurance+b.scenario.insurance,simFee=b.actual.fees+b.actual.estimatedHistoricFees+b.scenario.fees;
  const r=(title,first,second,third)=>`<div class="loan-compare-row"><span>${title}</span><b data-l="Plan original">${first}</b><b data-l="Proyección vigente">${second}</b><b data-l="Con estrategia">${third}</b></div>`;
  const fmt=v=>money(v,l.currency,2);
  const P=num(l.principal),startD=l.originationDate||b.original.rows[0]?.date||b.actual.rows[0]?.date||today();
  const mths=d=>{const x=dateObj(startD),y=dateObj(d);return Math.max(0,Math.round(((y-x)/86400000)/30.4375))};
  const span=m=>{const y=Math.floor(m/12),r=m%12;return y?(y+(y===1?' año':' años')+(r?' '+r+(r===1?' mes':' meses'):'')):(r+(r===1?' mes':' meses'))};
  const col=(o)=>({cost:P+o.i+o.s+o.f,ret:P>0?(o.i+o.s+o.f)/P*100:0,m:mths(o.end),...o});
  const C0=col({i:b.original.interest,s:b.original.insurance,f:b.original.fees,end:b.original.end}),C1=col({i:curr,s:currIns,f:currFee,end:b.baseline.end}),C2=col({i:sim,s:simIns,f:simFee,end:b.scenario.end});
  const card=(ic,lab,val,tone)=>`<div class="v1249-item"><span class="v1249-ic">${icon(ic)}</span><div><small>${lab}</small><strong class="${tone||''}">${val}</strong></div></div>`;
  const plan=(cls,title,badge,C,endLab)=>`<section class="v1249-col ${cls}">${badge?`<span class="v1249-badge">${badge}</span>`:''}<h4>${title}</h4>${card('building','Capital solicitado',fmt(P))}${card('wallet','Costo total final',fmt(C.cost),'cost')}${card('down','Intereses cobrados',fmt(C.i),'cost')}${card('shield','Seguro pagado',fmt(C.s),'ins')}${card('analytics','Retorno del banco',C.ret.toFixed(2)+'%','cost')}${card('calendar',endLab,span(C.m)+' <i>· '+prettyDate(C.end)+'</i>')}</section>`;
  const dCost=C1.cost-C2.cost,dInt=C1.i-C2.i,dIns=C1.s-C2.s,dRet=C1.ret-C2.ret,dMon=C1.m-C2.m,sg=(v,f)=>(v>=0?'+':'−')+f(Math.abs(v));
  const diff=`<section class="v1249-col is-diff"><span class="v1249-badge">¡TU GANANCIA!</span><h4>Diferencia neta</h4>${card('building','Diferencia capital',fmt(0))}${card('up','Ahorro total neto',sg(dCost,fmt),'gain')}${card('down','Ahorro de intereses',sg(dInt,fmt),'gain')}${card('shield','Ahorro de seguros',sg(dIns,fmt),'gain')}${card('analytics','Bajaste el retorno',(dRet>=0?'−':'+')+Math.abs(dRet).toFixed(2)+'%','gain')}${card('clock','Tiempo ahorrado',(dMon>=0?'+':'−')+Math.abs(dMon)+(Math.abs(dMon)===1?' mes':' meses'),'gain')}</section>`;
  const cards=`<div class="glass-loan v1249-cmp"><h3>Análisis de costos comparativo</h3><p>Comparación basada en las condiciones registradas, no en valores confirmados por el banco. La diferencia neta compara la estrategia con la proyección vigente.</p><div class="v1249-grid">${plan('is-orig','Plan original','',C0,'Plazo original')}${plan('is-curr','Proyección vigente','',C1,'Termina en')}${plan('is-fast','Plan acelerado','¡TU ATAQUE!',C2,'Terminas en')}${diff}</div></div>`;
  return cards+`<div class="glass-loan loan-compare v1249-old"><div class="loan-panel-title"><h3>Tres escenarios, una misma deuda.</h3><p>Comparación basada en las condiciones registradas, no en valores confirmados por el banco.</p></div><div class="loan-compare-scroll"><div class="loan-compare-table"><div class="loan-compare-header"><span>Concepto</span><strong>Plan original</strong><strong>Proyección vigente</strong><strong>Con estrategia</strong></div>
  ${r('Capital inicial',fmt(l.principal),fmt(l.principal),fmt(l.principal))}
  ${r('Intereses totales',fmt(b.original.interest),fmt(curr),fmt(sim))}
  ${r('Seguro estimado',fmt(b.original.insurance),fmt(currIns),fmt(simIns))}
  ${r('Cargos estimados',fmt(b.original.fees),fmt(currFee),fmt(simFee))}
  ${r('Costo total',fmt(num(l.principal)+b.original.interest+b.original.insurance+b.original.fees),fmt(num(l.principal)+curr+currIns+currFee),fmt(num(l.principal)+sim+simIns+simFee))}
  ${r('Última cuota',prettyDate(b.original.end),prettyDate(b.baseline.end),prettyDate(b.scenario.end))}
  </div></div><div class="loan-small-note">La columna vigente incluye pagos históricos y cuotas futuras estimadas. La estrategia solo representa un escenario hipotético; no cambia tus balances.</div></div>`;
}
function loanGroupedRows(rows,size){
  if(size===1)return rows;
  let groups=[];for(const r of rows){const d=dateObj(r.date),key=size===12?`${d.getFullYear()}`:size===6?`${d.getFullYear()}-S${Math.floor(d.getMonth()/6)+1}`:`${d.getFullYear()}-T${Math.floor(d.getMonth()/3)+1}`;
    let g=groups.at(-1);if(!g||g.groupKey!==key){g={...r,groupKey:key,label:key,opening:r.opening,principal:0,interest:0,insurance:0,fee:0,extra:0,payment:0,kind:r.kind};groups.push(g)}
    g.principal+=r.principal;g.interest+=r.interest;g.insurance+=r.insurance;g.fee+=r.fee;g.extra+=r.extra;g.payment+=r.payment;g.balance=r.balance;g.date=r.date;
  }return groups;
}

