 if(t.type==='card_advance'){const fee=fx(num(t.advanceFee),t.currency||'DOP');expense+=fee;interest+=0;expenseBy['Deudas e intereses']=(expenseBy['Deudas e intereses']||0)+fee;expenseSubBy['Deudas e intereses||Comisión de avance de efectivo']=(expenseSubBy['Deudas e intereses||Comisión de avance de efectivo']||0)+fee;cashIn+=fx(num(t.advanceNet),t.currency||'DOP');}
