/* V206 · Switch contextual y continuo entre productos bancarios en móviles. */
function v206BankSwitch(page){
 const tabs=[
  ['banks','Bancos','landmark'],
  ['accounts','Cuentas','wallet'],
  ['loans','Préstamos','receipt'],
  ['certificates','Certificados','chart'],
 ];
 return `<nav class="v206-banks-switch" aria-label="Cambiar entre bancos y productos" data-v206-switch="1">${tabs.map(([id,label,ico])=>`<button type="button" data-v206-tab="${id}" class="v206-banks-pill ${page===id?'active':''}" aria-pressed="${page===id}" ${page===id?'aria-current="page"':''}>${icon(ico)}<span>${label}</span></button>`).join('')}</nav>`;
}
function moduleSwitch(page){
 const root=navFamilyForPage(page),section=NAV_SECTIONS[root];if(!section)return '';
 // V299: contextual navigation must stay available across all six Movimientos pages.
 if(root==='banks'&&isMobileViewport()){
  if(page==='cards')return '';
  return v206BankSwitch(page);
 }
 return `<div class="module-switch-shell"><div class="module-switch-title"><span class="module-switch-kicker">NAVEGACIÓN DEL MÓDULO</span><strong>${section.title}</strong><small>${section.hint}</small></div><nav class="module-switch-tabs" aria-label="Secciones de ${section.title}">${section.tabs.map(([id,name,ic,view])=>{const on=(page===id||(id==='flow'&&['income','expenses'].includes(page)))&&(!view||(ui.v176PayView||'agenda')===view);return `<button type="button" class="module-switch-tab ${on?'active':''}" ${on?'aria-current="page"':''} data-act="navigate" data-id="${id}"${view?` data-v176-pay-view="${view}"`:''}>${icon(ic)}<span>${name}</span></button>`}).join('')}</nav><span class="module-switch-swipe">Desliza la barra para explorar más opciones ↔</span></div>`;
}

