/* V36 · Notificaciones internas, basadas exclusivamente en vencimientos registrados. */
function v36DueItems(){
 return upcoming().filter(o=>o.kind!=='personal_recv'&&Number(o.amount)>0&&/^\d{4}-\d{2}-\d{2}$/.test(String(o.date||'')));
}

/* V988 · Los avisos de pago de la campanita y del informe abren directamente el pago correspondiente */
document.addEventListener('click',e=>{
 const b=e.target.closest?.('.v988-notice[data-act],[data-v988-pay]');if(!b)return;
 const det=b.closest('details.v36-notifications');if(det)det.open=false;
 if(b.matches('[data-v988-pay]')){document.getElementById('v216-layer')?.remove();document.body.classList.remove('v216-modal-open');}
});
/* V994 · «Limpiar todo»: oculta (en este dispositivo) los avisos presentes; los nuevos reaparecen. */
const V994_KEY='vive.notif.cleared.v1';
function v994Cleared(){try{const x=JSON.parse(localStorage.getItem(V994_KEY)||'{}');return {d:new Set(x.d||[]),s:new Set(x.s||[]),r:new Set(x.r||[])}}catch(_){return {d:new Set(),s:new Set(),r:new Set()}}}
const v994DueKey=o=>[o.kind,o.ref||o.id,o.date].join('|');
const v994SpendKey=a=>[a.category,a.kind].join('|');
function v994ClearAll(){
 const c=v994Cleared();
 try{for(const o of v36DueItems())c.d.add(v994DueKey(o));}catch(_){}
 try{for(const a of v123CategoryAlerts())c.s.add(v994SpendKey(a));}catch(_){}
 try{for(const e of v246ReportEvents()){c.r.add(e.id);if(typeof v246MarkReportRead==='function')v246MarkReportRead(e.id);}}catch(_){}
 try{localStorage.setItem(V994_KEY,JSON.stringify({d:[...c.d].slice(-400),s:[...c.s].slice(-100),r:[...c.r].slice(-200)}))}catch(_){}
}
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-v994-clear]');if(!b)return;e.preventDefault();e.stopPropagation();v994ClearAll();render();toast('Notificaciones eliminadas.')},true);
function v36Bell(){
 const todayISO=today();
 const all=v36DueItems().sort((a,b)=>a.date.localeCompare(b.date));
 const v994=v994Cleared();
 const visibleAll=all.filter(o=>!v994.d.has(v994DueKey(o)));
 const notices=visibleAll.filter(o=>diffDays(o.date,todayISO)<=14);
 const urgent=visibleAll.filter(o=>diffDays(o.date,todayISO)<=7).length;
 const spendAlerts=v123CategoryAlerts().filter(a=>!v994.s.has(v994SpendKey(a)));
 const svg=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></svg>`;
 const NI={card:'<rect x="3" y="5.5" width="18" height="13" rx="3"/><path d="M3 10h18M7 15h4"/>',loan:'<path d="M4 20h16M6 20V9l6-4 6 4v11M10 20v-5h4v5"/>',personal:'<circle cx="9" cy="8" r="3"/><path d="M3 20c0-3.3 2.7-6 6-6s6 2.7 6 6M16 11a3 3 0 1 0 0-6M18 14c2 .6 3 2.4 3 5"/>',recurring:'<path d="M20 12a8 8 0 1 1-2.3-5.7M20 4v4h-4"/>',spend:'<path d="M3 17l6-6 4 4 8-8M15 7h6v6"/>',report:'<path d="M6 3h9l4 4v14H6zM14 3v5h5M9 13h6M9 17h6"/>'};
 const nsvg=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${NI[k]||NI.recurring}</svg>`;
 const nbank=o=>{try{const it=o.kind==='card'?card(o.ref||o.id):o.kind==='loan'?loan(o.ref||o.id):null;const bk=it&&bank(it.bankId);return bk&&bankLogoSafe(bk.logo)?bankLogoMark(bk,'v1280-bank'):(bk?`<span class="v1280-initials">${sanitize((bk.name||'B').trim().slice(0,2).toUpperCase())}</span>`:'')}catch(_){return ''}};
 const items=notices.slice(0,9).map(o=>{
   const d=diffDays(o.date,todayISO),kind=o.kind==='card'?'Tarjeta':o.kind==='loan'?'Préstamo':o.kind==='personal'?'Entre personas':'Suscripción';
   const state=d<0?'Vencido · revisar':d===0?'Vence hoy':d===1?'Mañana':`En ${d} días`;
   const act=o.action?`data-act="${sanitize(o.action)}" data-id="${sanitize(String(o.ref||o.id))}" data-ccy="${sanitize(String(o.ccy||o.currency||''))}"`:'';
   return `<button type="button" class="v36-notice v988-notice ${d<0?'v36-expired':d<=3?'v36-urgent':''} v988-${o.kind}" ${act} aria-label="Pagar ${sanitize(o.name)}, ${kind}, ${state}"><span class="v988-nico v1280-ico ${nbank(o)?'has-logo':''}" aria-hidden="true">${nbank(o)||nsvg(o.kind)}</span><div><strong>${sanitize(o.name)}</strong><small>${d<0?(-d>=60?'Vencido · '+Math.floor(-d/30)+' meses':'Vencido · '+(-d)+(-d===1?' día':' días')):d===0?'Vence hoy':d===1?'Vence mañana':'En '+d+' días'}</small></div><span class="v988-amt"><b>${money(o.amount,o.currency,2)}</b><em>Pagar</em></span></button>`;
 }).join('');
 const spendingItems=spendAlerts.map(a=>`<article class="v36-notice v123-bell-alert"><span class="v1280-ico v1280-spend" aria-hidden="true">${nsvg('spend')}</span><div><strong>${sanitize(a.category)} · ${a.kind==='trend'?'Tendencia al alza':'Gasto elevado'}</strong><small>${sanitize(v123AlertText(a))}</small></div></article>`).join('');
 const v994Reports=(()=>{try{return v246ReportEvents()}catch(_){return []}})();const v994AllRead=v994Reports.length>0&&v994Reports.every(r=>v994.r.has(r.id));
 const totalAlerts=urgent+spendAlerts.length+(v994AllRead?0:v246UnreadReportCount());
 const v994HasAny=items||spendingItems||(!v994AllRead&&v994Reports.length>0);
 return `<details class="v36-notifications"><summary aria-label="Notificaciones: ${totalAlerts} avisos">${svg}${totalAlerts?`<span class="v36-notification-count">${totalAlerts>99?'99+':totalAlerts}</span>`:''}</summary><div class="v36-notice-pop"><div class="v36-notice-head"><div><strong>Notificaciones</strong><small>Los informes aparecen a medida que cierra cada período</small></div>${v994HasAny?'<button type="button" class="v994-clear" data-v994-clear="1">Limpiar todo</button>':''}</div>${v994AllRead?'':'<div class="v1280-sec">Informes</div>'+v216BellItems()}${spendingItems?'<div class="v1280-sec">Alertas de gasto</div>'+spendingItems:''}${items?'<div class="v1280-sec">Próximos vencimientos</div>'+items:''}${v994HasAny?'':'<p class="v994-empty">No tienes notificaciones pendientes.</p>'}<p class="v36-notice-disclaimer">Los informes de la campanita se habilitan por fecha y hora; no equivalen a notificaciones push cuando la app está cerrada. Los recordatorios de vencimientos se configuran por separado.</p></div></details>`;
}
function mobileHeader(){
 if(ui.page!=='overview')return '';
 const pageName={pressure:'Presión financiera',overview:'Inicio',cards:'Tarjetas',mobilehub:'Explorar',mobilesearch:'Buscar',settings:'Ajustes',banks:'Instituciones',accounts:'Cuentas',register:'Movimientos',payments:'Compromisos',income:'Ingresos',budget:'Presupuestos',recurring:'Suscripciones',personal:'Entre personas',loans:'Préstamos',certificates:'Certificados',benefits:'Beneficios',advanced:'Analítica',kpis:'Indicadores',patrimony:'Patrimonio',categories:'Categorías'};
 return `<header class="vive-mobile-top" aria-label="Encabezado móvil"><button class="vive-mobile-brand" type="button" data-v119-open="1" aria-label="vive el hoy · Abrir El costo de mañana" title="Abrir El costo de mañana">${brandMark()}</button><span class="vive-mobile-location">${ui.page==='cards'?'Wallet':ui.page==='banks'?'Bancos':(ui.page==='wallet'?'Wallet':pageName[ui.page])||'Tus finanzas'}</span><div class="v65-header-tools v146-mobile-actions">${v402SyncButton()}${v36Bell()}${window.VIVE_ENABLED===false?'':`<button type="button" class="vive-mobile-head-access" data-vive-open="mobile" aria-label="Abrir Vive" title="Vive"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19.414 14.414C21 12.828 22 11.5 22 9.5a5.5 5.5 0 0 0-9.591-3.676.6.6 0 0 1-.818.001A5.5 5.5 0 0 0 2 9.5c0 2.3 1.5 4 3 5.5l5.535 5.362a2 2 0 0 0 2.879.052 2.12 2.12 0 0 0-.004-3 2.124 2.124 0 1 0 3-3 2.124 2.124 0 0 0 3.004 0 2 2 0 0 0 0-2.828l-1.881-1.882a2.41 2.41 0 0 0-3.409 0l-1.71 1.71a2 2 0 0 1-2.828 0 2 2 0 0 1 0-2.828l2.823-2.762"/></svg></button>`}<button type="button" class="v65-settings-button v271-settings-access ${ui.page==='settings'?'active':''}" data-act="navigate" data-id="settings" aria-label="Abrir Configuración" title="Configuración"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06-1.91 1.91-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.52V20h-3v-.08a1.65 1.65 0 0 0-1-1.52 1.65 1.65 0 0 0-1.82.33l-.06.06-1.91-1.91.06-.06A1.65 1.65 0 0 0 7.6 15a1.65 1.65 0 0 0-1.52-1H6v-3h.08A1.65 1.65 0 0 0 7.6 10a1.65 1.65 0 0 0-.33-1.82l-.06-.06 1.91-1.91.06.06A1.65 1.65 0 0 0 11 6.6a1.65 1.65 0 0 0 1-1.52V5h3v.08A1.65 1.65 0 0 0 16 6.6a1.65 1.65 0 0 0 1.82-.33l.06-.06 1.91 1.91-.06.06A1.65 1.65 0 0 0 19.4 10a1.65 1.65 0 0 0 1.52 1H21v3h-.08A1.65 1.65 0 0 0 19.4 15Z" transform="translate(-1.5 -0.5) scale(1.05)"/></svg></button></div></header>`;
}
/* Momentos · adaptador: convierte el estado financiero ya cargado en un snapshot para el motor (sin red ni consultas). */
function vMomentosSnapshot(){
 const t=today(),s={verified:false,overdue:[],upcoming:[],cuts:[],pressure:null,improving:null,goals:[]};
 try{
  s.verified=!!(db&&((db.cards||[]).length||(db.accounts||[]).length||(db.loans||[]).length||(db.transactions||[]).length));
  const short=u=>String(u.name||'Compromiso').replace(/\s·\s(DOP|USD)$/,'');
  for(const u of (upcoming()||[]).filter(x=>x&&x.date&&num(x.amount)>0)){
   const n=diffDays(u.date,t),it={id:u.id,name:short(u),days:n,go:u.kind==='card'?'wallet':'pressure'};
   if(n<0)s.overdue.push(it);else if(n<=7)(u.kind==='card'?s.cuts:s.upcoming).push(it);
  }
  const y=Number(t.slice(0,4)),m=Number(t.slice(5,7)),cur=monthlyTotals(y,m),pm=m===1?[y-1,12]:[y,m-1],prev=monthlyTotals(pm[0],pm[1]);
  const net=num(cur.income)-num(cur.expense),pnet=num(prev.income)-num(prev.expense);
  if(num(cur.income)>0&&num(cur.expense)>num(cur.income))s.pressure={income:money(cur.income),expense:money(cur.expense)};
  if((num(prev.income)||num(prev.expense))&&net>0&&net>pnet)s.improving={net:money(net),prev:money(pnet)};
  try{if(window.__viveIntel&&window.__viveIntel.forMomentos)s.discoveries=window.__viveIntel.forMomentos()}catch(_){}
  /* Metas: VIVE aún no registra metas; se mostrarán aquí cuando existan datos reales. */
 }catch(err){}
 return s;
}
window.ViveMomentosHost={snapshot:vMomentosSnapshot,icon:name=>icon(name),go:id=>{const b=document.createElement('button');b.type='button';b.dataset.act='navigate';b.dataset.id=id;b.hidden=true;document.body.appendChild(b);b.click();b.remove()}};

/* Dock tipo Apple Music: al desplazar hacia abajo se compacta en [Inicio] [pestaña activa] [Buscar]; al subir o tocar la pestaña activa se expande. */
let vDockCompact=false;
(function(){
 let lastY=window.scrollY||0,acc=0;
 const set=on=>{if(vDockCompact===on)return;vDockCompact=on;document.querySelector('.vive-mobile-dock')?.classList.toggle('is-compact',on)};
 window.addEventListener('scroll',()=>{
  if(!window.matchMedia('(max-width:790px)').matches)return;
  const y=window.scrollY||0,d=y-lastY;lastY=y;
  if(y<24){acc=0;set(false);return}
  acc=(d>0)===(acc>0)?acc+d:d;
  if(acc>14)set(true);else if(acc<-10)set(false);
 },{passive:true});
})();
/* Cápsula del Centro Estratégico (dock compacto): muestra el momento más relevante y abre Momentos. */
function vDockCenter(){
 const m=window.ViveMomentos?window.ViveMomentos.top():{title:'Todo tranquilo',icon:'sparkles',tone:'calm'};
 return `<button type="button" class="vive-mobile-dock-center vdc-${m.tone}" data-momentos-open="1" aria-haspopup="dialog" aria-label="Abrir Momentos: ${sanitize(m.title)}. Tu centro estratégico"><span class="vdc-ico">${icon(m.icon)}</span><span class="vdc-text"><strong>${sanitize(m.title)}</strong><small>Tu centro estratégico</small></span><span class="vdc-chev">${icon('arrow')}</span></button>`;
}
function mobileBottomNavigation(){
 if((window.scrollY||0)<24)vDockCompact=false;
 // Cada producto bancario pertenece al espacio Bancos; no debe marcar Explorar por error.
 const bankingPages=['banks','accounts','cards','loans','certificates','benefits'];
 const current=ui.page==='cards'?'wallet':bankingPages.includes(ui.page)?'banks':(['overview','wallet','mobilehub','mobilesearch'].includes(ui.page)?ui.page:'mobilehub');
 const items=[['overview','Inicio','home'],['wallet','Wallet','card'],['banks','Bancos','landmark'],['mobilehub','Explorar','grid'],['mobilesearch','Buscar','search']];
 return `<nav class="vive-mobile-dock${vDockCompact?' is-compact':''}" data-current="${current}" aria-label="Navegación móvil">${items.map(([id,label,ic])=>`<button type="button" class="vive-mobile-dock-item ${current===id?'active':''}" data-act="navigate" data-id="${id}" ${current===id?'aria-current="page"':''} aria-label="${label}" title="${label}"><span class="vive-mobile-dock-icon">${icon(ic)}</span><span class="vive-mobile-dock-label">${label}</span></button>${id==='overview'?vDockCenter():''}`).join('')}</nav><button type="button" class="v249-register-fab" data-act="newTransaction" aria-label="Registrar una operación" title="Registrar ingresos, egresos, transferencias y pagos"><span class="v249-fab-surface" aria-hidden="true">${icon('plus')}</span></button>`;
}

function mobileMiniTrend(){
 const ref=dateObj(ui.month+'-01');const months=Array.from({length:5},(_,i)=>{let d=new Date(ref.getFullYear(),ref.getMonth()-(4-i),1),x=monthlyTotals(d.getFullYear(),d.getMonth()+1);return {m:d.toLocaleDateString('es-DO',{month:'short'}).replace('.',''),income:x.income,expense:x.expense}});
 const max=Math.max(1,...months.flatMap(m=>[m.income,m.expense]));
 const current=monthlyTotals(ref.getFullYear(),ref.getMonth()+1);
 const monthName=ref.toLocaleDateString('es-DO',{month:'long',year:'numeric'});
 return `<div class="v348-trend-block"><div class="vive-mobile-mini-trend" role="img" aria-label="Comparación de ingresos y egresos de los últimos cinco meses">${months.map(m=>`<div class="vive-mobile-trend-group" title="${m.m}: Ingresos ${money(m.income)} · Egresos ${money(m.expense)}"><div class="vive-mobile-trend-bars"><span class="vive-mobile-trend-in" style="height:${Math.max(5,m.income/max*100)}%"></span><span class="vive-mobile-trend-out" style="height:${Math.max(5,m.expense/max*100)}%"></span></div><small>${m.m}</small></div>`).join('')}</div><div class="v348-trend-legend" aria-label="Resumen del mes seleccionado: ${sanitize(monthName)}"><span class="v348-trend-total"><i class="v348-trend-dot income" aria-hidden="true"></i><span>Ingresos</span><strong>${money(current.income)}</strong></span><span class="v348-trend-total"><i class="v348-trend-dot expense" aria-hidden="true"></i><span>Egresos</span><strong>${money(current.expense)}</strong></span></div></div>`;
}

/* V64 · Total de saldo por naturaleza: no confundir deuda íntegra con cuotas por vencer. */
function v64CommitmentTotals(){
 const cards=(db.cards||[]).reduce((sum,c)=>sum+fx(cardStatus(c,'DOP').debt,'DOP')+fx(cardStatus(c,'USD').debt,'USD'),0);
 const loans=(db.loans||[]).reduce((sum,l)=>sum+fx(loanAccounting(l).balance,l.currency),0);
 const personal=(db.personalLoans||[]).filter(l=>l.direction==='borrowed').reduce((sum,l)=>sum+fx(personalBalance(l),l.currency),0);
 const monthly=v80RecurringMonthly();
 return {card:rnd(cards),loan:rnd(loans),personal:rnd(personal),recurring:rnd(monthly)};
}
function v64DueSummary(kind,amount){
 return `${kind==='recurring'?'Costo mensual equivalente':'Saldo total pendiente'}: ${money(amount)}`;
}
/* V64 · Comparación con último mes cerrado hasta que exista base interanual en 2027. */
function v64PositionComparison(){
 const now=today(),year=Number(now.slice(0,4));
 const yoy=positionYearOverYear();
 if(year>=2027&&yoy.valid)return {prior:yoy.prior,position:yoy.position,valid:true,label:'año anterior',short:'vs. '+yoy.prior.slice(0,4)};
 const d=dateObj(now);const lastDay=new Date(d.getFullYear(),d.getMonth(),0);
 const prior=monthDay(lastDay.getFullYear(),lastDay.getMonth()+1,lastDay.getDate());
 const historical=[...(db.accounts||[]).map(a=>a.opened),...(db.cards||[]).map(c=>c.opened),...(db.loans||[]).map(l=>plusMonths(l.firstDue||today(),-1)),...(db.certificates||[]).map(c=>c.startDate),...(db.personalLoans||[]).map(l=>l.date),...(db.transactions||[]).map(t=>t.date)].filter(Boolean);
 const valid=historical.some(t=>t<=prior);
 return {prior,position:valid?historicalPosition(prior):null,valid,label:'mes anterior',short:'cambio mensual'};
}



