document.addEventListener('click',e=>{const b=e.target.closest?.('[data-v985-pane]');if(b)v242SettingsPane=b.dataset.v985Pane;},true);
/* V1121 · Anticipar: cada fila abre primero el selector de qué pagar y luego el flujo de pago existente. */
function v1121Go(act,id,ccy){const b=document.createElement('button');b.type='button';b.dataset.act=act;b.dataset.id=String(id);if(ccy)b.dataset.ccy=ccy;b.hidden=true;document.body.append(b);b.click();b.remove()}
function v1121Pay(kind){
 const nav=(page,msg)=>{toast(msg);ui.page=page;render()};
 try{
  if(kind==='card'){
   const cards=(db.cards||[]).filter(c=>c&&!c.archived&&!isHidden(c)&&!/debit|debito/.test(String([c.type,c.cardType,c.kind].join(' ')).toLowerCase()));
   if(!cards.length)return nav('cards','No tienes tarjetas de crédito registradas.');
   window.openRegisterProductPicker('Selecciona la tarjeta a pagar',cards.map(item=>({type:'cardId',item})),'',o=>v1121Go('payCard',o.value));
  }else if(kind==='loan'){
   const loans=(db.loans||[]).filter(l=>l&&!l.archived&&!isHidden(l));
   if(!loans.length)return nav('loans','No tienes préstamos activos.');
   window.openRegisterProductPicker('Selecciona el préstamo a pagar',loans.map(item=>({type:'loanId',item})),'',o=>v1121Go('payLoan',o.value));
  }else if(kind==='recurring'){
   const list=(typeof v339ActiveRecurring==='function'?v339ActiveRecurring():(db.recurring||[]).filter(r=>r.active!==false&&!r.archived));
   if(!list.length)return nav('recurring','No tienes suscripciones activas.');
   window.openItemPicker('Selecciona la suscripción a pagar',list.map(r=>({value:r.id,name:r.name,iconHtml:v45SubIcon(r,'small'),detail:[r.nextDue?prettyDate(r.nextDue):'',r.category].filter(Boolean).join(' · '),amount:money(num(r.amount),r.currency||'DOP',2)})),id=>v1121Go('payRecurring',id));
  }else{
   const list=(db.personalLoans||[]).filter(l=>l&&!l.archived&&personalBalance(l)>.005);
   if(!list.length)return nav('personal','No tienes saldos pendientes con personas.');
   window.openItemPicker('Selecciona la persona',list.map(l=>({value:l.id,name:l.person,detail:l.direction==='lent'?'Te debe':'Le debes',amount:money(personalBalance(l),l.currency||'DOP',2)})),id=>v1121Go('payPersonal',id));
  }
 }catch(err){console.warn('V1121',err);}
}
/* V1127 · Próximos vencimientos: tocar uno abre directamente su pago (tarjeta, préstamo, suscripción o persona). */
function v1127Target(key){
 const m=/^(?:debt|overdue):(card|loan|recurring|personal):(.+?)(?::(DOP|USD))?:(\d{4}-\d{2}-\d{2})$/.exec(String(key||''));
 if(!m)return null;
 const act={card:'payCard',loan:'payLoan',recurring:'payRecurring',personal:'payPersonal'}[m[1]];
 return act?{act,id:m[2],ccy:m[3]||''}:null;
}
document.addEventListener('click',e=>{const r=e.target.closest?.('[data-v1127-pay]');if(!r)return;const t=v1127Target(r.dataset.v1127Pay);if(!t)return;e.preventDefault();e.stopPropagation();document.getElementById('v361-pressure-day-dialog')?.remove();document.body.classList.remove('v361-pressure-open');v1121Go(t.act,t.id,t.ccy)},true);
/* V1126 · Radar: tocar un tramo (0–7, 8–15, 16–30 días) abre el desglose de sus vencimientos, igual que el calendario. */
function v1126OpenDueRange(i){
 const limits=[7,15,30],labels=['0–7 días','8–15 días','16–30 días'];
 const from=v119DateAfter(i?limits[i-1]+1:0),end=v119DateAfter(limits[i]);
 const events=(v119Baseline(30).events||[]).filter(e=>e.type==='expense'&&num(e.amount)>0&&e.date>=from&&e.date<=end).sort((a,b)=>String(a.date).localeCompare(String(b.date)));
 const total=events.reduce((t,e)=>t+num(e.amount),0);
 document.getElementById('v361-pressure-day-dialog')?.remove();
 const rows=events.map(e=>{const pay=v1127Target(e.key);return `<article class="v361-pressure-item${pay?' v1127-payable':''}" ${pay?`data-v1127-pay="${sanitize(e.key)}" role="button" tabindex="0"`:''}><div><strong>${sanitize(e.name||'Compromiso')}</strong><span>${sanitize(prettyDate(e.date))}${pay?' · Toca para pagar':''}</span></div><b>${v318Money(num(e.amount))}</b></article>`}).join('');
 const dialog=document.createElement('div');dialog.id='v361-pressure-day-dialog';dialog.className='v361-pressure-overlay';
 dialog.innerHTML=`<div class="v361-pressure-backdrop" data-v361-pressure-close="1"></div><section role="dialog" aria-modal="true" aria-labelledby="v361-pressure-title" class="v361-pressure-sheet"><header><div><small>RADAR DE VENCIMIENTOS · ${labels[i]}</small><h2 id="v361-pressure-title">${labels[i]}</h2></div><button type="button" data-v361-pressure-close="1" aria-label="Cerrar desglose">×</button></header><div class="v361-pressure-main"><span>Compromisos previstos</span><strong>${v318Money(total)}</strong><small>${events.length} ${events.length===1?'compromiso':'compromisos'} en este tramo</small></div><div class="v361-pressure-list">${rows||'<p class="v360-pressure-empty">No hay obligaciones en este tramo.</p>'}</div><footer><button type="button" data-v361-pressure-close="1">Cerrar</button></footer></section>`;
 document.body.appendChild(dialog);document.body.classList.add('v361-pressure-open');dialog.querySelector('.v361-pressure-sheet header button')?.focus();
}
document.addEventListener('click',e=>{const c=e.target.closest?.('[data-v1126-bucket]');if(!c)return;e.preventDefault();e.stopPropagation();v361PressureLastFocus=c;v1126OpenDueRange(Number(c.dataset.v1126Bucket))},true);
document.addEventListener('keydown',e=>{const c=e.target.closest?.('[data-v1126-bucket]');if(c&&(e.key==='Enter'||e.key===' ')){e.preventDefault();v1126OpenDueRange(Number(c.dataset.v1126Bucket))}});
/* V1125 · Radar de vencimientos: el botón «Pagar» pregunta qué vencimiento pagar y abre el pago. */
function v1125PayUpcoming(){
 let list=[];try{list=(upcoming()||[]).filter(u=>u&&u.action&&u.ref).slice(0,40)}catch(e){}
 if(!list.length){toast('No tienes pagos próximos.');return}
 const map=new Map(list.map((u,i)=>[String(i),u]));
 window.openItemPicker('Selecciona qué pagar',list.map((u,i)=>({value:String(i),name:u.name,...(u.kind==='recurring'&&(db.recurring||[]).find(r=>String(r.id)===String(u.ref))?{iconHtml:v45SubIcon((db.recurring||[]).find(r=>String(r.id)===String(u.ref)),'small')}:{}),detail:prettyDate(u.date)+(u.kind==='card'?' · Tarjeta':u.kind==='loan'?' · Préstamo':u.kind==='recurring'?' · Suscripción':''),amount:money(num(u.amount),u.currency||'DOP',2)})),i=>{const u=map.get(String(i));if(u)v1121Go(u.action,u.ref,u.ccy)});
}
document.addEventListener('click',e=>{if(!e.target.closest?.('[data-v1125-pay]'))return;e.preventDefault();e.stopPropagation();v1125PayUpcoming()},true);
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-v1121-pay]');if(!b)return;e.preventDefault();e.stopPropagation();v1121Pay(b.dataset.v1121Pay)},true);
/* V1129 · Widget «Salario anticipado»: registra desde Inicio el cobro de un ingreso recurrente (nómina) antes de su fecha. */
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-v1129-start]');if(!b)return;e.preventDefault();e.stopPropagation();
 /* Registrar cobro anticipado: abre el registro del cobro de la fuente recurrente (formal primero, luego la de fecha más cercana); la fuente se puede cambiar dentro del formulario. */
 try{v40Ensure();const list=(db.incomeSchedules||[]).filter(x=>x&&x.active!==false&&x.nextDue).sort((a,c)=>(a.kind==='formal'?0:1)-(c.kind==='formal'?0:1)||String(a.nextDue).localeCompare(String(c.nextDue)));
  if(list.length)v940IncomeCaptureForm(list[0].id,'advance');else v40IncomeForm()}catch(err){console.warn('V1129',err)}},true);
