/* V371 · Rentabilidad de tarjeta, lectura anual sin asientos duplicados.
   Beneficios = solo acreditaciones monetarias reales vinculadas a la tarjeta.
   Comparación = anualidad del año registrada, o contrato anual si aún no se cobró.
   No se agrega la anualidad a transacciones ni se valoran puntos / millas / perks. */
function v371CardReturn(c){
 const year=String(today()).slice(0,4), tx=(db.transactions||[]).filter(t=>t.cardId===c.id && String(t.date||'').startsWith(year));
 const configuredAmount=num(c.annualFeeAmount) || num(c.annualFeeDOP) || num(c.annualFeeUSD);
 const configuredCurrency=c.annualFeeCurrency || (num(c.annualFeeUSD)>0&&num(c.annualFeeDOP)<=0?'USD':'DOP');
 const feeRows=tx.filter(t=>['card_charge','expense'].includes(t.type) && (t.chargeKind==='annual_fee' || /anualidad|membres[ií]a/i.test(String(t.subcategory||''))));
 const rewardRows=tx.filter(t=>['card_reward','bank_reward'].includes(t.type));
 const rate=num(db.settings?.fx);
 const needsFx=(configuredAmount>0&&configuredCurrency==='USD')||[...feeRows,...rewardRows].some(t=>t.currency==='USD'&&num(t.amount)>0);
 const missingRate=needsFx&&!(rate>0);
 const asDop=t=>num(t.amount)*(t.currency==='USD'?rate:1);
 const feeActual=rnd(feeRows.reduce((sum,t)=>sum+asDop(t),0));
 const configured=rnd(configuredAmount*(configuredCurrency==='USD'?rate:1));
 // Si ya hubo un cargo real este año, se utiliza ese importe como costo de referencia.
 const annual=feeActual>0?feeActual:configured;
 const benefit=rnd(rewardRows.reduce((sum,t)=>sum+asDop(t),0));
 const net=rnd(benefit-annual);
 const roi=!missingRate&&annual>0?rnd(net/annual*100):null;
 return {year,annual,configured,hasConfigured:configuredAmount>0,benefit,net,roi,missingRate,feeConfirmed:feeActual>0,hasAnnual:configuredAmount>0||feeActual>0};
}
function v371CardReturnWidget(c,consolidatedCards=null,bankView=false,walletPc=false){
 const compact=bankView||walletPc;
 const d=consolidatedCards?(()=>{
  const rows=consolidatedCards.map(v371CardReturn);
  const annual=rnd(rows.reduce((s,x)=>s+x.annual,0)),benefit=rnd(rows.reduce((s,x)=>s+x.benefit,0)),net=rnd(benefit-annual);
  const missingRate=rows.some(x=>x.missingRate),hasAnnual=rows.some(x=>x.hasAnnual);
  const configured=rnd(rows.reduce((sum,row)=>sum+row.configured,0));
  return {year:String(today()).slice(0,4),annual,configured,hasConfigured:rows.some(x=>x.hasConfigured),benefit,net,roi:!missingRate&&annual>0?rnd(net/annual*100):null,missingRate,hasAnnual,feeConfirmed:rows.every(x=>x.hasAnnual&&x.feeConfirmed),unconfigured:rows.filter(x=>!x.hasAnnual).length};
 })():v371CardReturn(c);
 const cost=d.missingRate?'—':d.hasAnnual?money(d.annual,'DOP',2):'Sin definir';
 const benefit=d.missingRate?'—':money(d.benefit,'DOP',2);
 const net=d.missingRate||!d.hasAnnual?'—':`${d.net>0?'+':''}${money(d.net,'DOP',2)}`;
 const percentage=d.roi===null?'—':`${d.roi>0?'+':''}${new Intl.NumberFormat('es-DO',{maximumFractionDigits:1}).format(d.roi)}%`;
 const tone=d.missingRate||!d.hasAnnual?'':(d.net>0?'positive':d.net<0?'negative':'');
 const benefitId=consolidatedCards?'all':sanitize(c.id);
 const inWallet=ui.page==='wallet'&&!bankView;
 const walletCards=consolidatedCards||[c];
 const walletActions=inWallet&&walletCards.length&&!(walletPc&&!isMobileViewport())?`<div class="wallet-return-actions">
  <button type="button" data-act="walletReturnEntry" data-mode="benefit" data-id="${benefitId}">${icon('gift2')}<span>Registrar beneficio</span>${icon('arrow')}</button>
  <button type="button" data-act="walletReturnEntry" data-mode="annual" data-id="${benefitId}">${icon('shield')}<span>Anualidad y seguros</span>${icon('arrow')}</button>
 </div>`:'';
 // El resumen móvil de Bancos tiene su propia jerarquía, sin alterar Wallet ni PC.
 if(bankView&&isMobileViewport()&&ui.page==='banks')return `<section class="v371-card-return vBanks-mobile-return" aria-label="Beneficios y retorno">
  <h2><button type="button" class="vBanksPc-benefits-link" data-v144-action="open-benefits" data-id="${benefitId}">${icon('gift2')}Beneficios y retorno ${icon('arrow')}</button></h2>
  <div class="vBanks-return-main ${tone}"><div><small>Retorno neto</small><strong ${vBanksAmountSize(net)}>${net}</strong></div><span class="vBanks-return-percent">${percentage}</span></div>
  <div class="vBanks-return-secondary"><div><small>Anualidad configurada</small><strong ${vBanksAmountSize(d.hasConfigured?money(d.configured,'DOP',2):'Sin definir')}>${d.missingRate?'—':d.hasConfigured?money(d.configured,'DOP',2):'Sin definir'}</strong></div><div class="${d.benefit>0?'positive':''}"><small>Beneficios recibidos</small><strong ${vBanksAmountSize(benefit)}>${benefit}</strong></div></div>
  <p class="v371-return-note">${d.missingRate?'Falta la tasa RD$/US$ para calcular el retorno.':!d.hasAnnual?'Configura la anualidad para calcular el retorno.':d.feeConfirmed?'Retorno sobre anualidades cobradas.':d.unconfigured?'Retorno sobre anualidades conocidas · '+d.unconfigured+' sin definir.':d.annual!==d.configured?'Retorno sobre anualidades cobradas o configuradas.':'Retorno estimado sobre anualidades configuradas.'}</p>
 </section>`;
 const title=compact?`<h2><button type="button" class="vBanksPc-benefits-link" data-v144-action="open-benefits" data-id="${benefitId}">${icon('gift2')}Beneficios y retorno ${icon('arrow')}</button></h2>`:`<h2>${inWallet?icon('gift2'):''}Beneficios y retorno</h2>`;
 return `<section class="v266-wallet-panel v371-card-return${walletPc?' vWalletPc-panel vWalletPc-return':''}" aria-label="Retorno anual de beneficios de ${sanitize(c.name)}">
 <div class="v371-return-heading"><div>${inWallet?'':`<span class="v266-overline">BENEFICIOS · ${d.year}</span>`}${title}</div>${compact?'':`<button type="button" class="v371-return-action" data-v144-action="open-benefits" data-id="${benefitId}" aria-label="Abrir beneficios de ${sanitize(c.name)}">${icon('arrow')}</button>`}</div>
 <div class="v371-return-values">
 <div class="v371-return-tile">${inWallet?icon('card'):compact?`<span class="v371-rt-ico is-card">${icon('card')}</span>`:''}<small>Anualidad</small><strong>${compact&&!inWallet?(d.missingRate?'—':d.hasConfigured?money(d.configured,'DOP',2):'Sin definir'):cost}</strong></div>
 <div class="v371-return-tile${inWallet&&d.benefit>0||compact&&d.benefit>0?' positive':''}">${inWallet?icon('gift2'):compact?`<span class="v371-rt-ico is-gift">${icon('gift2')}</span>`:''}<small>Beneficios</small><strong>${benefit}</strong></div>
 <div class="v371-return-tile ${tone}"><small>${bankView?'Retorno neto':'Retorno'}</small><strong>${net}</strong></div>
 <div class="v371-return-tile ${tone}"><small>Retorno %</small><strong>${percentage}</strong></div>
 </div>
 ${walletActions}
 <p class="v371-return-note">${d.missingRate?'Falta la tasa RD$/US$ para calcular el retorno.':!d.hasAnnual?'Configura la anualidad desde Gestionar para calcular el retorno.':consolidatedCards&&d.unconfigured?'Retorno sobre anualidades conocidas · '+d.unconfigured+' sin definir.':d.feeConfirmed?'Retorno = beneficios monetarios acreditados − anualidad cobrada.':consolidatedCards?'Retorno consolidado sobre anualidades cobradas o configuradas; no implica un cargo realizado.':'Retorno estimado respecto a la anualidad configurada; no implica un cargo realizado.'}</p>
 </section>`;
}

