function shellKpi(title,v,foot,ico,tone=''){return `<div class="kpi"><div class="kpi-head">${sanitize(title)}<span class="kpi-icon">${icon(ico)}</span></div><div class="kpi-value ${tone}">${v}</div><div class="kpi-foot">${foot}</div></div>`}


const MONTHS_FULL=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
function smoothPath(points){if(!points.length)return '';let path=`M ${points[0][0]} ${points[0][1]}`;for(let i=1;i<points.length;i++){let prev=points[i-1],cur=points[i],mid=(prev[0]+cur[0])/2;path+=` C ${mid} ${prev[1]}, ${mid} ${cur[1]}, ${cur[0]} ${cur[1]}`}return path}
function glassTrend(year){const data=Array.from({length:12},(_,i)=>monthlyTotals(year,i+1)),curYear=nowYear(),monthLimit=year===curYear?nowMonth():year>curYear?0:12;const w=1000,h=440,left=42,right=974,top=38,bottom=385,usable=bottom-top;let max=Math.max(100,...data.flatMap((d,i)=>i<monthLimit?[d.income,d.expense]:[]));max*=1.18;const x=i=>left+(right-left)*i/11,y=v=>bottom-Math.max(0,v)/max*usable;let active=data.map((d,i)=>({...d,i})).filter(d=>d.i<monthLimit);let a=active.map(d=>[x(d.i),y(d.income)]),b=active.map(d=>[x(d.i),y(d.expense)]);let pa=smoothPath(a),pb=smoothPath(b);let areaA=pa?`${pa} L ${a[a.length-1][0]} ${bottom} L ${a[0][0]} ${bottom} Z`:'';let areaB=pb?`${pb} L ${b[b.length-1][0]} ${bottom} L ${b[0][0]} ${bottom} Z`:'';let guides=[0,.25,.5,.75,1].map(v=>`<line x1="${left}" x2="${right}" y1="${y(v*max)}" y2="${y(v*max)}" class="trend-grid"/><text x="${left-12}" y="${y(v*max)+4}" class="trend-axis" text-anchor="end">${shorten(v*max)}</text>`).join('');let points=active.map(d=>`<g class="trend-point" tabindex="0" role="img" data-chart-tip="${MONTHS_FULL[d.i]} ${year}|Ingresos: ${money(d.income)}|Egresos: ${money(d.expense)}|Neto: ${money(d.net)}" aria-label="${MONTHS_FULL[d.i]}: ingresos ${money(d.income)}, egresos ${money(d.expense)}"><line x1="${x(d.i)}" x2="${x(d.i)}" y1="${top}" y2="${bottom}" class="trend-guide"/><circle cx="${x(d.i)}" cy="${y(d.income)}" r="5" class="trend-income-point"/><circle cx="${x(d.i)}" cy="${y(d.expense)}" r="5" class="trend-expense-point"/><rect x="${x(d.i)-27}" y="${top}" width="54" height="${bottom-top}" fill="transparent"/><title>${MONTHS_FULL[d.i]}: ingresos ${money(d.income)} · egresos ${money(d.expense)} · neto ${money(d.net)}</title></g>`).join('');return `<div class="trend-wrap"><svg class="trend-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Evolución mensual de ingresos y egresos de ${year}. Valores en pesos dominicanos."><defs><linearGradient id="glassIncome" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#2276e8" stop-opacity=".19"/><stop offset="100%" stop-color="#2276e8" stop-opacity="0"/></linearGradient><linearGradient id="glassExpense" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#ef8572" stop-opacity=".10"/><stop offset="100%" stop-color="#ef8572" stop-opacity="0"/></linearGradient></defs>${guides}<path d="${areaA}" fill="url(#glassIncome)"/><path d="${areaB}" fill="url(#glassExpense)"/><path d="${pa}" fill="none" stroke="#287df2" stroke-width="3.5" stroke-linecap="round"/><path d="${pb}" fill="none" stroke="#eb8b7c" stroke-width="3.5" stroke-linecap="round"/>${points}${MONTHS_FULL.map((m,i)=>`<text x="${x(i)}" y="${bottom+27}" text-anchor="middle" class="trend-month ${i===nowMonth()-1&&year===curYear?'current':''}">${m.slice(0,3)}</text>`).join('')}</svg></div><div class="trend-legend"><span><i class="legend-line income"></i>Ingresos</span><span><i class="legend-line expenses"></i>Egresos</span><span class="chart-currency">Consolidado en RD$</span></div>`}



/* V357 · Sólo presentación de tablas de Analítica. No modifica datos ni sumas. */
function v357AdvancedNumber(value){
 const n=Number(value)||0, a=Math.abs(n), fmt=(x,d)=>new Intl.NumberFormat('es-DO',{maximumFractionDigits:d,minimumFractionDigits:0}).format(x);
 let short=a>=1e9?fmt(a/1e9,1)+'B':a>=1e6?fmt(a/1e6,1)+'M':a>=1e3?fmt(a/1e3,1)+'K':fmt(a,a<100?2:0);
 if(n<0&&a>0)short='−'+short;
 const full=money(n,'DOP',2);
 return `<span class="v357-compact-num" title="${sanitize(full)}" aria-label="${sanitize(full)}">${short}</span>`;
}
function compactAnnualSummary(opts={}){
 const data=Array.from({length:12},(_,i)=>monthlyTotals(ui.year,i+1));
 const limit=ui.year===nowYear()?nowMonth():ui.year<nowYear()?12:0;
 const rows=[['Ingresos','income'],['Egresos','expense'],['Neto','net'],['Saldo final','ending']];
 const cell=(key,i)=>i>=limit?'<span class="quiet">—</span>':`<span title="${MON[i]} ${ui.year} · ${money(data[i][key])}">${opts.inAdvanced?v357AdvancedNumber(data[i][key]):matrixAmount(data[i][key])}</span>`;
 return `<section class="summary-glass compact-balance refined-balance matrix-fit ${opts.inAdvanced?'v19-flat-summary':''}"><div class="summary-panel-header"><div><span class="summary-tag">BALANCE ANUAL · ${ui.year}</span><h2><span class="v20-table-currency" title="Valores en pesos dominicanos" aria-label="Pesos dominicanos">RD$</span> Un año, cuatro cifras.</h2><p>Lectura mensual · valores en <b>RD$</b>; símbolo discreto junto a cada importe</p></div><div class="hstack"><button class="year-btn" data-act="prevYear" aria-label="Año anterior">‹</button><strong class="year-label">${ui.year}</strong><button class="year-btn" data-act="nextYear" aria-label="Año siguiente">›</button>${!opts.inAdvanced?`<button class="section-arrow" data-act="navigate" data-id="advanced" title="Desglose avanzado">${icon('arrow')}</button>`:''}</div></div>
 <div class="table-wrap matrix-scroll refined-table-wrap"><table class="annual-table compact-grid matrix-numeric" aria-label="Resumen mensual en RD$"><colgroup><col class="matrix-name-col"/>${Array.from({length:12},()=>'<col/>').join('')}<col class="matrix-tail-col"/><col class="matrix-tail-col"/></colgroup><thead><tr><th>Concepto</th>${MON.map(m=>`<th>${m}</th>`).join('')}<th>Total</th><th>Prom.</th></tr></thead><tbody>${rows.map(([label,key])=>{const values=data.slice(0,limit).map(r=>r[key]);const total=values.reduce((a,b)=>a+b,0);const average=values.length?total/values.length:0;return `<tr class="v27-balance-${key} ${key==='net'?'sum':key==='ending'?'ending':''}"><td>${label}</td>${data.map((_,i)=>`<td class="matrix-num">${cell(key,i)}</td>`).join('')}<td class="matrix-num">${key==='ending'?'—':(opts.inAdvanced?v357AdvancedNumber(total):matrixAmount(total))}</td><td class="matrix-num">${opts.inAdvanced?v357AdvancedNumber(average):matrixAmount(average)}</td></tr>`}).join('')}</tbody></table></div><p class="matrix-footnote">Cifras compactas: K = miles, M = millones. Pasa el cursor o enfoca cada cifra para ver el importe completo; las sumas y los promedios no cambian.</p></section>`;
}


/* NUEVA EXPERIENCIA VISIÓN: usa datos existentes y no crea movimientos. */
function visionCompactNumber(value){const n=Number(value)||0,abs=Math.abs(n);return abs>=1e6?(n/1e6).toFixed(1)+'M':abs>=1e3?Math.round(n/1e3)+'K':Math.round(n).toLocaleString('es-DO');}


/* VISIÓN · La gráfica representa la posición neta histórica, no el saldo de cuentas. */
function visionPositionHistory(monthCount=6, currentPosition=null){
 const count=[3,5,6,12].includes(Number(monthCount))?Number(monthCount):6;
 const now=dateObj(today()),year=now.getFullYear(),month=now.getMonth();
 const rows=Array.from({length:count},(_,i)=>{
  const date=new Date(year,month-(count-1-i),1);
  const cutoff=i===count-1?today():periodEnd(date.getFullYear(),date.getMonth()+1);
  const historical=i===count-1&&Number.isFinite(currentPosition)?currentPosition:(v14HistoricalAvailable(cutoff)?historicalPosition(cutoff).net:null);
  return {date,cutoff,value:historical};
 });
 const observed=rows.filter(x=>Number.isFinite(x.value)).map(x=>x.value);
 if(!observed.length)return {graph:'<div class="vision-empty">Añade productos y movimientos para ver la evolución de tu posición neta.</div>',rows};
 let min=Math.min(...observed),max=Math.max(...observed);
 const padding=Math.max(1,Math.abs(max-min)*.15,Math.abs(max)*.055);
 min-=padding;max+=padding;
 const X=i=>58+(count===1?0:i*576/(count-1));
 const Y=v=>154-(v-min)/(max-min)*114;
 const dots=rows.map((row,i)=>Number.isFinite(row.value)?{x:X(i),y:Y(row.value),row,i}:null).filter(Boolean);
 const path=dots.map((p,i)=>`${i?'L':'M'}${p.x.toFixed(2)} ${p.y.toFixed(2)}`).join(' ');
 const fill=dots.length>1?`${path} L ${dots[dots.length-1].x.toFixed(2)} 155 L ${dots[0].x.toFixed(2)} 155 Z`:'';
 const years=[...new Set(rows.map(r=>r.date.getFullYear()))];
 const graph=`<svg class="vision-liquid-chart vision-net-chart" viewBox="0 0 676 203" preserveAspectRatio="none" role="img" aria-label="Evolución de la posición neta registrada de ${years.join(' a ')} en RD$">
  <defs><linearGradient id="vision-position-area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#25e8a5" stop-opacity=".20"/><stop offset="1" stop-color="#25e8a5" stop-opacity="0"/></linearGradient></defs>
  ${Array.from({length:4},(_,i)=>{const value=max-i*(max-min)/3,y=Y(value);return `<line class="vision-gridline" x1="58" y1="${y.toFixed(2)}" x2="649" y2="${y.toFixed(2)}"/><text class="vision-axis" x="7" y="${(y+5).toFixed(2)}">${visionCompactNumber(value)}</text>`}).join('')}
  ${fill?`<path d="${fill}" fill="url(#vision-position-area)"/>`:''}
  <path d="${path}" fill="none" stroke="#1bdf98" stroke-width="3.8" stroke-linecap="round" stroke-linejoin="round"/>
  ${dots.map(p=>`<circle class="vision-chart-point" cx="${p.x}" cy="${p.y}" r="5" fill="#21e4a1" stroke="#112338" stroke-width="2.8" tabindex="0" data-chart-tip="POSICIÓN NETA · ${p.row.date.toLocaleDateString('es-DO',{month:'long',year:'numeric'})}|Al cierre: ${money(p.row.value,'DOP',2)}|Activos disponibles, certificados y por cobrar menos obligaciones"/>`).join('')}
  ${rows.map((r,i)=>`<text class="vision-month" x="${X(i)}" y="192" text-anchor="middle">${r.date.toLocaleDateString('es-DO',{month:'short'}).replace('.','')}</text>`).join('')}
 </svg>`;
 return {graph,rows};
}

