function bankFigures(b){let aa=db.accounts.filter(a=>linkedBank(a,b.id)),cc=db.cards.filter(c=>linkedBank(c,b.id)),ll=db.loans.filter(l=>linkedBank(l,b.id)),certs=db.certificates.filter(c=>linkedBank(c,b.id));let liquidity=aa.reduce((sum,a)=>sum+fx(getAccountBalance(a),a.currency),0),credit=cc.reduce((sum,c)=>sum+fx(cardStatus(c,'DOP').debt,'DOP')+fx(cardStatus(c,'USD').debt,'USD'),0),loansDue=ll.reduce((sum,l)=>sum+fx(loanStatus(l).balance,l.currency),0);let investment=certs.reduce((sum,c)=>sum+fx(certificateCapital(c),c.currency),0);return {aa,cc,ll,certs,liquidity,credit,loansDue,investment,benefits:bankBenefits(b.id),net:liquidity+investment-credit-loansDue}}
function banks(){return vBanksDashboard();}
document.addEventListener('click',e=>{const button=e.target.closest?.('[data-v176-bank-detail]');if(!button)return;e.preventDefault();const root=button.closest('.bank-workspace'),target=root?.querySelector('.product-columns,.v40-head,.v40-rows');target?.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});},true);
/* V1264 · Historial de una institución: lo que ha entrado y salido por mes, con línea de evolución y cifras clave. Solo lectura. */
function v1264BankFlows(b){
 const accIds=new Set(db.accounts.filter(a=>a.bankId===b.id).map(a=>a.id)),cardIds=new Set(db.cards.filter(c=>c.bankId===b.id).map(c=>c.id)),m=new Map();
 const add=(d,k,v)=>{const key=String(d).slice(0,7);if(!/^\d{4}-\d{2}$/.test(key))return;const r=m.get(key)||{in:0,out:0};r[k]+=v;m.set(key,r)};
 for(const t of db.transactions||[]){
  const v=txDop(t);if(!(v>0))continue;
  const fromB=accIds.has(t.accountId),toB=accIds.has(t.toAccountId);
  if(t.type==='income'){if(fromB)add(t.date,'in',v)}
  else if(t.type==='transfer'){if(toB&&!fromB)add(t.date,'in',v);else if(fromB&&!toB)add(t.date,'out',v)}
  else if(t.type==='expense'||t.type==='loan_payment'||t.type==='personal_payment'){if(fromB)add(t.date,'out',v);else if(cardIds.has(t.cardId))add(t.date,'out',v)}
  else if(t.type==='card_charge'||t.type==='card_advance'){if(cardIds.has(t.cardId))add(t.date,'out',v)}
 }
 return [...m].sort((x,y)=>x[0].localeCompare(y[0])).map(([k,r])=>({k,...r}));
}
function v1264BankHistory(b){
 const all=v1264BankFlows(b),range=ui.bankHistoryRange||12,rows=range===0?all:all.slice(-range);
 const mn=k=>{const d=dateObj(k+'-01');return d.toLocaleDateString('es-DO',{month:'short'}).replace('.','')+" '"+k.slice(2,4)};
 const tin=rows.reduce((n,r)=>n+r.in,0),tout=rows.reduce((n,r)=>n+r.out,0),net=tin-tout,n=Math.max(1,rows.length);
 const peak=rows.slice().sort((a,c)=>c.in-a.in)[0],hi=rows.slice().sort((a,c)=>c.out-a.out)[0];
 const rng=[[6,'6 meses'],[12,'12 meses'],[0,'Todo']].map(([v,l])=>`<button type="button" data-act="bankHistoryRange" data-id="${v}" class="${range===v?'is-on':''}">${l}</button>`).join('');
 const kpi=(l,v,sub,cls='')=>`<div class="v1264-kpi ${cls}"><small>${l}</small><strong>${v}</strong>${sub?`<em>${sub}</em>`:''}</div>`;
 let chart='<p class="v1264-empty">Todavía no hay movimientos en esta institución.</p>';
 if(rows.length){
  const W=720,H=230,pl=48,pr=16,pt=16,pb=30,max=Math.max(1,...rows.map(r=>Math.max(r.in,r.out)))*1.1,X=i=>pl+(W-pl-pr)*(rows.length===1?.5:i/(rows.length-1)),Y=v=>pt+(H-pt-pb)*(1-v/max);
  const line=k=>rows.map((r,i)=>(i?'L':'M')+X(i).toFixed(1)+' '+Y(r[k]).toFixed(1)).join(' ');
  const area=k=>line(k)+` L${X(rows.length-1).toFixed(1)} ${H-pb} L${X(0).toFixed(1)} ${H-pb} Z`;
  const grid=[0,.25,.5,.75,1].map(z=>`<line x1="${pl}" x2="${W-pr}" y1="${(pt+(H-pt-pb)*z).toFixed(1)}" y2="${(pt+(H-pt-pb)*z).toFixed(1)}" class="v1264-grid"/><text x="${pl-8}" y="${(pt+(H-pt-pb)*z+4).toFixed(1)}" text-anchor="end" class="v1264-ax">${shorten(max*(1-z))}</text>`).join('');
  const step=Math.ceil(rows.length/8),xl=rows.map((r,i)=>i%step===0||i===rows.length-1?`<text x="${X(i).toFixed(1)}" y="${H-8}" text-anchor="middle" class="v1264-ax">${mn(r.k)}</text>`:'').join('');
  const dots=(k,c)=>rows.map((r,i)=>`<circle cx="${X(i).toFixed(1)}" cy="${Y(r[k]).toFixed(1)}" r="3.5" class="${c}"><title>${mn(r.k)} · ${k==='in'?'Entró':'Salió'} ${money(r[k])}</title></circle>`).join('');
  chart=`<svg viewBox="0 0 ${W} ${H}" class="v1264-svg" role="img" aria-label="Entradas y salidas por mes de ${sanitize(b.name)}"><defs><linearGradient id="v1264gi" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--v424-accent-strong)" stop-opacity=".28"/><stop offset="1" stop-color="var(--v424-accent-strong)" stop-opacity="0"/></linearGradient></defs>${grid}${xl}<path d="${area('in')}" fill="url(#v1264gi)"/><path d="${line('in')}" class="v1264-lin"/><path d="${line('out')}" class="v1264-lout"/>${dots('in','v1264-din')}${dots('out','v1264-dout')}</svg>`;
 }
 const table=rows.slice().reverse().slice(0,12).map(r=>`<div class="v1264-row"><b>${dateObj(r.k+'-01').toLocaleDateString('es-DO',{month:'long',year:'numeric'})}</b><span class="in">+${money(r.in)}</span><span class="out">−${money(r.out)}</span><strong class="${r.in-r.out<0?'neg':''}">${r.in-r.out<0?'−':'+'}${money(Math.abs(r.in-r.out))}</strong></div>`).join('');
 return `<section class="v1264-hist" aria-label="Historial de ${sanitize(b.name)}"><header><div><small>HISTORIAL · ${sanitize(b.name).toUpperCase()}</small><h3>Lo que ha entrado y lo que ha salido</h3></div><div class="v1264-range" role="group" aria-label="Periodo">${rng}</div></header>
 <div class="v1264-kpis">${kpi('ENTRÓ',money(tin),rows.length+' '+(rows.length===1?'mes':'meses'),'in')}${kpi('SALIÓ',money(tout),'Promedio '+money(tout/n)+' al mes','out')}${kpi('FLUJO NETO',(net<0?'−':'+')+money(Math.abs(net)),net>=0?'Entró más de lo que salió':'Salió más de lo que entró',net<0?'neg':'')}${kpi('MES DE MAYOR ENTRADA',peak?money(peak.in):'—',peak?dateObj(peak.k+'-01').toLocaleDateString('es-DO',{month:'long',year:'numeric'}):'')}${kpi('MES DE MAYOR SALIDA',hi?money(hi.out):'—',hi?dateObj(hi.k+'-01').toLocaleDateString('es-DO',{month:'long',year:'numeric'}):'')}</div>
 <div class="v1264-chart"><div class="v1264-leg"><span class="in">Entradas</span><span class="out">Salidas</span></div>${chart}</div>
 ${rows.length?`<div class="v1264-table"><div class="v1264-row v1264-head"><b>Mes</b><span>Entró</span><span>Salió</span><strong>Neto</strong></div>${table}</div>`:''}
 <p class="v1264-note">Incluye ingresos y transferencias de las cuentas de esta institución, gastos, pagos de préstamos y consumos con sus tarjetas. Los pagos a tarjeta no se cuentan para no duplicar el consumo.</p></section>`;
}
function vBanksPcCardConsumption(cards,mobile=false){
 const byType=new Map();
 const {totals}=v1301WalletConsumption(cards,byType);
 const detailRows=[...byType].sort((a,b)=>b[1].equivalent-a[1].equivalent||a[0].localeCompare(b[0],'es'));
 const rows=true?detailRows:(()=>{
  const primary=detailRows.filter(([type])=>type!=='Otros').slice(0,4);
  const names=new Set(primary.map(([type])=>type));
  const remaining=detailRows.filter(([type])=>!names.has(type));
  const other=remaining.reduce((a,[,v])=>({DOP:a.DOP+v.DOP,USD:a.USD+v.USD,equivalent:a.equivalent+v.equivalent,missingFx:a.missingFx||v.missingFx}),{DOP:0,USD:0,equivalent:0,missingFx:false});
  return [...primary,['Otros',other]];
 })();
 const comparable=!totals.missingFx&&totals.equivalent>0&&rows.every(([,amount])=>amount.equivalent>=0);
 const palette=['#008c6e','#187bd7','#9143d8','#d99402','#7286a1'];
 const chart=mobile&&comparable?`<div class="vBanks-consumption-chart" role="img" aria-label="Consumo total ${money(totals.equivalent)}"><svg viewBox="0 0 120 120" aria-hidden="true"><circle cx="60" cy="60" r="48" fill="none" stroke="var(--bank-track)" stroke-width="13"/>${rows.reduce((state,[,amount],i)=>{
  const share=100*amount.equivalent/totals.equivalent;
  state.html+=`<circle cx="60" cy="60" r="48" fill="none" stroke="${palette[i%palette.length]}" stroke-width="13" pathLength="100" stroke-dasharray="${share} 100" stroke-dashoffset="${-state.offset}" transform="rotate(-90 60 60)"/>`;
  state.offset+=share;return state;
 },{offset:0,html:''}).html}</svg><span><b>${money(totals.equivalent)}</b><small>Consumo total</small></span></div>`:'';
 const totalLine=!chart?`<div class="vBanksPc-consumption-total"><span>Consumo total</span><strong>${totals.missingFx?'—':money(totals.equivalent)}</strong></div>`:'';
 const body=rows.length?`<div class="vBanks-consumption-body${chart?' with-chart':''}">${chart}${totalLine}<div class="vBanksPc-consumption-rows">${rows.map(([type,amount],index)=>{
  const share=comparable?100*amount.equivalent/totals.equivalent:0;
  return `<div class="vBanksPc-crow" data-eq="${num(amount.equivalent)}" data-dop="${num(amount.DOP)}" data-usd="${num(amount.USD)}"><span class="vBanksPc-category-icon">${mobile&&chart?`<i style="--swatch:${palette[index%palette.length]}"></i>`:icon(V255_TAXONOMY.gasto.categories[type]||'bag')}</span><strong>${sanitize(type)}</strong>${comparable?`<span class="vBanksPc-meter" aria-hidden="true"><i style="--use:${Math.min(100,share)}%"></i></span>`:''}<span class="vBanksPc-consumption-amount"><b>${amount.missingFx?'—':money(amount.equivalent,'DOP',0)}</b>${amount.USD?`<small>${vWalletPcSplit(amount.DOP,amount.USD)}</small>`:''}</span>${comparable?`<small>${share.toFixed(1)}%</small>`:''}</div>`;
 }).join('')}</div></div>`:'<p class="vBanksPc-empty">Sin consumos registrados.</p>';
 return v1301ConsumptionDisclosure('Consumo por tipo','','',body,{glyph:'analytics',open:true});
}
let vBanksPcCardCycle;
const V_BANKS_ALL='__all_banks__';
const V_BANKS_GROUPS=[
 ['accounts','Cuentas','wallet','addAccount'],
 ['cards','Tarjetas','card','addCard'],
 ['loans','Préstamos','landmark','addLoan'],
 ['certificates','Certificados','layers','addCertificate']
];
let vBanksCertificateDetail,vBanksAccountDetail;

function vBanksScope(){
 const institutions=db.banks.filter(b=>(ui.showHidden||!isHidden(b))&&v61InstitutionMatches(b))
  .filter(b=>v42InstitutionFilter==='all'||v40IsFinancial(b)===(v42InstitutionFilter==='financial'));
 const selected=institutions.find(b=>b.id===ui.bankId)||null;
 const byId=new Map(institutions.map(b=>[b.id,{}]));
 const groups={};
 for(const [key] of V_BANKS_GROUPS){
  const items=db[key].filter(x=>(ui.showHidden||!isHidden(x))&&(key!=='accounts'||x.kind!=='cash'));
  groups[key]=[];
  for(const b of byId.values())b[key]=[];
  for(const item of items){
   const bucket=byId.get(item.bankId);
   if(bucket)bucket[key].push(item);
   if(bucket||(!bank(item.bankId)&&v61InstitutionProfile==='all'&&v42InstitutionFilter==='all'))groups[key].push(item);
  }
 }
 return {institutions,selected,byId,groups,active:selected?byId.get(selected.id):groups};
}
function vBanksPosition(groups){
 const sum=(items,amount)=>items.reduce((total,item)=>total+amount(item),0);
 const limits=['DOP','USD'].map(ccy=>sum(groups.cards,c=>num(c['limit'+ccy])));
 const funds=sum(groups.accounts,a=>fx(getAccountBalance(a),a.currency));
 const cardDebt=sum(groups.cards,c=>vWalletPcEquivalent(cardStatus(c,'DOP').debt,cardStatus(c,'USD').debt));
 const loanDebt=sum(groups.loans,l=>fx(loanStatus(l).balance,l.currency));
 const invested=sum(groups.certificates,c=>fx(certificateCapital(c),c.currency));
 const limit=vWalletPcEquivalent(...limits),debt=cardDebt+loanDebt;
 return {funds,cardDebt,loanDebt,invested,debt,limit,limits,net:funds+invested-debt,usage:limit>0?vWalletPcUsage(cardDebt,limit):null};
}
function vBanksSelect(id){
 ui.bankId=id===V_BANKS_ALL?null:id;
 // Solo Bancos PC: institución y categoría son filtros independientes.
 // En móvil se conserva íntegramente el comportamiento existente.
 if(isMobileViewport()||!['all',...V_BANKS_GROUPS.map(([key])=>key)].includes(ui.vBanksPcProduct))ui.vBanksPcProduct='all';
 ui.vBanksDesktopSection=null;
 ui.vBanksProductDetail=null;
 ui.vBanksPcBenefits=false;
 ui.vBanksMobileProducts=false;
}
function vBanksPicker(){
 const scope=vBanksScope();
 const items=[{value:V_BANKS_ALL,name:'Todos los bancos',detail:'Vista consolidada',iconHtml:icon('layers'),amount:money(vBanksPosition(scope.groups).net)},...scope.institutions.map(b=>({
  value:b.id,name:b.name,detail:b.kind||'Banco',institutionLogo:bankLogoSafe(b.logo),amount:money(vBanksPosition(scope.byId.get(b.id)).net)
 }))];
 window.openItemPicker('Seleccionar institución',items,id=>{
  vBanksSelect(id);render();document.querySelector('.vBanks-mobile-selector')?.focus({preventScroll:true});
 },scope.selected?.id||V_BANKS_ALL);
 if(isMobileViewport())setTimeout(()=>document.querySelector('dialog.v827-picker-backdrop')?.classList.add('vBanks-picker'),0);
}
function vBanksFlags(f){
 return f.usage===null?'—':f.usage.toFixed(1)+'%';
}
