/* V28 · Identidad visual: logos bancarios personales y tarjetas por categoría. */
const bankLogoSafe=(logo)=> typeof logo==='string' && logo.length<240000 && /^data:image\/(?:webp|png|jpeg);base64,[a-z0-9+/=]+$/i.test(logo) ? logo : '';
function bankLogoMark(b,extra=''){
 const logo=bankLogoSafe(b?.logo);
 return `<span class="bank-photo-mark ${extra}" style="--bank-color:${sanitize(b?.color||'#376bea')}" aria-label="${sanitize(b?.name||'Banco')}">${logo?`<img src="${logo}" alt="Logo de ${sanitize(b?.name||'banco')}" loading="lazy"/>`:`<span class="bank-photo-fallback">${sanitize((b?.name||'B').trim().slice(0,2).toUpperCase())}</span>`}</span>`;
}
/* V1002 · logo de la institución en tarjetas móviles de cuentas, préstamos y certificados */
function v1002BankGlyph(item,fallback){const b=bank(item?.bankId)||(item?.bank?{name:String(item.bank)}:null);return b?bankLogoMark(b,'v1002-bank-logo'):icon(fallback)}
function bankLogoInline(bankId){const b=bank(bankId);return b?bankLogoMark(b,'bank-inline-logo'):'';}
function normCardText(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();}
const CARD_TIER_NAMES={classic:'Clásica',gold:'Gold',platinum:'Platinum',black:'Black',infinite:'Infinite',signature:'Signature',world:'World',worldelite:'World Elite',diamond:'Diamond',business:'Business',titanium:'Titanium',other:'Otra categoría'};
function cardTierKey(c){
 const direct=normCardText(c?.tier),t=normCardText((c?.name||'')+' '+(c?.category||''));
 /* V960: «Clásica»/«Otra» es el valor por defecto del formulario; si el nombre o la categoría dicen
    Platinum, Gold, Black… manda el nombre para que el color corresponda a la tarjeta real. */
 if(CARD_TIER_NAMES[direct]&&!(direct==='classic'||direct==='other'))return direct;
 if(CARD_TIER_NAMES[direct]&&!/world\s*elite|infinite|infinity|infinit|signature|black|negra|centurion|platinum|platino|diamond|diamante|titanium|titanio|business|corporativa|empresarial|gold|\boro\b|\bworld\b/.test(t))return direct;
 if(/world\s*elite/.test(t))return 'worldelite';
 if(/infinite|infinity|infinit/.test(t))return 'infinite';
 if(/signature/.test(t))return 'signature';
 if(/black|negra|centurion/.test(t))return 'black';
 if(/platinum|platino/.test(t))return 'platinum';
 if(/diamond|diamante/.test(t))return 'diamond';
 if(/titanium|titanio/.test(t))return 'titanium';
 if(/business|corporativa|empresarial/.test(t))return 'business';
 if(/gold|oro/.test(t))return 'gold';
 if(/\bworld\b/.test(t))return 'world';
 if(/classic|clasica|estandar|standard/.test(t))return 'classic';
 return 'classic';
}
function cardNetworkKey(c){const direct=normCardText(c?.network),name=normCardText(c?.name);
 if(direct==='visa'||direct==='mastercard'||direct==='amex'||direct==='discover'||direct==='other')return direct;
 if(/master\s?card|master/.test(name))return 'mastercard';
 if(/american\s?express|amex/.test(name))return 'amex';
 if(/discover/.test(name))return 'discover';
 if(/\bvisa\b/.test(name))return 'visa';
 return 'other';
}
function cardNetworkMark(c){const net=cardNetworkKey(c);
 if(net==='mastercard')return `<span class="credit-network credit-network-mastercard" role="img" aria-label="Mastercard"><span class="network-circles"><svg viewBox="0 0 43 26" width="43" height="26" aria-hidden="true"><circle cx="13" cy="13" r="12.5" fill="#eb001b"/><circle cx="30" cy="13" r="12.5" fill="#f79e1b"/><path d="M21.5 3.2a12.5 12.5 0 0 1 0 19.6 12.5 12.5 0 0 1 0-19.6Z" fill="#ff5f00"/></svg></span><b>mastercard</b></span>`;
 if(net==='visa')return `<span class="credit-network credit-network-visa" role="img" aria-label="Visa">VISA</span>`;
 if(net==='amex')return `<span class="credit-network credit-network-amex" role="img" aria-label="American Express">AMEX</span>`;
 if(net==='discover')return `<span class="credit-network credit-network-discover" role="img" aria-label="Discover">DISCOVER</span>`;
 return `<span class="credit-network credit-network-generic" aria-label="Red de tarjeta">Crédito</span>`;
}
async function compressBankImage(file){
 if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Usa PNG, JPG o WebP.');
 if(file.size>5000000)throw Error('La imagen debe pesar menos de 5 MB.');
 const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(Error('No se pudo abrir la imagen.'));reader.onload=()=>{const el=new Image();el.onload=()=>resolve(el);el.onerror=()=>reject(Error('La imagen no se pudo interpretar.'));el.src=String(reader.result)};reader.readAsDataURL(file)});
 const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');
 if(!ctx)throw Error('No fue posible preparar la imagen.');
 /* Adaptación de logos sin fondo (PNG/WebP con transparencia): se recorta al contenido visible, se centra en un lienzo cuadrado y se deja un margen parejo, conservando la transparencia. */
 const iw=image.naturalWidth||image.width,ih=image.naturalHeight||image.height;
 let sx=0,sy=0,sw=iw,sh=ih;
 try{const pr=Math.min(1,256/Math.max(iw,ih)),pw=Math.max(1,Math.round(iw*pr)),ph=Math.max(1,Math.round(ih*pr)),pc=document.createElement('canvas');pc.width=pw;pc.height=ph;const px=pc.getContext('2d',{willReadFrequently:true});px.drawImage(image,0,0,pw,ph);const d=px.getImageData(0,0,pw,ph).data;let x0=pw,y0=ph,x1=-1,y1=-1,transparent=0;
  for(let y=0;y<ph;y++)for(let x=0;x<pw;x++){const al=d[(y*pw+x)*4+3];if(al<12){transparent++;continue}if(x<x0)x0=x;if(x>x1)x1=x;if(y<y0)y0=y;if(y>y1)y1=y}
  if(transparent>pw*ph*.04&&x1>=x0&&y1>=y0){sx=Math.floor(x0/pr);sy=Math.floor(y0/pr);sw=Math.min(iw-sx,Math.ceil((x1-x0+1)/pr));sh=Math.min(ih-sy,Math.ceil((y1-y0+1)/pr))}
 }catch(_){sx=0;sy=0;sw=iw;sh=ih}
 const side=192,inner=Math.round(side*(sw===iw&&sh===ih?1:.78)),k=Math.min(inner/sw,inner/sh);
 canvas.width=side;canvas.height=side;
 const dw=Math.max(1,Math.round(sw*k)),dh=Math.max(1,Math.round(sh*k));
 ctx.drawImage(image,sx,sy,sw,sh,Math.round((side-dw)/2),Math.round((side-dh)/2),dw,dh);
 const data=canvas.toDataURL('image/webp',.82);
 if(!bankLogoSafe(data))throw Error('El logo excede el tamaño permitido. Usa una imagen más pequeña.');
 return data;
}

