 return `<details class="v51-recycle"><summary>${icon('history')} Papelera · ${removed.length} movimiento${removed.length===1?'':'s'} eliminado${removed.length===1?'':'s'} <small>Puedes recuperar un registro sin duplicarlo</small></summary><div class="v51-recycle-list">${removed.slice().reverse().slice(0,30).map(rec=>`<article><div><strong>${sanitize(transactionTitle(rec.tx))}</strong><small>${prettyDate(rec.tx.date)} · ${money(rec.tx.amount,rec.tx.currency,2)} · Eliminado ${sanitize((rec.at||'').slice(0,10))}</small></div><span class="v54-trash-controls"><button type="button" data-act="v51RestoreTransaction" data-id="${rec.id}">Restaurar</button><button type="button" class="v54-permadelete" data-act="v54PurgeTrash" data-id="${rec.id}">Borrar definitivamente</button></span></article>`).join('')}</div></details>`;
