/* V235: Registrar es un asistente flotante, separado del libro de Movimientos. */
function openRegisterAssistant(){
 const root=document.getElementById('modal-root');if(!root)return;
 const reopening=Boolean(root.querySelector('.v235-register-dialog'));
 if(!reopening&&document.activeElement instanceof HTMLElement)window.v843RegistrarReturnFocus=document.activeElement;
 root.innerHTML=`<div class="modal-layer v235-register-layer" data-backdrop="true"><section class="modal v235-register-dialog" data-component="RegistrarShell" role="dialog" aria-modal="true" aria-label="Registrar: elegir operación"><div class="v235-register-close"><span>REGISTRAR</span><button type="button" class="close" data-act="closeModal" aria-label="Cerrar asistente">×</button></div>${moneyRegister('assistant')}</section></div>`;
 queueMicrotask(()=>{
  const target=reopening?root.querySelector('.vr-switch.selected'):root.querySelector('.v235-register-close .close');
  target?.focus({preventScroll:true});
 });
}
/* V843 · Control de teclado del asistente Registrar: solo mientras está abierto. */
document.addEventListener('keydown',e=>{
 const dialog=document.querySelector('#modal-root .v235-register-dialog');
 if(!dialog)return;
 if(e.key==='Escape'){
  e.preventDefault();e.stopImmediatePropagation();closeModal();return;
 }
 if(e.key!=='Tab')return;
 const focusables=[...dialog.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(x=>x.getClientRects().length&&!x.hidden);
 if(!focusables.length)return;
 const first=focusables[0],last=focusables[focusables.length-1];
 if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}
 else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}
},true);

/* ─── vive el hoy · ANÁLISIS DE EGRESOS ─────────────────────────────────
   Reconoce gastos, no movimiento bruto de efectivo. Es consistente con
   monthlyTotals(): cargos de tarjetas una sola vez, intereses/seguros de
   préstamos, intereses personales y comisiones de transferencias.
   No incorpora pagos de capital, transferencias internas ni desembolsos.
   ─────────────────────────────────────────────────────────────────── */
function expenseTransactionItems(t){
  const currency=t.currency||'DOP',base=fx(num(t.amount),currency);
  if(['expense','card_charge','card_refund'].includes(t.type)){
    const sign=t.type==='card_refund'?-1:1;
    const items=[{t,amount:sign*base,category:t.category||'Otros gastos',subcategory:t.subcategory||'Sin subcategoría',method:t.cardId?'Tarjetas de crédito':'Cuentas y efectivo',detail:t.merchant||t.description||t.note||transactionTitle(t)}];
    if(t.type==='expense')for(const [label,amount] of [['Impuesto bancario',num(t.paymentTax)],[t.paymentSpeed==='instant'?'Pago al instante':'Otros cargos bancarios',num(t.paymentFee)]])if(amount>0)items.push({t,amount:fx(amount,t.paymentFeeCurrency||account(t.accountId)?.currency||currency),category:'Impuestos y comisiones',subcategory:label,method:'Costos de la operación',detail:label+' · '+transactionTitle(t)});
    return items;
  }
  if(t.type==='card_payment'){
    return [['Impuesto bancario',num(t.paymentTax)],['Otros cargos bancarios',num(t.paymentFee)]].filter(([,amount])=>amount>0).map(([label,amount])=>({t,amount:fx(amount,t.paymentFeeCurrency||account(t.accountId)?.currency||currency),category:'Impuestos y comisiones',subcategory:label,method:'Costos del pago de tarjeta',detail:label}));
  }
  if(t.type==='loan_payment'){
    const parts=[['Intereses',t.interest],['Seguros',t.insurance],['Comisiones',t.fee]]
      .filter(([name,amount])=>num(amount)>0)
      .map(([name,amount])=>({t,amount:fx(num(amount),currency),category:'Deudas e intereses',subcategory:name,method:'Costos de préstamos',detail:loan(t.loanId)?.name||'Préstamo bancario'}));
    if(num(t.paymentTax)>0)parts.push({t,amount:fx(num(t.paymentTax),t.paymentFeeCurrency||account(t.accountId)?.currency||currency),category:'Impuestos y comisiones',subcategory:'Impuesto bancario',method:'Costos del pago de préstamo',detail:'Impuesto sobre transferencia'});
    return parts;
  }
  if(t.type==='card_advance'&&num(t.advanceFee)>0)
    return [{t,amount:fx(num(t.advanceFee),currency),category:'Deudas e intereses',subcategory:'Comisión de avance de efectivo',method:'Costos de tarjetas',detail:'Comisión '+num(t.advanceFeePct).toFixed(2)+'% · '+(card(t.cardId)?.name||'Tarjeta')}];
  if(t.type==='personal_settlement'&&personalLoan(t.personalLoanId)?.direction==='borrowed'&&num(t.interest)>0)
    return [{t,amount:fx(num(t.interest),currency),category:'Deudas e intereses',subcategory:'Intereses entre personas',method:'Costos de préstamos',detail:personalLoan(t.personalLoanId)?.person||'Préstamo personal'}];
  if(t.type==='transfer'&&num(t.transferFee)>0){const a=account(t.accountId),tax=num(t.transferTax??0),fixed=num(t.transferFixedFee??Math.max(0,t.transferFee-tax));
    return [['Impuesto bancario',tax],[t.transferSpeed==='instant'?'Pago al instante':'Otros cargos bancarios',fixed]].filter(([,amount])=>amount>0).map(([label,amount])=>({t,amount:fx(amount,a?.currency||currency),category:'Impuestos y comisiones',subcategory:label,method:'Costos de transferencia',detail:label}));
  }
  return [];
}





