/* V176: caja y cuentas agrupadas sin sumar divisas nominales. */






function previousYearPoint(ref=today()){
 const d=dateObj(ref);return monthDay(d.getFullYear()-1,d.getMonth()+1,d.getDate());
}
function historicalPosition(date){
 const accounts=db.accounts.reduce((s,a)=>s+fx(getAccountBalance(a,date),a.currency),0);
 const cardDebt=db.cards.reduce((s,c)=>{
  if((c.opened||today())>date)return s;
  const current=['DOP','USD'].reduce((total,cur)=>{
   const op=cur==='USD'?num(c.openingUSD):num(c.openingDOP);
   const changes=db.transactions.filter(t=>t.cardId===c.id&&t.currency===cur&&t.date<=date).reduce((acc,t)=>{
    if(t.type==='card_charge'||(t.type==='adjustment'&&!t.accountId)||t.type==='personal_issue'&&personalLoan(t.personalLoanId)?.direction==='lent'||t.type==='personal_settlement'&&personalLoan(t.personalLoanId)?.direction==='borrowed')return acc+num(t.amount);
    if(['card_payment','card_refund','card_reward'].includes(t.type)||t.type==='personal_issue'&&personalLoan(t.personalLoanId)?.direction==='borrowed'||t.type==='personal_settlement'&&personalLoan(t.personalLoanId)?.direction==='lent')return acc-num(t.amount);
    return acc;
   },0);
   return total+fx(Math.max(0,op+changes),cur);
  },0);
  return s+current;
 },0);
 const loans=db.loans.reduce((s,l)=>{
  const orig=plusMonths(l.firstDue||today(),-1);
  if(orig>date)return s;
  const paid=db.transactions.filter(t=>t.loanId===l.id&&t.type==='loan_payment'&&t.date<=date).reduce((a,t)=>a+num(t.principal),0);
  return s+fx(Math.max(0,num(l.principal)-paid),l.currency);
 },0);
 const investments=db.certificates.reduce((s,c)=>{
  if(c.startDate&&c.startDate>date)return s;
  const base=c.capitalMode==='pending'?db.transactions.filter(t=>t.certificateId===c.id&&t.type==='certificate_funding'&&t.date<=date).reduce((a,t)=>a+num(t.amount),0):num(c.principal);
  const redeemed=db.transactions.filter(t=>t.certificateId===c.id&&t.type==='certificate_redemption'&&t.date<=date).reduce((a,t)=>a+num(t.amount),0);
  return s+fx(Math.max(0,base-redeemed),c.currency);
 },0);
 const people=db.personalLoans.reduce((res,l)=>{
  if((l.date||today())>date)return res;
  const settled=db.transactions.filter(t=>t.personalLoanId===l.id&&t.type==='personal_settlement'&&t.date<=date).reduce((v,t)=>v+num(t.principal),0);
  const v=fx(Math.max(0,num(l.principal)-settled),l.currency);
  if(l.direction==='lent')res.receivable+=v;else res.payable+=v;
  return res;
 },{receivable:0,payable:0});
 return {liquid:accounts,debt:cardDebt+loans+people.payable,net:accounts+investments+people.receivable-cardDebt-loans-people.payable};
}
function positionYearOverYear(){
 const prior=previousYearPoint();
 const baseline=[...db.accounts.map(x=>x.opened),...db.cards.map(x=>x.opened),...db.loans.map(x=>plusMonths(x.firstDue||today(),-1)),...db.certificates.map(x=>x.startDate),...db.personalLoans.map(x=>x.date),...db.transactions.map(x=>x.date)].filter(Boolean);
 const valid=baseline.some(date=>date<=prior);
 return {prior,valid,position:valid?historicalPosition(prior):null};
}
function signedCompactAmount(value,currency='DOP',showCurrency=false){
 const a=Math.abs(num(value)),negative=num(value)<-.005;
 const v=a>=999500?
   (()=>{const m=a/1e6;return m>=9.995?m.toFixed(2)+'M':m.toFixed(1)+'M';})():
   a>=999.5?(()=>{const k=a/1e3;return k<9.95?k.toFixed(1)+'K':Math.round(k)+'K';})():
   new Intl.NumberFormat('es-DO',{maximumFractionDigits:0}).format(a);
 return (negative?'−':a>.005?'+':'')+(showCurrency?(currency==='USD'?'US$':'RD$'):'')+v;
}
function comparisonInline(percent,delta,currency='DOP'){
 const sign=percent>0?'+':'';
 const pct=Number.isFinite(percent)?sign+new Intl.NumberFormat('es-DO',{maximumFractionDigits:1,minimumFractionDigits:1}).format(percent)+'%':'—';
 return `<span class="comparison-inline"><b class="comparison-pct">${pct}</b><span class="comparison-divider" aria-hidden="true"></span><span class="comparison-amount">${signedCompactAmount(delta,currency)}</span></span>`;
}


