/* V359 · Conciliación inteligente: capital bancario ANTES del pago.
   Guarda únicamente la cuota original y una referencia de capital;
   la corrección de saldo no se considera movimiento financiero. */
function v359DailyInterest(l,balance,onDate,basis=365,form=null){
 if(!l||!(balance>=0))return {days:0,value:0,from:''};
 const id=form?.dataset?.id||'';
 const history=loanTransactions(l.id).filter(t=>t.id!==id&&t.date<onDate&&t.date<=today()).sort((a,b)=>b.date.localeCompare(a.date));
 const prev=history[0]?.date||l.lastPaidDate||l.openingBalanceDate||l.originationDate||'';
 const start=/^\d{4}-\d{2}-\d{2}$/.test(prev)?prev:onDate;
 const ms=Date.parse(onDate+'T12:00:00Z')-Date.parse(start+'T12:00:00Z');
 const days=Number.isFinite(ms)?Math.max(0,Math.round(ms/86400000)):0;
 const annual=Math.max(0,num(l.currentRate??l.rate));
 return {from:start,days,value:rnd(balance*annual/100*days/(basis===360?360:365))};
}
function v359LoanRefresh(form,changed=''){
 if(!form||form.elements.type?.value!=='loan_payment')return;
 const mode=form.elements.loanPaymentMode?.value==='bank'?'bank':'normal';
 const l=loan(form.elements.loanId?.value),block=form.querySelector('#v359BankRecon');
 if(block){block.hidden=mode!=='bank';block.querySelectorAll('input,select').forEach(el=>{el.disabled=mode!=='bank';});}
 const picker=form.querySelector('.v359-mode-picker');
 if(picker)picker.querySelectorAll('[data-v359-mode]').forEach(b=>{const chosen=b.dataset.v359Mode===mode;b.classList.toggle('selected',chosen);b.setAttribute('aria-pressed',chosen?'true':'false')});
 if(form.elements.bankBalanceBefore)form.elements.bankBalanceBefore.required=mode==='bank';
 const isExtra=form.elements.paymentKind?.value==='extra';
 if(isExtra&&mode==='bank'){
  form.elements.loanPaymentMode.value='normal';return v359LoanRefresh(form,'paymentKind');
 }
 const pre=form.elements.bankBalanceBefore?.value||'';
 const bal=pre!==''?Number(pre):NaN;
 const overview=form.querySelector('#v359BankPreview');
 if(mode!=='bank'||!l||!overview)return;
 const simulated=loanAccounting(l).balance;
 const rateBasis=form.elements.interestCalcBasis?.value==='360'?360:365;
 const result=Number.isFinite(bal)&&bal>=0?v359DailyInterest(l,bal,form.elements.date?.value||today(),rateBasis,form):null;
 if(result){
  // Auto-complete estimate on switching mode/bank amount/date, but NEVER overwrite
  // interest or principal manually edited by the user.
  const intField=form.elements.interest,prinField=form.elements.principal;
  if(intField&&!form.dataset.v359EditedInterest&&form.elements.interestSource?.value!=='bank_confirmed'&&['mode','bankBalanceBefore','interestCalcBasis','date','loanId'].includes(changed))intField.value=result.value.toFixed(2);
  const amount=num(form.elements.amount?.value),interest=num(intField?.value),extras=num(form.elements.insurance?.value)+num(form.elements.fee?.value);
  if(prinField&&!form.dataset.v359EditedPrincipal&&['mode','amount','bankBalanceBefore','interestCalcBasis','date','loanId','interest','insurance','fee'].includes(changed))prinField.value=Math.max(0,rnd(amount-interest-extras)).toFixed(2);
  if(intField&&changed==='principal'&&!form.dataset.v359EditedInterest)intField.value=Math.max(0,rnd(amount-num(prinField?.value)-extras)).toFixed(2);
 }
 const delta=Number.isFinite(bal)?rnd(bal-simulated):0;
 overview.innerHTML=Number.isFinite(bal)&&bal>=0?`<div class="v359-preview-row"><span>Saldo estimado por la app</span><strong>${money(simulated,l.currency,2)}</strong></div><div class="v359-preview-row"><span>Capital informado por el banco</span><strong>${money(bal,l.currency,2)}</strong></div><div class="v359-preview-row"><span>Diferencia de conciliación</span><strong>${money(delta,l.currency,2)}</strong></div><div class="v359-preview-row"><span>Interés diario orientativo (${result.days} días, base ${rateBasis})</span><strong>${money(result.value,l.currency,2)}</strong></div><small>Interés orientativo, no acreditado por el banco. Ajusta el desglose según tu comprobante; el saldo no genera un segundo pago.</small>`:'<small>Escribe el saldo de capital ANTES de pagar para comparar con la aplicación.</small>';
}
document.addEventListener('click',e=>{
 const b=e.target.closest?.('[data-v359-mode]');if(!b)return;
 const f=b.closest('form');if(!f||f.id!=='transactionForm')return;
 e.preventDefault();const input=f.elements.loanPaymentMode;if(!input)return;
 const previousMode=input.value;
 input.value=b.dataset.v359Mode;delete f.dataset.v359EditedInterest;delete f.dataset.v359EditedPrincipal;
 if(previousMode==='bank'&&input.value==='normal'){
  // Restore the contractual app estimate; don't keep the bank-mode daily estimate
  // in a normal payment after changing the choice.
  const l=loan(f.elements.loanId?.value),st=l?loanStatus(l):null;
  if(st&&f.elements.interest){f.elements.interest.value=Math.max(0,st.estimatedInterest).toFixed(2);
   const amt=num(f.elements.amount?.value),over=num(f.elements.insurance?.value)+num(f.elements.fee?.value);
   if(f.elements.principal)f.elements.principal.value=Math.max(0,rnd(amt-num(f.elements.interest.value)-over)).toFixed(2);
  }
 }
 v359LoanRefresh(f,'mode');refreshLegacyLoanPayment();
});
