 if(kind==='loan'){const receiptExtra=left.querySelector('#v49PaymentBreakdown');if(receiptExtra)right.appendChild(receiptExtra);const extraText=right.querySelector('.other-studio-aside-label');if(extraText)extraText.textContent='CUOTA · DETALLE VALIDADO';}
