function v31Ensure(){
 if(!db.smart360||typeof db.smart360!=='object')db.smart360={};
 const s=db.smart360;
 for(const k of ['bankRows','bankBalances','planned','fxHistory','docs','audit'])if(!Array.isArray(s[k]))s[k]=[];
 if(!s.options||typeof s.options!=='object')s.options={};
 return s;
}
