  if(!changes.length){f33Stamp=String(v405Revision);if(!f33Dirty)try{localStorage.removeItem(f33CloudKey())}catch(_){};f33SetStatus('ok','✓ Sin cambios pendientes en Supabase');return;}
  // Comparación lineal, sin modificar las reglas de eliminación o autorización.
  const savedTransactionIds=new Set((snapshot.transactions||[]).map(t=>String(t.id)));
  const removed=(v405Base.transactions||[]).filter(t=>!savedTransactionIds.has(String(t.id)));
