function v40IncomeRow(s){let p;try{p=v40Payroll(s,s.nextDue)}catch(e){p={net:0,staleRule:true}}const auto=s.postingMode==='auto',due=s.nextDue<=today();return `<div class="v40-row"><div><strong>${sanitize(s.name)}</strong><small>${sanitize(s.kind==='formal'?'Nómina formal':'Ingreso independiente')} · ${sanitize(s.frequency==='semi_monthly'?'Quincenal · 15 y último día':s.frequency==='weekly'?'Semanal':s.frequency==='quarterly'?'Trimestral':s.frequency==='annual'?'Anual':'Mensual')} · Próximo ${prettyDate(s.nextDue)}<br/>${sanitize(bank(s.institutionId)?.name||'Sin institución')} · ${sanitize(account(s.accountId)?.name||'Sin cuenta')}${p.staleRule?' · Revisar reglas fiscales del año':''}</small></div><div class="v40-row-actions"><span class="v40-pill ${auto?'good':'manual'}">${auto?'Auto al sincronizar':'Confirmación'}</span><b>${money(p.net,s.currency,2)}</b>${s.active!==false&&!auto?`<button class="btn sm soft" data-v40-action="confirmIncome" data-id="${s.id}">${s.kind==='formal'?(due?'Confirmar salario':'Registrar salario anticipado'):(due?'Confirmar cobro':'Registrar cobro anticipado')}</button>`:''}${s.active!==false?`<button class="btn sm ghost" data-v40-action="v940Additional" data-id="${s.id}">+ Ingreso adicional</button>`:''}<button class="btn sm ghost" data-v40-action="editIncome" data-id="${s.id}">Editar</button><button class="btn sm ghost" data-v40-action="toggleIncome" data-id="${s.id}">${s.active===false?'Activar':'Pausar'}</button></div></div>`}
function v40IncomeBreakdown(s){let p;try{p=v40Payroll(s,s.nextDue);}catch(e){return '';}const paid=db.transactions.filter(t=>t.incomeScheduleId===s.id).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8);return `<details class="v40-breakdown"><summary>Desglose estimado · bruto, AFP, SFS, ISR y neto</summary><div class="v40-break-grid">${[['Bruto del período',p.gross],['AFP',p.afp],['SFS',p.sfs],['ISR / Retención',p.isr],['Otros descuentos',p.other],['Neto estimado',p.net]].map(([n,v])=>`<div><small>${n}</small><b>${money(v,s.currency,2)}</b></div>`).join('')}</div>${paid.length?`<div class="v40-past"><strong>Depósitos contabilizados</strong>${paid.map(t=>`<p>${prettyDate(t.date)} · ${money(t.amount,t.currency,2)} · ${sanitize(t.postingOrigin||'Registrado')} · ISR de ese recibo: ${money(t.payrollSnapshot?.isr||0,t.currency,2)}</p>`).join('')}</div>`:'<p class="v40-one">Todavía sin depósitos contabilizados.</p>'}</details>`;}
function v40IncomeSection(){
 v40Ensure();const active=db.incomeSchedules.filter(x=>x.active!==false),formal=active.filter(x=>x.kind==='formal'),informal=active.filter(x=>x.kind!=='formal');
 let monthExpected=0;for(const s of active){try{const payroll=v40Payroll(s,today());monthExpected+=fx(payroll.net*v80MonthlyFactor(s.frequency),s.currency);}catch(e){}}
 return `<section class="v40-shell" id="v40-income-schedules"><div class="v40-head"><div><h3>Ingresos recurrentes y nómina</h3><p>Tu calendario real de cobros, impuestos estimados y depósitos confirmados.</p></div><button class="btn" data-v40-action="addIncome">+ Programar ingreso</button></div>
 <div class="v40-grid"><div class="v40-tile"><small>FUENTES ACTIVAS</small><strong>${active.length}</strong><p>${formal.length} empleos formales · ${informal.length} fuentes independientes</p></div><div class="v40-tile"><small>NETO MENSUAL ESTIMADO</small><strong>${money(monthExpected)}</strong><p>Proyección RD$ equivalente; no se suma al balance hasta registrar depósito.</p></div><div class="v40-tile"><small>PRÓXIMO INGRESO</small><strong>${active.length?prettyDate(active.slice().sort((a,b)=>a.nextDue.localeCompare(b.nextDue))[0].nextDue):'—'}</strong><p>Confirmación manual o asiento al sincronizar, según cada fuente.</p></div></div>
 <div class="v40-rows">${db.incomeSchedules.length?db.incomeSchedules.map(s=>v40IncomeRow(s)+v40IncomeBreakdown(s)).join(''):'<div class="v40-empty">Todavía no hay fuentes programadas. Agrega tu empleo o una actividad periódica para construir el calendario de ingresos.</div>'}</div><div class="v40-note">El modo automático registra un asiento contable previsto, no verifica un depósito bancario. Los cambios de salario o reglas fiscales solo afectan vencimientos futuros; cada ingreso generado conserva su desglose y tasa de cambio de registro.</div></section>`;
}

function v40IncomeOccurrence(s,due){
 const parts=(db.transactions||[]).filter(t=>t.type==='income'&&t.incomeScheduleId===s.id&&(
  t.incomeOccurrenceDate===due||(!t.incomeOccurrenceDate&&t.scheduleKey===`income:${s.id}:${due}`)));
 const received=rnd(parts.reduce((total,t)=>total+num(t.amount),0));
 const snap=parts.find(t=>num(t.incomeOccurrenceExpected)>0);
 const estimated=num(snap?.incomeOccurrenceExpected)||num(v40Payroll(s,due).net);
 // Legacy single-post settlements were completed even when actual pay differed from estimate.
 const closed=parts.some(t=>t.incomeOccurrenceCompleted===true||(!t.incomeOccurrenceDate&&t.scheduleKey===`income:${s.id}:${due}`));
 return {parts,received,expected:rnd(estimated),remaining:closed?0:rnd(Math.max(0,estimated-received))};
}
function v40IncomePost(s,due,actualNet,actualDate='',note='',mode='auto',targetAccountId=''){
 if(!/^\d{4}-\d{2}-\d{2}$/.test(String(due||'')))throw Error('Vencimiento de ingreso inválido.');
 if(mode==='auto'&&due>today())throw Error('No se puede generar automáticamente un ingreso futuro.');
 const day=actualDate||due;if(day>today()||!/^\d{4}-\d{2}-\d{2}$/.test(String(day)))throw Error('La fecha efectiva del depósito debe ser actual o pasada.');
 const a=account(targetAccountId||s.accountId);
 if(!a||a.archived||bank(a.bankId)?.archived||a.currency!==s.currency||!(num(actualNet)>0))throw Error('La cuenta de destino o el importe recibido no es válido.');
 const occurrence=v40IncomeOccurrence(s,due),value=rnd(actualNet);
 if(!(occurrence.remaining>.005))return false;
 if(value>occurrence.remaining+.005)throw Error('Este cobro supera el saldo pendiente de '+money(occurrence.remaining,s.currency,2)+'. Registra cualquier excedente como ingreso laboral adicional.');
 if(mode==='auto'&&occurrence.parts.length)return false; // No completar a ciegas un depósito parcial.
 const completed=occurrence.remaining-value<=.005;
 const key=`income:${s.id}:${due}`;
 const snap=occurrence.parts[0]?.incomeOriginalPayroll||v40Payroll(s,due);
 // Each installment owns its proportional historical payroll snapshot, so partial receipts
 // never multiply the gross or withholding amounts in payroll analytics.
 const ratio=occurrence.expected>0?value/occurrence.expected:0;
 const scaled={...snap};
 for(const fld of ['gross','afp','sfs','isr','other','generalOther','companyOther'])scaled[fld]=rnd(num(snap[fld])*ratio);
 scaled.net=value;
 scaled.companyItems=(snap.companyItems||[]).map(x=>({...x,amount:rnd(num(x.amount)*ratio),...(x.interest!=null?{interest:rnd(num(x.interest)*ratio)}:{})}));
 const tx={id:uuid(),created:new Date().toISOString(),type:'income',date:day,amount:value,currency:s.currency,
  accountId:a.id,category:s.kind==='formal'?'Salario y nómina':'Negocios y ventas',
  subcategory:s.kind==='formal'?'Sueldo recurrente':'Ingreso recurrente',note:(note||s.name).slice(0,180),
  reviewed:mode!=='auto',incomeScheduleId:s.id,incomeOccurrenceDate:due,
  incomeOccurrenceExpected:occurrence.expected,incomeOriginalPayroll:{...snap,companyItems:(snap.companyItems||[]).map(x=>({...x}))},incomeOccurrenceCompleted:completed,incomeInstallment:occurrence.parts.length+1,
  scheduleKey:completed&&!occurrence.parts.length?key:key+':part:'+uuid(),
  postingOrigin:mode==='auto'?'automático estimado':day<due?'cobro anticipado':'confirmado',
  payrollSnapshot:{...scaled,sourceName:s.name,institutionName:bank(s.institutionId)?.name||'',institutionId:s.institutionId||'',accountName:a.name,expectedDate:due,actualNet:value,actualDate:day,mode,kind:s.kind,partial:!completed||occurrence.parts.length>0},
  fxRateSnapshot:db.settings.fx};
 db.transactions.push(tx);
 if(completed){s.nextDue=v40IncomeNext(due,s.frequency);s.lastPostedAt=new Date().toISOString();s.lastPostedDate=day;}
 return completed?'completed':'partial';
}
