/* V48 · Análisis por fuente: solo movimientos REALES registrados, nunca proyecciones futuras. */
function v48SourceTotals(source){
 const tx=db.transactions.filter(t=>t.type==='income'&&t.date<=today()&&(source==='__oneoff'?!t.incomeScheduleId:t.incomeScheduleId===source.id));
 const toDop=(v,t)=>t.currency==='USD'?num(v)*num(t.fxRateSnapshot||db.settings.fx):num(v);
 const sum=items=>items.reduce((x,t)=>x+toDop(t.amount,t),0);
 const received=sum(tx),month=ui.month||today().slice(0,7),byMonth=Array.from({length:12},(_,i)=>sum(tx.filter(t=>t.date.startsWith(month.slice(0,4)+'-'+String(i+1).padStart(2,'0')))));
 const tax=tx.reduce((n,t)=>n+toDop(t.payrollSnapshot?.isr||0,t),0);
 const deductions=tx.reduce((n,t)=>n+toDop((t.payrollSnapshot?.afp||0)+(t.payrollSnapshot?.sfs||0)+(t.payrollSnapshot?.isr||0)+(t.payrollSnapshot?.other||0),t),0);
 const m=tx.filter(t=>t.date.startsWith(month)),current=sum(m);
 return {tx,received,byMonth,tax,deductions,current,month,total:tx.length};
}
function v48SourceChart(values){const max=Math.max(1,...values);return `<div class="v48-month-chart">${values.map((v,i)=>`<div title="${MONTHS_FULL[i]}: ${money(v)}"><span style="height:${Math.max(v>0?4:1,(v/max)*94)}%"></span><small>${MONTHS_FULL[i].slice(0,3)}</small></div>`).join('')}</div>`;}
function v48IncomeSources(){
 v40Ensure();const sources=[...db.incomeSchedules,{id:'__oneoff',name:'Ingresos puntuales',kind:'informal',active:true,nextDue:'',currency:'DOP'}];
 const selected=ui.v48SourceId||'';
 const items=sources.map(s=>{const d=v48SourceTotals(s.id==='__oneoff'?'__oneoff':s);return {s,d};});
 const detail=items.find(x=>x.s.id===selected);
 return `<section class="v48-source-shell"><header class="v48-source-head"><div><span class="v48-eyebrow">INGRESOS · ANÁLISIS POR ORIGEN</span><h3>Ingresos por fuente</h3><p>Selecciona un trabajo, negocio o ingreso puntual para ver sus cobros, impuestos, descuentos y evolución, sin incluir montos futuros.</p></div><button type="button" class="btn sm soft" data-act="navigate" data-id="advanced">Abrir Analítica avanzada →</button></header>
 <div class="v48-source-cards">${items.map(({s,d})=>`<button type="button" data-v48-source="${sanitize(s.id)}" class="v48-source-card ${selected===s.id?'selected':''}"><span class="v48-source-dot">${s.kind==='formal'?'▣':s.id==='__oneoff'?'＋':'↗'}</span><span><strong>${sanitize(s.name)}</strong><small>${s.kind==='formal'?'Nómina formal':s.id==='__oneoff'?'Sin programación':'Ingreso independiente'} · ${d.total} cobro(s)</small></span><b>${money(d.received)}</b></button>`).join('')}</div>
 ${detail?`<article class="v48-source-detail"><div class="v48-detail-top"><div><span class="v48-eyebrow">DETALLE EJECUTIVO · COBROS CONTABILIZADOS</span><h3>${sanitize(detail.s.name)}</h3><p>${detail.s.kind==='formal'?'Nómina formal · impuestos y descuentos según los comprobantes reales':'Actividad independiente · descuentos según cada registro'}</p></div><button type="button" class="btn sm ghost" data-v48-source="">Cerrar</button></div>
 <div class="v48-source-metrics"><div><small>RECIBIDO EN EL MES</small><strong>${money(detail.d.current)}</strong></div><div><small>ACUMULADO REGISTRADO</small><strong>${money(detail.d.received)}</strong></div><div><small>DEDUCCIONES REGISTRADAS</small><strong>${money(detail.d.deductions)}</strong></div><div><small>DEPÓSITOS CONTABILIZADOS</small><strong>${detail.d.total}</strong></div></div>
 <div class="v48-source-graph"><strong>Evolución mensual · ${detail.d.month.slice(0,4)}</strong>${v48SourceChart(detail.d.byMonth)}</div>
 <div class="v48-real-movements"><strong>Últimos ingresos realmente contabilizados</strong>${detail.d.tx.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8).map(t=>`<div><span>${prettyDate(t.date)} · ${sanitize(t.note||'Ingreso')}<small>${t.payrollSnapshot?' · Deducciones del recibo: '+money((t.payrollSnapshot.afp||0)+(t.payrollSnapshot.sfs||0)+(t.payrollSnapshot.isr||0)+(t.payrollSnapshot.other||0),t.currency,2):''}</small></span><b>${money(t.amount,t.currency,2)}</b></div>`).join('')||'<p class="v48-helper">Aún no hay depósitos: no se suman ingresos solamente programados.</p>'}</div></article>`:
 `<p class="v48-helper">Elige una fuente para consultar su evolución, los cobros reales y las deducciones. Los ingresos programados no afectan el saldo antes del día de cobro.</p>`}
 </section>`;
}
const v48PrevDecorate=v40Decorate;
v40Decorate=function(){v48PrevDecorate();if(ui.page==='income')document.getElementById('page')?.insertAdjacentHTML('afterbegin',v48IncomeSources());};
document.addEventListener('click',function(ev){const button=ev.target.closest?.('[data-v48-source]');if(!button)return;ev.preventDefault();ev.stopImmediatePropagation();ui.v48SourceId=button.dataset.v48Source||'';render();document.querySelector('.v48-source-shell')?.scrollIntoView({block:'start',behavior:'smooth'});},true);



/* V49 · Formularios contextuales / cálculos reactivos: laptop e iPhone. */
function v49UpdateLoanForm(form){
 if(!form?.elements?.months)return;
 const unit=form.elements.termUnit?.value||'months';if(unit==='fortnights'&&form.elements.paymentFrequency&&!form.elements.paymentFrequency.disabled)form.elements.paymentFrequency.value='semi_monthly';const frequency=form.elements.paymentFrequency?.value||'monthly';
 const count=Math.max(1,Math.floor(num(form.elements.termCount?.value)||1));
 form.elements.months.value=unit==='years'?count*12:unit==='fortnights'?Math.ceil(count/2):count;
 const months=num(form.elements.months.value),periods=unit==='fortnights'?count:months*(frequency==='semi_monthly'?2:1);
 const base={principal:num(form.elements.principal?.value),rate:num(form.elements.rate?.value),months,paymentFrequency:frequency,termQuincenas:unit==='fortnights'?count:null,firstDue:form.elements.firstDue?.value||today(),insuranceMonthly:form.elements.insuranceKind?.value==='none'?0:num(form.elements.insuranceMonthly?.value),monthlyFee:num(form.elements.monthlyFee?.value)};
 const payment=base.principal>0?fullOriginalLoan(base).installment:0;
 const confirmed=num(form.elements.currentInstallment?.value);
 const used=confirmed>0?confirmed:payment;
 const ins=v49LoanPeriodInsurance(base),fee=v49LoanPeriodFee(base),total=rnd(used+ins+fee),target=form.querySelector('#v49LoanEstimate');
 if(target)target.innerHTML=`<div class="v49-section-label"><span>RESUMEN</span><strong>Importe por vencimiento</strong></div><div class="v49-estimate-grid"><div><small>Periodicidad</small><strong>${frequency==='semi_monthly'?'Quincenal':'Mensual'}</strong></div><div><small>Cuotas previstas</small><strong>${periods.toLocaleString('es-DO')}</strong></div><div><small>${confirmed>0?'Capital + interés ajustado':'Capital + interés calculado'}</small><strong>${money(used,form.elements.currency?.value||'DOP',2)}</strong></div><div><small>Seguro + cargos por cuota</small><strong>${money(ins+fee,form.elements.currency?.value||'DOP',2)}</strong></div></div><div class="v49-estimate-total"><span>${confirmed>0?'Cuota pactada por vencimiento':'Cuota estimada por vencimiento'}</span><b>${money(total,form.elements.currency?.value||'DOP',2)}</b></div><small class="v49-help">${frequency==='semi_monthly'?'Dos cuotas cada mes. Si el primer vencimiento es antes o el día 15, el siguiente será fin de mes; si es después, el siguiente será día 15 del mes siguiente.':'Una cuota mensual según la fecha que elegiste.'} La tasa y los seguros pueden variar según contrato.</small>`;
 if(form.elements.insuranceMonthly?.closest('label'))form.elements.insuranceMonthly.closest('label').hidden=form.elements.insuranceKind?.value==='none';
}
const v49OriginalLoanForm=loanForm;
loanForm=function(id,preBank){
 v49OriginalLoanForm(id,preBank);
 const form=document.getElementById('loanForm');if(!form)return;
 form.classList.add('v49-loan-form');
 if(form.elements.months?.closest('label'))form.elements.months.closest('label').hidden=true;
 if(form.elements.termCount&&form.elements.termUnit){const l=db.loans.find(x=>x.id===form.dataset.id);const unit=l?.termUnit||'months';form.elements.termUnit.value=unit;form.elements.termCount.value=unit==='fortnights'?(num(l?.termQuincenas)||num(form.elements.months.value)*2):unit==='years'?Math.max(1,Math.round(num(form.elements.months.value)/12)):(num(form.elements.months.value)||36);}
 if(form.elements.termUnit?.disabled){const x=form.elements.termUnit;const h=document.createElement('input');h.type='hidden';h.name='termUnit';h.value=x.value;x.name='termUnitDisplay';form.appendChild(h);}
 if(form.elements.paymentFrequency){
  // On contracts with real payments, immutable values must still be submitted.
  if(form.elements.paymentFrequency.disabled){const original=form.elements.paymentFrequency;const h=document.createElement('input');h.type='hidden';h.name='paymentFrequency';h.value=original.value;original.name='paymentFrequencyDisplay';form.appendChild(h);}
 }
 v49UpdateLoanForm(form);
};
document.addEventListener('input',ev=>{if(ev.target?.form?.id==='loanForm')v49UpdateLoanForm(ev.target.form);},true);
document.addEventListener('change',ev=>{if(ev.target?.form?.id==='loanForm')v49UpdateLoanForm(ev.target.form);},true);
document.addEventListener('change',ev=>{
 const field=ev.target,form=field?.form;if(form?.id!=='transactionForm'||form.dataset.special!=='loan')return;
 if(field.name==='loanId'){
  const next=loan(field.value);if(!next)return;
  const acc=db.accounts.find(a=>a.currency===next.currency&&!a.archived)||db.accounts[0];
  transactionForm({type:'loan_payment',loanId:next.id,accountId:acc?.id||'',amount:'',principal:'',interest:'',insurance:'',fee:'',paymentKind:'regular'});
  return;
 }
 if(field.name==='paymentKind'){
  const f=form.elements,l=loan(f.loanId?.value),status=l?loanStatus(l):null;
  if(field.value==='extra'){
   f.interest.value='0';f.insurance.value='0';f.fee.value='0';
   f.principal.value=f.amount.value||'0';
  }else if(status){
   const interest=status.estimatedInterest,ins=v49LoanPeriodInsurance(l,status.periods),fee=v49LoanPeriodFee(l,status.periods),amount=rnd(status.installment+ins+fee);
   f.amount.value=amount;f.interest.value=interest;f.insurance.value=ins;f.fee.value=fee;
   f.principal.value=Math.max(0,rnd(amount-interest-ins-fee));
  }
  refreshLegacyLoanPayment();
 }
},true);
document.addEventListener('submit',ev=>{
 const f=ev.target;if(f?.id!=='loanForm')return;
 v49UpdateLoanForm(f);
 if(num(f.elements.months?.value)>600){ev.preventDefault();ev.stopImmediatePropagation();showError('El plazo máximo admitido es de 50 años (600 meses).');return;}
 if(f.elements.insuranceKind?.value==='none'&&f.elements.insuranceMonthly)f.elements.insuranceMonthly.value='0';
},true);


/* V50: live explanatory payroll without changing financial state or calculating premature deposits. */
function v50IncomeRefresh(form){
 if(!form||form.id!=='v40IncomeForm')return;
 const e=form.elements,formal=e.kind?.value==='formal',selected=form.dataset.v48KindChosen==='true';
 const message=form.querySelector('.v50-kind-confirm');
 if(message)message.textContent=selected?(formal?'✓ Nómina formal seleccionada. AFP, SFS e ISR se calcularán según Configuración.':'✓ Trabajo informal seleccionado. Solo registraremos los descuentos generales que introduzcas.'):'Selecciona una modalidad para continuar.';
 const visible = form.querySelector('.v50-income-quick');
 if(visible){
  try{
   const frequency=e.frequency?.value||'monthly';
   const grossMonthly=v45GrossMonthly(e.grossMonthly?.value||0,e.salaryBasis?.value||'monthly',frequency);
   const cc=e.currency?.value||'DOP';
   if(!(grossMonthly>0)){visible.innerHTML='<small>VISTA PREVIA</small><span>Introduce el importe bruto para calcular el neto previsto.</span>';}
   else{
    v43SyncCompany(form);
    const s={kind:e.kind?.value||'formal',grossMonthly,currency:cc,frequency,otherDeduction:Number(e.otherDeduction?.value)||0,companyDeductions:JSON.parse(e.companyDeductionsJSON?.value||'[]')};
    const result=v40Payroll(s,e.nextDue?.value||today());
    const suffix=frequency==='semi_monthly'?'por quincena':frequency==='annual'?'por año':frequency==='weekly'?'por semana':frequency==='quarterly'?'por trimestre':'por mes';
    visible.innerHTML=`<div class="v50-preview-top"><small>NETO ESTIMADO ${sanitize(suffix.toUpperCase())}</small><strong>${money(result.net,cc,2)}</strong></div><div class="v50-preview-rows"><div><small>BRUTO POR COBRO</small><b>${money(result.gross,cc,2)}</b></div><div><small>DEDUCCIONES</small><b>−${money(result.afp+result.sfs+result.isr+result.other,cc,2)}</b></div><div><small>BASE MENSUAL</small><b>${money(grossMonthly,cc,2)}</b></div></div>`;
   }
  }catch(err){visible.innerHTML='<small>VISTA PREVIA</small><span>'+sanitize(err.message||'Verifica el importe')+'</span>';}
 }
 const dateBox=form.querySelector('.v50-date-quick');
 if(dateBox){
  const f=e.frequency?.value||'monthly';let desc='';
  if(f==='semi_monthly'){let a=e.payDayA?.value||'15',b=e.payDayB?.value||'31';desc=`Días ${a} y ${b==='31'?'último día':b} de cada mes.`;}
  else if(f==='monthly')desc='Día '+(e.payDay?.value||'15')+' de cada mes.';
  else desc={weekly:'Cada 7 días.',quarterly:'Cada 3 meses.',annual:'Una vez al año.'}[f]||'';
  const mode=e.postingMode?.value==='auto'?'Asiento automático al sincronizar':'Esperará tu confirmación antes de acreditarse';
  const due=e.nextDue?.value?prettyDate(e.nextDue.value):'Por definir';
  dateBox.innerHTML=`<small>RESUMEN DE PROGRAMACIÓN</small><strong>${sanitize(v45FreqName(f))} · ${sanitize(desc)}</strong><span>Primer cobro previsto: ${sanitize(due)}.</span><span>${sanitize(mode)}. No registra pagos futuros.</span>`;
 }
}
const v50OriginalIncomeSummary=v48RefreshSummary;
v48RefreshSummary=function(form){
 v50OriginalIncomeSummary(form);
 const target=form.querySelector('.v50-review-extra');if(!target)return;
 try{
  v43SyncCompany(form);
  const e=form.elements,freq=e.frequency.value,base=v45GrossMonthly(e.grossMonthly.value,e.salaryBasis?.value||'monthly',freq),kind=e.kind.value;
  const p=v40Payroll({kind,frequency:freq,grossMonthly:base,currency:e.currency.value,otherDeduction:Number(e.otherDeduction.value)||0,companyDeductions:JSON.parse(e.companyDeductionsJSON?.value||'[]')},e.nextDue.value);
  const cc=e.currency.value;
  const pays=v80MonthlyFactor(freq);
  const first=prettyDate(e.nextDue.value);
  const inst=e.institutionId?.value?bank(e.institutionId.value)?.name:'Sin institución vinculada';
  let content=`<div class="v50-review-note"><strong>${sanitize(e.name.value)}</strong> · ${kind==='formal'?'Trabajo formal':'Actividad independiente'}<br>Frecuencia: <strong>${sanitize(v45FreqName(freq))}</strong> · Comienza el <strong>${sanitize(first)}</strong> · Cuenta: <strong>${sanitize(account(e.accountId.value)?.name||'Pendiente')}</strong>${inst&&e.institutionId?.value?'<br>Institución: '+sanitize(inst):''}.<br>${freq==='semi_monthly'?'Dos cobros por mes: bruto mensual '+money(base,cc,2)+' → neto quincenal '+money(p.net,cc,2)+'.':'Bruto por período '+money(p.gross,cc,2)+' → neto '+money(p.net,cc,2)+'.'}</div>`;
  if(kind==='formal'){
    const items=p.companyItems||[];
    if(items.length)content+=`<div class="v50-review-note"><b>Otros descuentos de empresa (por cobro)</b>${items.map(x=>`<div class="v50-review-deduction"><span>${sanitize(x.name)} · ${sanitize(x.category||'Otros gastos')}</span><b>−${money(x.amount,cc,2)}</b></div>`).join('')}</div>`;
  }
  content+='<div class="v50-review-note">Los valores de nómina son estimaciones. No se contabilizará ningún cobro anterior a su vencimiento, y los recibos ya registrados conservan sus importes.</div>';
  target.innerHTML=content;
 }catch(err){target.innerHTML='<p class="v48-validation-error">'+sanitize(err.message||'Verifica el desglose')+'</p>';}
};
