  const next30=obligations.filter(o=>o.date>=now&&o.date<=end),overdue=obligations.filter(o=>o.date<now),week=next30.filter(o=>o.date<=endWeek);
  const liquidity=(db.accounts||[]).reduce((a,c)=>a+fxAmt(getAccountBalance(c),c.currency),0);
