  const total=amounts(next30.map(o=>({amount:fxAmt(o.amount,o.currency)}))),late=amounts(overdue.map(o=>({amount:fxAmt(o.amount,o.currency)}))),w=amounts(week.map(o=>({amount:fxAmt(o.amount,o.currency)})));
