 const interest=section('02','Tasa de interés','La tasa anual es parte fundamental del contrato.');
 if(rate?.querySelector('.filter-label'))rate.querySelector('.filter-label').textContent='Tasa anual pactada (%)';
 if(currentRate?.querySelector('.filter-label'))currentRate.querySelector('.filter-label').textContent='Tasa anual vigente (%)';
 // Una única tasa contractual visible; los campos heredados se mantienen ocultos para compatibilidad.
