/* Reutiliza el Resumen existente, sin reestructurar las demás vistas. */
/* V123 · Alertas de gasto por categoría, exclusivamente desde datos locales.
   Las tres referencias son meses completos anteriores al mes actual.
   No se cuentan pagos de tarjeta, préstamos ni transferencias como compras nuevas. */
function v123CategoryAlertsFromTransactions(transactions,cutoff,rate){
 const m=String(cutoff||'').slice(0,7);
 if(!/^\d{4}-\d{2}$/.test(m))return [];
 const baselineMonths=[];for(let offset=3;offset>=1;offset--){
  const d=new Date(Number(m.slice(0,4)),Number(m.slice(5,7))-1-offset,1);
  baselineMonths.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);
 }
 const wanted=new Set([...baselineMonths,m]);
 const sums=new Map();const observed=new Set();
 const conversion=(tx)=>tx.currency==='USD'?Math.max(0,num(tx.fxRateSnapshot||rate)):1;
 for(const tx of transactions||[]){
  const day=String(tx.date||'');if(!/^\d{4}-\d{2}-\d{2}$/.test(day)||day>cutoff)continue;
  const period=day.slice(0,7);if(!wanted.has(period))continue;
  // Es una sola compra, aunque el pago de la tarjeta ocurra semanas después.
  if(!['expense','card_charge','card_refund'].includes(tx.type))continue;
  const category=String(tx.category||'Sin categoría').trim()||'Sin categoría';
  const amount=num(tx.amount)*conversion(tx)*(tx.type==='card_refund'?-1:1);
  if(!Number.isFinite(amount)||!amount)continue;
  const key=category+'\u0000'+period;
  sums.set(key,(sums.get(key)||0)+amount);
  observed.add(period);
 }
 const results=[];
 for(const category of new Set([...sums.keys()].map(k=>k.split('\u0000')[0]))){
  const previous=baselineMonths.map(period=>Math.max(0,sums.get(category+'\u0000'+period)||0));
  // La ausencia de gastos en un mes concreto no es un valor histórico fiable
  // si el usuario no registró ninguna operación en ese mes.
  if(baselineMonths.some(period=>!observed.has(period)))continue;
  const active=previous.filter(v=>v>0);
  if(active.length<2)continue;
  const avg=previous.reduce((sum,x)=>sum+x,0)/3;
  const current=Math.max(0,sums.get(category+'\u0000'+m)||0);
  if(avg<500)continue;
  const over=current-avg,ratio=avg>0?current/avg:0;
  if(current>=avg*1.5&&over>=1000){
   results.push({category,kind:'spike',average:rnd(avg),current:rnd(current),extra:rnd(over),pct:rnd((ratio-1)*100),history:previous.map(rnd)});
  }else if(previous.every(v=>v>=500)&&previous[1]>=previous[0]*1.15&&previous[2]>=previous[1]*1.15&&previous[2]>=previous[0]*1.5){
   results.push({category,kind:'trend',average:rnd(avg),current:rnd(current),extra:rnd(previous[2]-previous[0]),pct:rnd((previous[2]/previous[0]-1)*100),history:previous.map(rnd)});
  }
 }
 return results.sort((a,b)=>(a.kind==='spike'?-1:0)-(b.kind==='spike'?-1:0)||b.extra-a.extra).slice(0,5);
}
function v123CategoryAlerts(){return v99Memo('v123:category-alerts:'+today(),()=>v123CategoryAlertsFromTransactions(db.transactions,today(),db.settings.fx));}
function v123AlertText(a){
 if(a.kind==='trend')return `Subió en los últimos tres meses: ${money(a.history[0])} → ${money(a.history[2])}.`;
 return `Promedio: ${money(a.average)} · Este mes: ${money(a.current)} · ${a.pct.toFixed(0)}% por encima de lo habitual.`;
}
function v123AlertWidget(){
 const alerts=v123CategoryAlerts();if(!alerts.length)return '';
 return `<section class="v123-spending-panel" aria-label="Alertas de gastos fuera de lo habitual"><div class="v123-spending-head"><span class="v123-spending-symbol">${icon('chart')}</span><div><small>TUS HÁBITOS · ANÁLISIS PREVENTIVO</small><h2>Gastos fuera de lo habitual</h2><p>Comparación con los últimos tres meses completos.</p></div></div><div class="v123-spending-list">${alerts.slice(0,3).map(a=>`<div class="v123-spending-item"><div><strong>${sanitize(a.category)}</strong><small>${sanitize(v123AlertText(a))}</small></div><span class="v123-spending-percent">${a.kind==='trend'?'Tendencia al alza':`+${a.pct.toFixed(0)}%`}</span></div>`).join('')}</div><p class="v123-spending-disclaimer">Avisos orientativos según los gastos registrados. No incluyen abonos de tarjetas como nuevas compras.</p></section>`;
}
const v119PreviousOverview=pages.overview;
pages.overview=function(){return v123AlertWidget()+v119PreviousOverview()};


/* V144 · Centro de tarjetas y beneficios: interfaz contextual, sin duplicar el libro.
   Guarda únicamente referencias de beneficios previstos; los saldos reales siempre
   provienen de db.transactions y sus identificadores existentes. */
function v144Ready(){
 if(!Array.isArray(db.v144PendingBenefits))db.v144PendingBenefits=[];
 if(!Array.isArray(db.v144ScheduledCosts))db.v144ScheduledCosts=[];
}
function v144CurrentFx(t){return txDop(t)}
function v144AmountDOP(amount,currency){return rnd(num(amount)*(currency==='USD'?num(db.settings.fx)||0:1))}
function v144Value(value,currency='DOP'){return money(value,currency,2)}
function v144PeriodMatch(date){const y=String(ui.v144BenefitYear||nowYear()),m=String(ui.v144BenefitMonth||'all');return String(date||'').startsWith(y)&&(m==='all'||String(date||'').slice(5,7)===m)}
function v144AllCosts(c){return db.transactions.filter(t=>t.cardId===c.id&&(
 ((t.type==='card_charge'||t.type==='expense')&&(
  t.v144CardCost===true||['annual_fee','commission','insurance','issuance','renewal'].includes(t.chargeKind)||
  (t.type==='card_charge'&&t.category==='Deudas e intereses'&&/anualidad|membres[ií]a|seguro|comisi[oó]n/i.test(t.subcategory||''))
 ))));}
function v144CostPaid(t){
 if(t.type==='expense')return true;
 if(t.type!=='card_charge'||!t.v144SettledVia)return false;
 const pay=db.transactions.find(p=>p.id===t.v144SettledVia&&p.type==='card_payment'&&p.cardId===t.cardId&&p.currency===t.currency&&p.date>=t.date);
 if(!pay)return false;
 const linked=db.transactions.filter(x=>x.v144SettledVia===pay.id);
 return linked.every(x=>x.cardId===pay.cardId&&x.currency===pay.currency&&x.date<=pay.date)
   &&linked.reduce((sum,x)=>sum+num(x.amount),0)<=num(pay.amount)+.01;
}
function v144CostPaidDate(t){const p=db.transactions.find(p=>p.id===t.v144SettledVia);return t.type==='card_charge'&&v144CostPaid(t)?p.date:t.date;}
function v144CardStats(c,period=true){
 v144Ready();
 const match=date=>!period||v144PeriodMatch(date);
 const rewards=db.transactions.filter(t=>t.cardId===c.id&&['card_reward','bank_reward'].includes(t.type)&&match(t.date));
 const realizedCashback=rnd(rewards.filter(t=>t.v144BenefitKind!=='other').reduce((s,t)=>s+v144CurrentFx(t),0));
 const realizedOther=rnd(rewards.filter(t=>t.v144BenefitKind==='other').reduce((s,t)=>s+v144CurrentFx(t),0));
 const costs=v144AllCosts(c);
 const paid=costs.filter(t=>v144CostPaid(t)&&match(v144CostPaidDate(t)));
 const billed=costs.filter(t=>!v144CostPaid(t)&&match(t.date));
 const feePaid=rnd(paid.filter(t=>t.chargeKind==='annual_fee'||/anualidad|membres[ií]a/i.test(t.subcategory||'')).reduce((s,t)=>s+v144CurrentFx(t),0));
 const paidAmount=rnd(paid.reduce((s,t)=>s+v144CurrentFx(t),0));
 const billedAmount=rnd(billed.reduce((s,t)=>s+v144CurrentFx(t),0));
 const pending=db.v144PendingBenefits.filter(x=>x.cardId===c.id&&match(x.date));
 const expected=rnd(pending.reduce((s,x)=>s+v144AmountDOP(x.amount,x.currency),0));
 const planned=db.v144ScheduledCosts.filter(x=>x.cardId===c.id&&match(x.date));
 const plannedSum=rnd(planned.reduce((s,x)=>s+v144AmountDOP(x.amount,x.currency),0));
 const gross=rnd(realizedCashback+realizedOther),net=rnd(gross-paidAmount);
 return {rewards,paid,billed,pending,planned,realizedCashback,realizedOther,gross,paidAmount,billedAmount,feePaid,expected,plannedSum,net,roi:paidAmount>0?rnd(net/paidAmount*100):null};
}
function v144RoiText(value){return value===null?'No aplica':`${value>=0?'+':''}${new Intl.NumberFormat('es-DO',{maximumFractionDigits:1}).format(value)}%`}
function v144CardDue(c){const due=annualMembershipDate(c);const configured=num(c.annualFeeAmount)>0?num(c.annualFeeAmount):(num(c.annualFeeDOP)||num(c.annualFeeUSD));const cur=c.annualFeeCurrency||(num(c.annualFeeUSD)&&!num(c.annualFeeDOP)?'USD':'DOP');return {date:due,currency:cur,amount:configured};}
function v144CardKpis(c,small=false){
 const z=v144CardStats(c),d=cardStatus(c,'DOP'),u=cardStatus(c,'USD'),debt=rnd(d.debt+v144AmountDOP(u.debt,'USD'));
 const items=[['Deuda total',v144Value(debt),'RD$ + US$ equivalentes',''],['Cashback cobrado',v144Value(z.realizedCashback),'Solo acreditaciones confirmadas','good'],['Costo pagado',v144Value(z.paidAmount),'No incluye cargos sin conciliar','cost'],['Beneficio neto',v144Value(z.net),'Cashback + otros beneficios − costos pagados',z.net>=0?'good':'cost']];
 return `<div class="v144-kpis ${small?'compact':''}">${items.map(([label,val,note,kind])=>`<div class="v144-kpi ${kind}"><small>${sanitize(label)}</small><strong>${val}</strong><span>${sanitize(note)}</span></div>`).join('')}</div>`;
}
function v144ReceivedBenefits(c){
 const seen=new Set();
 const rows=[...(db.transactions||[]).filter(t=>t.cardId===c.id&&['card_reward','bank_reward'].includes(t.type)).map(t=>({key:'tx:'+t.id,date:t.date,label:t.note||'Cashback acreditado',value:money(t.amount,t.currency,2),detail:t.type==='bank_reward'?'Acreditado en cuenta':'Acreditado en tarjeta'})),...(db.perkUses||[]).filter(p=>p.cardId===c.id).map(p=>({key:'perk:'+p.id,date:p.date,label:p.name||'Beneficio recibido',value:p.kind==='points'?new Intl.NumberFormat('es-DO',{maximumFractionDigits:2}).format(num(p.value))+' puntos':num(p.value)?money(p.value,p.currency,2):'Registrado',detail:(({discount:'Descuento confirmado',points:'Puntos del programa',other:'Valor referencial'})[p.kind]||'Beneficio informativo')+' · no modifica saldos'}))].filter(r=>{if(seen.has(r.key))return false;seen.add(r.key);return true}).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
 return `<details class="v144-received-benefits" open><summary>Beneficios recibidos · ${rows.length}</summary>${rows.length?`<ul>${rows.slice(0,12).map(r=>`<li><div><strong>${sanitize(r.label)}</strong><small>${prettyDate(r.date)} · ${sanitize(r.detail)}</small></div><b>${sanitize(r.value)}</b></li>`).join('')}</ul>${rows.length>12?'<small>Últimos 12 registros. Consulta Análisis para filtrar el historial.</small>':''}`:'<small>Aún no hay beneficios registrados para esta tarjeta.</small>'}</details>`;
}
function v144CardExecutive(c,opts={}){
 const z=v144CardStats(c),due=v144CardDue(c),annual=(due.amount>0&&due.date)?`${v144Value(due.amount,due.currency)} · ${prettyDate(due.date)}`:due.amount>0?v144Value(due.amount,due.currency):'Sin configurar';
 return `<section class="v144-executive ${opts.mobile?'mobile':''}" aria-label="Beneficios y costos de ${sanitize(c.name)}">
 <div class="v144-section-head"><div><small>VALOR REAL DE TU TARJETA</small><h3>Beneficios y costos</h3><p>Ganancias confirmadas frente a dinero efectivamente pagado.</p></div><button type="button" class="v144-link" data-v144-action="open-benefits" data-id="${sanitize(c.id)}">Ver análisis ${icon('arrow')}</button></div>
 ${v144CardKpis(c,true)}
 <div class="v144-executive-strip"><span>Rentabilidad <b>${v144RoiText(z.roi)}</b></span><span>Costos cargados no conciliados <b>${v144Value(z.billedAmount)}</b></span><span>Anualidad prevista <b>${sanitize(annual)}</b></span></div>
 <div class="v144-actions"><button type="button" data-v144-action="new-cashback" data-id="${sanitize(c.id)}">${icon('plus')} Cashback</button><button type="button" data-v144-action="new-cost" data-id="${sanitize(c.id)}">${icon('receipt')} Costo de la tarjeta</button><button type="button" data-v144-action="open-benefits" data-id="${sanitize(c.id)}">${icon('chart')} Análisis</button></div>
 ${v144ReceivedBenefits(c)}
 </section>`;
}


function v144BenefitOptionsCards(){return [['all','Todas mis tarjetas'],...db.cards.filter(c=>ui.showHidden||!isHidden(c)).map(c=>[c.id,c.name])];}
function v144CardFilterUI(options=v144BenefitOptionsCards()){const year=String(ui.v144BenefitYear||nowYear()),month=ui.v144BenefitMonth||'all',selected=ui.v144BenefitsCard||'all';
 const months=[['all','Año completo'],...['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'].map((x,i)=>[String(i+1).padStart(2,'0'),x])];
 return `<div class="v144-filter-row"><label>Tarjeta<select data-v144-filter="card">${options.map(([v,t])=>`<option value="${sanitize(v)}" ${selected===v?'selected':''}>${sanitize(t)}</option>`).join('')}</select></label><label>Año<select data-v144-filter="year">${Array.from({length:6},(_,i)=>nowYear()+1-i).map(y=>`<option value="${y}" ${year===String(y)?'selected':''}>${y}</option>`).join('')}</select></label><label>Período<select data-v144-filter="month">${months.map(([v,t])=>`<option value="${v}" ${month===v?'selected':''}>${t}</option>`).join('')}</select></label></div>`;
}
/* V183 · Consistencia anual: solo beneficios confirmados y costos pagados.
   La anualidad configurada es informativa; no se mezcla con pagos reales. */
function v183YearBenefitMetrics(cards,year){
 const cardIds=new Set(cards.map(c=>c.id));
 const months=Array.from({length:12},(_,i)=>({month:i+1,earned:0,paid:0}));
 for(const t of db.transactions||[]){
  if(!cardIds.has(t.cardId)||!['card_reward','bank_reward'].includes(t.type))continue;
  const date=String(t.date||'');
  if(!date.startsWith(String(year)))continue;
  const m=Number(date.slice(5,7));if(m<1||m>12)continue;
  months[m-1].earned+=v144CurrentFx(t);
 }
 for(const c of cards){
  for(const t of v144AllCosts(c)){
   if(!v144CostPaid(t))continue;
   const date=String(v144CostPaidDate(t)||'');
   if(!date.startsWith(String(year)))continue;
   const m=Number(date.slice(5,7));if(m<1||m>12)continue;
   months[m-1].paid+=v144CurrentFx(t);
  }
 }
 let earn=0,paid=0;
 for(const m of months){
  m.earned=rnd(m.earned);m.paid=rnd(m.paid);
  earn=rnd(earn+m.earned);paid=rnd(paid+m.paid);
  m.accumulatedEarned=earn;
  m.accumulatedPaid=paid;
  m.accumulatedNet=rnd(earn-paid);
 }
 const feeConfigured=rnd(cards.reduce((sum,c)=>{
  const fee=v144CardDue(c);return sum+(fee.amount>0?v144AmountDOP(fee.amount,fee.currency):0);
 },0));
 return {months,earned:earn,paid,net:rnd(earn-paid),feeConfigured};
}

function v144BenefitsTable(cards){
 return `<div class="v144-table-wrap"><table class="v144-profit-table v183-profit-table"><thead><tr>
  <th>Tarjeta</th><th>Beneficios cobrados</th><th>Costos pagados</th><th>Cargos por conciliar</th><th>Anualidad configurada</th><th>Resultado neto</th><th>Detalle</th>
 </tr></thead><tbody>${cards.map(c=>{
  const z=v144CardStats(c),fee=v144CardDue(c);
  const feeText=fee.amount>0?v144Value(fee.amount,fee.currency):'Sin configurar';
  return `<tr><td data-label="Tarjeta"><strong>${sanitize(c.name)}</strong><small>${sanitize(bankOf(c))}</small></td>
   <td data-label="Beneficios cobrados">${v144Value(z.gross)}</td>
   <td data-label="Costos pagados">${v144Value(z.paidAmount)}</td>
   <td data-label="Cargos sin conciliar">${v144Value(z.billedAmount)}</td>
   <td data-label="Anualidad configurada">${feeText}<small>No es un pago registrado</small></td>
   <td data-label="Resultado neto" class="${z.net>=0?'positive':'negative'}">${v144Value(z.net)}</td>
   <td data-label="Detalle"><button type="button" class="v144-link" data-v144-action="open-benefits" data-id="${sanitize(c.id)}">Ver detalles</button></td>
  </tr>`;
 }).join('')}</tbody></table></div>`;
}



