 select.innerHTML='<option value="">Sin subcategoría</option>'+subcategoryOptions('gasto',category).map(s=>`<option value="${sanitize(s)}">${sanitize(v255TaxonomyOptionLabel('gasto',category,s))}</option>`).join('');
