document.addEventListener('click',e=>{
 const opener=e.target.closest('[data-v7-apple-id]');
 if(opener){e.preventDefault();e.stopPropagation();v7OpenAppleClassifier(opener.dataset.v7AppleId);return;}
 const close=e.target.closest('[data-v7-apple-close]');
 if(close){e.preventDefault();const root=document.getElementById('modal-root');if(root)root.innerHTML='';v8AppleDock();}
},true);
