function v245CreateNode(tag,className,html){
 const el=document.createElement(tag);el.className=className;
 if(html!==undefined)el.innerHTML=html;
 return el;
}
function v245CleanPayments(){
 const root=document.querySelector('#v145-payment-center');
 if(!root||root.dataset.v245Ready)return;
 root.dataset.v245Ready='1';
 const headline=root.querySelector('.v145-pay-hero');
 const tiles=root.querySelector('.v145-payment-kpis');
 if(!headline||!tiles||tiles.children.length<4)return;
 const main=tiles.children[0],pending=tiles.children[1],overdue=tiles.children[2];
 const sub=v245CreateNode('div','v245-pay-summary');
 sub.append(pending,overdue);
 main.classList.add('v245-pay-amount');
 headline.append(main,sub);
 tiles.remove(); // V283: no crear otro bloque de vistas o KPIs redundantes.
}

