   const f=e.target.closest?.('#v354-form');if(f){if(['purchase','received','paidAmount'].includes(e.target.name)&&e.target.type==='text'){e.target.value=e.target.value.replace(/,/g,'.').replace(/[^0-9.]/g,'');}recalc(f)}
