  const search=document.createElement('input');search.type='search';search.className='v785-picker-search';search.placeholder=isBenefit?'Buscar tarjeta…':'Buscar préstamo…';search.setAttribute('aria-label',search.placeholder);pane.prepend(search);
  search.addEventListener('input',()=>{const q=search.value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();rows.forEach(b=>b.hidden=!b.textContent.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q));});
