/* ==== script: v342-reorder-script ==== */
(function(){
 let active=null,timer=null;
 function clear(){if(timer)clearTimeout(timer);timer=null;if(active){active.node?.classList.remove('v342-dragging');document.querySelectorAll('.v342-drop-target').forEach(x=>x.classList.remove('v342-drop-target'));active=null}}
 function saveMove(from,to){if(!from||!to||from===to)return;const cfg=v105Config();const a=cfg.order.indexOf(from),b=cfg.order.indexOf(to);if(a<0||b<0)return;
  const old=db.settings.v105OverviewWidgets;cfg.order.splice(a,1);cfg.order.splice(b,0,from);db.settings.v105OverviewWidgets={order:cfg.order.slice(),visible:cfg.visible.slice()};
  if(!persist()){db.settings.v105OverviewWidgets=old;toast('No se pudo guardar el orden.');return}render();toast('Orden actualizado en Personalización.');}
 document.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-v342-drag]');if(!handle||e.button>0)return;clear();const node=handle.closest('[data-v316-row]');if(!node)return;
  active={id:handle.dataset.v342Drag,node,ready:false,pointer:e.pointerId,x:e.clientX,y:e.clientY,target:null};
  timer=setTimeout(()=>{if(active){active.ready=true;active.node.classList.add('v342-dragging');}},420);
 },{passive:true});
 document.addEventListener('pointermove',e=>{if(!active||active.pointer!==e.pointerId)return;
  if(!active.ready){if(Math.hypot(e.clientX-active.x,e.clientY-active.y)>14)clear();return;}
  document.querySelectorAll('.v342-drop-target').forEach(x=>x.classList.remove('v342-drop-target'));
  const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-v316-row]');
  if(target&&target!==active.node){active.target=target;target.classList.add('v342-drop-target')}
 },{passive:true});
 document.addEventListener('pointerup',e=>{if(!active||active.pointer!==e.pointerId)return;const from=active.id,ready=active.ready,target=active.target?.dataset.v316Row;clear();if(ready&&target)saveMove(from,target)},true);
 document.addEventListener('pointercancel',clear,true);
})();
/* Do not navigate backwards when swiping a horizontal card gallery. */
(function(){
 let touch=null,blockUntil=0;
 const railSelector='.v266-gallery-track,.v68-wallet-gallery,.v144-card-rail,.v58m-cardrail';
 document.addEventListener('pointerdown',e=>{const rail=e.target.closest(railSelector);touch=rail?{rail,x:e.clientX,y:e.clientY,moved:false}:null},{passive:true,capture:true});
 document.addEventListener('pointermove',e=>{if(!touch)return;const dx=Math.abs(e.clientX-touch.x),dy=Math.abs(e.clientY-touch.y);if(dx>18&&dx>dy*1.3)touch.moved=true},{passive:true,capture:true});
 document.addEventListener('pointerup',()=>{if(touch?.moved)blockUntil=performance.now()+350;touch=null},{passive:true,capture:true});
 document.addEventListener('pointercancel',()=>{touch=null},{passive:true,capture:true});
 document.addEventListener('click',e=>{if(performance.now()<blockUntil&&e.target.closest(railSelector)){e.preventDefault();e.stopImmediatePropagation();blockUntil=0}},true);
})();
