/* ==== script: v391-registration-interaction ==== */
(()=>{'use strict';
 const root=document.getElementById('modal-root');if(!root)return;
 const names={transactionForm:'Movimiento',accountForm:'Cuenta',cardForm:'Tarjeta',loanForm:'Préstamo',certificateForm:'Certificado',personalLoanForm:'Acuerdo',personalPaymentForm:'Abono',recurringForm:'Servicio',annualFeeForm:'Anualidad',rewardReceivedForm:'Beneficio',benefitLedgerForm:'Beneficio',manualBenefitForm:'Beneficio',v144CashbackForm:'Cashback',bankForm:'Institución',categoryForm:'Categoría',budgetForm:'Presupuesto',cashWalletForm:'Efectivo'};
  let processing=false;
 function decorate(){
  if(processing)return;processing=true;
  try{
   for(const modal of root.querySelectorAll('.modal.v204-form-dialog')){
    if(modal.dataset.v391Ready==='1')continue;
    const form=modal.querySelector(':scope > form');if(!form)continue;
    const formName=names[form.id]||'Registro';
    modal.dataset.v391Ready='1';modal.classList.add('v391-form-shell');
    const head=modal.querySelector(':scope > .modal-head');
    // Barra de etapas decorativa eliminada; se mantienen encabezado y validaciones.
    const error=form.querySelector('#formError');if(error){error.setAttribute('role','alert');error.setAttribute('aria-live','polite');}
    // Preserve native validation and all original financial submit handlers.
    form.addEventListener('invalid',e=>{const field=e.target;if(!(field instanceof HTMLElement))return;const details=field.closest('details');if(details)details.open=true;field.setAttribute('aria-invalid','true');},true);
    form.addEventListener('input',e=>{const field=e.target;if(field instanceof HTMLElement&&field.matches('input,select,textarea')&&field.checkValidity())field.removeAttribute('aria-invalid')});
    form.addEventListener('change',e=>{const field=e.target;if(field instanceof HTMLElement&&field.matches('input,select,textarea')&&field.checkValidity())field.removeAttribute('aria-invalid')});
   }
  }finally{processing=false;}
 }
 decorate();
 let queued=false;const observer=new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;decorate();})});observer.observe(root,{childList:true,subtree:true});
})();
;
/* ==== script: v399-individual-forms-script ==== */
(()=>{'use strict';
 const root=document.getElementById('modal-root');if(!root)return;
 // Each description is contextual to the individual registration process. No business logic is changed.
 const catalog={
 transactionForm:['Movimiento','Revisa importe, fecha y cuenta o tarjeta antes de registrar.','MO','movement'],
 accountForm:['Cuenta bancaria','Identifica la institución, moneda y saldo inicial.','CU','movement'],
 cardForm:['Tarjeta','Revisa límites, moneda, fechas de corte y vencimiento.','TC','credit'],
 loanForm:['Préstamo','Confirma capital, tasa, periodicidad y calendario de pagos.','PR','credit'],
 certificateForm:['Certificado','Valida capital, plazo, rendimiento y vencimiento.','CE','credit'],
 personalLoanForm:['Acuerdo entre personas','Indica si debes o te deben, importe y fecha de inicio.','AP','people'],
 personalPaymentForm:['Abono entre personas','Comprueba capital, intereses y saldo resultante.','AB','people'],
 recurringForm:['Servicio o suscripción','Confirma importe, frecuencia, categoría y próximo cobro.','SU','services'],
 annualFeeForm:['Anualidad de tarjeta','Registra la anualidad correspondiente y su fecha de cobro.','AN','credit'],
 rewardReceivedForm:['Beneficio recibido','Comprueba la tarjeta y el destino de la acreditación.','BR','rewards'],
 benefitLedgerForm:['Beneficio o puntos','Diferencia el beneficio monetario del no monetario.','BP','rewards'],
 manualBenefitForm:['Cashback','Revisa el importe, la tarjeta y el estado de acreditación.','CB','rewards'],
 benefitRuleForm:['Regla de beneficios','Define las condiciones sin contabilizar dinero anticipado.','RB','rewards'],
 perkUsageForm:['Uso de beneficio','Registra el beneficio utilizado y su fecha.','UB','rewards'],
 recurringPaymentConfirmForm:['Pago recurrente','Comprueba el servicio, importe y fuente del pago.','PG','services'],
 cashWalletForm:['Efectivo','Identifica moneda, fecha y operación del efectivo.','EF','movement'],
 personalDebtForm:['Entre personas','Confirma el acuerdo y el sentido de la obligación.','EP','people']
 };
  let busy=false;
 function apply(){if(busy)return;busy=true;try{
  for(const dialog of root.querySelectorAll('.modal.v204-form-dialog')){
   if(dialog.dataset.v399Ready==='1')continue;
   const form=dialog.querySelector(':scope > form');if(!form)continue;
   const cfg=catalog[form.id];if(!cfg)continue;
   dialog.dataset.v399Ready='1';dialog.classList.add('v399-individual-form');dialog.dataset.v399Kind=cfg[3];
   // Cabecera contextual adicional eliminada por preferencia de interfaz.
   // Design layer only: do not change submit, confirmation, persistence or calculations.
  }
 }finally{busy=false;}}
 apply();let queued=false;new MutationObserver(()=>{if(queued)return;queued=true;queueMicrotask(()=>{queued=false;apply();})}).observe(root,{childList:true,subtree:true});
})();
;
/* ==== script: v400-review-confirmation-script ==== */
(()=>{'use strict';
 const root=document.getElementById('modal-root');if(!root)return;
 const descriptions={
  'ingreso':['Entrada de dinero','La aplicación registrará la entrada según la cuenta, fecha y categoría indicadas.'],
  'egreso':['Salida de dinero','La aplicación registrará el gasto según la cuenta, fecha y categoría indicadas.'],
  'gasto':['Salida de dinero','Revisa el origen del dinero, la categoría y el importe antes de guardar.'],
  'transferencia':['Movimiento entre instrumentos','Comprueba la cuenta de origen, el destino, la moneda y las comisiones si corresponden.'],
  'préstamo':['Operación de préstamo','Revisa por separado capital, intereses, seguros y cargos calculados.'],
  'tarjeta':['Operación de tarjeta','Comprueba la tarjeta y el efecto sobre la deuda, el corte o el pago.'],
  'devolución':['Reintegro o devolución','Verifica el importe, la tarjeta o cuenta receptora y la compra original si está vinculada.'],
  'cashback':['Acreditación de beneficio','Confirma si el beneficio reduce deuda, ingresa a una cuenta o permanece pendiente.'],
  'beneficio':['Registro de beneficio','Revisa si el beneficio es monetario o informativo y su estado de acreditación.'],
  'suscripción':['Servicio o suscripción','Comprueba frecuencia, fecha de cobro y medio de pago antes de registrar.'],
  'entre personas':['Obligación entre personas','Verifica si debes o te deben y el importe que quedará pendiente.'],
  'conciliación':['Ajuste de saldo','Comprueba el saldo del banco y la diferencia: no debe confundirse con ingreso o gasto.']
 };
 const enrich=()=>{
  for(const screen of root.querySelectorAll('.v349-review-screen:not([data-v400-enhanced])')){
   screen.dataset.v400Enhanced='1';
   const panel=screen.querySelector('.v349-review-panel');const main=screen.querySelector('.v353-review-main');if(!panel||!main)continue;
   const rows=[...main.querySelectorAll('.v349-review-row')];
   const operation=rows.find(el=>el.querySelector('span')?.textContent?.trim()==='Operación');
   const name=(operation?.querySelector('strong')?.textContent||'').trim();
   const norm=name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
   const key=Object.keys(descriptions).find(k=>norm.includes(k.normalize('NFD').replace(/[\u0300-\u036f]/g,'')));
   const [title,explain]=key?descriptions[key]:['Registro financiero','Comprueba importe, fecha y los instrumentos involucrados. El resultado dependerá del tipo de operación seleccionado.'];
   const section=document.createElement('section');section.className='v400-review-clarity';section.setAttribute('aria-label','Qué estás confirmando');
   const kicker=document.createElement('p');kicker.className='v400-review-kicker';kicker.textContent='Antes de guardar';
   const heading=document.createElement('h3');heading.className='v400-review-title';heading.textContent=title;
   const detail=document.createElement('p');detail.className='v400-review-explain';detail.textContent=explain;
   const marks=document.createElement('div');marks.className='v400-review-indicators';
   for(const label of ['Importe','Origen y destino','Fecha']){const chip=document.createElement('span');chip.textContent=label;marks.append(chip)}
   section.append(kicker,heading,detail,marks);main.append(section);
   const note=screen.querySelector('.v349-review-note');if(note&&!note.hasAttribute('role'))note.textContent='Confirma solo después de revisar los datos. Si el guardado falla, no asumas que quedó sincronizado.';
  }
 };
 let scheduled=false;const schedule=()=>{if(scheduled)return;scheduled=true;queueMicrotask(()=>{scheduled=false;enrich()})};
 new MutationObserver(schedule).observe(root,{childList:true,subtree:true});enrich();
})();
;
/* ==== script: v401-financial-logic ==== */
/* V401 — Auditoría financiera extendida: informativa, sin escritura ni modificación de balances.
   Casos críticos: tasa USD, divisas de transferencia, abonos personales, prestaciones de crédito.
   La ausencia de alertas no representa conciliación bancaria ni verificación remota. */
function v401FinancialLogicAudit(){
 const findings=[];const put=(name,reason,id)=>{if(findings.length<150)findings.push({name,reason,id:String(id||'')})};
 const currentFx=Number(db?.settings?.fx);
 const hasUSD=(db.accounts||[]).some(a=>a.currency==='USD')||(db.cards||[]).some(c=>Number(c.limitUSD)>0)||(db.transactions||[]).some(t=>t.currency==='USD');
 if(hasUSD&&(!Number.isFinite(currentFx)||currentFx<=0))put('Tipo de cambio inválido','La tasa DOP por USD debe ser mayor que cero; las conversiones podrían quedar en cero.','');
 const byPerson=new Map();for(const t of db.transactions||[]){
  if(!t||!t.type)continue;
  const amt=Number(t.amount),src=Number(t.sourceAmount),tax=Number(t.paymentTax||0),fee=Number(t.paymentFee||0);
  if(['card_payment','loan_payment'].includes(t.type)){
   if(!Number.isFinite(src)||src<=0)put('Débito bancario inválido','El pago necesita un importe de origen válido.',t.id);
   if(!Number.isFinite(tax)||!Number.isFinite(fee)||tax<0||fee<0)put('Cargo o impuesto inválido','Los cargos asociados a un pago no pueden ser negativos ni indefinidos.',t.id);
   const a=account(t.accountId);if(a&&a.currency!==t.currency&&!Number.isFinite(Number(t.fxRateSnapshot))&&!Number.isFinite(Number(t.paymentFxRate)))put('Tipo de cambio no documentado','El pago usa monedas distintas; verifica el importe efectivamente debitado y la tasa utilizada.',t.id);
  }
  if(t.type==='transfer'){
   const a=account(t.accountId),b=account(t.toAccountId),target=Number(t.targetAmount);
   if(a&&b){
    if(a.currency===b.currency&&Number.isFinite(amt)&&Number.isFinite(target)&&Math.abs(amt-target)>.02)put('Transferencia de misma moneda','Los importes enviado y recibido son distintos. Revisa si corresponde una comisión o ajuste explícito.',t.id);
    if(a.currency!==b.currency&&(!Number.isFinite(target)||target<=0))put('Conversión incompleta','La cuenta receptora necesita un importe positivo en su propia moneda.',t.id);
   }
   if(!Number.isFinite(Number(t.transferFee||0))||Number(t.transferFee||0)<0)put('Comisión de transferencia inválida','La comisión debe ser un importe válido no negativo.',t.id);
  }
  if(['card_charge','card_refund','card_reward'].includes(t.type)){
   const c=card(t.cardId);if(c&&!['DOP','USD'].includes(t.currency))put('Moneda de tarjeta inválida','El movimiento de tarjeta debe estar en DOP o USD.',t.id);
  }
  if(['personal_issue','personal_settlement'].includes(t.type)){
   if(!personalLoan(t.personalLoanId))put('Acuerdo personal inexistente','El movimiento referencia un acuerdo entre personas que ya no existe.',t.id);
   if(t.type==='personal_settlement'){
    const capital=Number(t.principal),interest=Number(t.interest||0);
    if(!Number.isFinite(capital)||capital<0||!Number.isFinite(interest)||interest<0)put('Abono personal inválido','Capital e intereses deben ser importes válidos no negativos.',t.id);
    const l=personalLoan(t.personalLoanId);if(l&&t.currency!==l.currency)put('Moneda de deuda inconsistente','El abono y el acuerdo personal deben utilizar la misma moneda.',t.id);
    if(l&&t.date<l.date)put('Abono anterior al acuerdo','Comprueba la fecha del abono respecto a la fecha de entrega.',t.id);
    if(l&&t.date<=today()){const key=l.id;byPerson.set(key,(byPerson.get(key)||0)+(Number.isFinite(capital)?Math.max(0,capital):0));}
   }
  }
 }
 for(const l of db.personalLoans||[]){
  const principal=Number(l.principal),forgiven=l.forgiveness?.date&&l.forgiveness.date<=today()?Number(l.forgiveness.amount||0):0;
  if(!Number.isFinite(principal)||principal<=0)put('Capital personal inválido','El capital inicial del acuerdo debe ser positivo.',l.id);
  if(!Number.isFinite(forgiven)||forgiven<0)put('Condonación inválida','El capital perdonado debe ser válido y no negativo.',l.id);
  if(Number.isFinite(principal)&&Number.isFinite(forgiven)&&(byPerson.get(l.id)||0)+forgiven>principal+.02)put('Capital personal excedido','Los abonos más el importe perdonado exceden el capital pactado.',l.id);
 }
 return {count:(db.transactions||[]).length,findings,total:findings.length,limited:findings.length>=150};
}
function v401FinancialLogicSection(){
 const result=v401FinancialLogicAudit(),shown=result.findings.slice(0,25);
 return `<details class="v30-control v401-financial-logic"><summary>Lógica financiera · ${result.total?`${result.total} alerta(s) por revisar`:'sin alertas adicionales'}</summary><div class="v339-integrity-body"><p>Diagnóstico informativo de tipos de cambio, monedas, cargos, préstamos personales y movimientos. No modifica saldos ni valida estados bancarios reales.</p>${shown.length?`<ul>${shown.map(x=>`<li><b>${sanitize(x.name)}</b> · ${sanitize(x.reason)} ${x.id?`<code>${sanitize(x.id.slice(0,12))}</code>`:''}</li>`).join('')}</ul>${result.total>shown.length?'<p>Hay más observaciones; se muestran las primeras 25.</p>':''}`:'<p>Sin alertas adicionales según las reglas V401. Debes seguir conciliando contra estados de cuenta reales.</p>'}</div></details>`;
}
