/* ==== script: v500-confirm-review-polish-script ==== */
(function(){
  'use strict';
  function stripLegacyPaymentPreview(scope){
    (scope||document).querySelectorAll('.v382-card-payment-preview,.v382-review-card').forEach(el=>el.remove());
  }
  function wrapFeedback(){
    const original=window.v156TransactionFeedback;
    if(typeof original!=='function' || original.__v500Wrapped)return;
    const wrapped=function(tx){
      window.setTimeout(()=>{
        try{original(tx);}catch(error){console.error('Animación de confirmación:',error);}
      },80);
    };
    wrapped.__v500Wrapped=true;
    window.v156TransactionFeedback=wrapped;
  }
  function boot(){
    wrapFeedback();
    stripLegacyPaymentPreview(document);
    const modalRoot=document.getElementById('modal-root');
    if(modalRoot && !modalRoot.__v500Observer){
      const mo=new MutationObserver(()=>stripLegacyPaymentPreview(modalRoot));
      mo.observe(modalRoot,{childList:true,subtree:true});
      modalRoot.__v500Observer=mo;
    }
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});
  else boot();
})();
;
/* ==== script: v612-fastx-other-category-behavior ==== */
(function(){
  const syncForm=(form)=>{
    if(!form || !form.matches('.fastx-form')) return;
    const section=form.querySelector('.fastx-category-section');
    if(!section) return;
    const more=section.querySelector('.v134-category-more');
    const otherBtn=section.querySelector('[data-fast-other]');
    const select=form.elements.category;
    const popular=[...section.querySelectorAll('[data-fast-category]')].map(b=>b.dataset.fastCategory);
    const value=(select && String(select.value||'')) || '';
    const isOther=!!value && !popular.includes(value);
    if(otherBtn) otherBtn.classList.toggle('selected', isOther || !!more?.open);
    if(more){
      const label=more.querySelector('summary span:first-child');
      if(label){
        const next=isOther ? 'Otra categoría · '+value : 'Otras categorías';
        if(label.textContent!==next) label.textContent=next;
      }
    }
  };
  const modalRoot=document.getElementById('modal-root');
  if(!modalRoot) return;
  modalRoot.addEventListener('click', (ev)=>{
    const other=ev.target.closest('[data-fast-other]');
    if(!other) return;
    const form=other.closest('form.fastx-form');
    const more=form?.querySelector('.v134-category-more');
    if(!more) return;
    ev.preventDefault();
    more.open=true;
    requestAnimationFrame(()=>{
      const select=more.querySelector('select[name="category"]') || form.elements.category;
      if(select && typeof select.focus==='function') select.focus({preventScroll:true});
      if(typeof more.scrollIntoView==='function') more.scrollIntoView({block:'nearest', behavior:'smooth'});
      syncForm(form);
    });
  }, true);
  modalRoot.addEventListener('change',(ev)=>{
    const form=ev.target?.closest?.('form.fastx-form');
    if(form) syncForm(form);
  }, true);
  const boot=()=>modalRoot.querySelectorAll('form.fastx-form').forEach(syncForm);
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded', boot, {once:true}); else boot();
  // No observar el DOM completo: la mutación del texto de categoría provocaba
  // un ciclo infinito que bloqueaba los clics del asistente en web y móvil.
  // La selección se actualiza exclusivamente en los eventos reales click/change.
})();
;
/* ==== script: v709-recurring-black-and-flow-details-script ==== */
(function(){
  function closeDetail(){
    const dialog=document.getElementById('v362-flow-detail-dialog');
    if(dialog) dialog.remove();
    document.body.classList.remove('v362-flow-open');
  }
  function openDetail(btn){
    closeDetail();
    const title=btn.getAttribute('data-title')||'Detalle';
    const value=btn.getAttribute('data-value')||'—';
    const summary=btn.getAttribute('data-summary')||'';
    const line1=btn.getAttribute('data-line1')||'';
    const value1=btn.getAttribute('data-value1')||'';
    const line2=btn.getAttribute('data-line2')||'';
    const value2=btn.getAttribute('data-value2')||'';
    const dialog=document.createElement('div');
    dialog.id='v362-flow-detail-dialog';
    dialog.className='v362-flow-overlay';
    dialog.innerHTML=`<div class="v362-flow-backdrop" data-v362-flow-close="1"></div><section role="dialog" aria-modal="true" aria-labelledby="v362-flow-title" class="v362-flow-sheet"><header><div><small>DINERO COMPROMETIDO · DETALLE</small><h2 id="v362-flow-title">${title}</h2></div><button type="button" data-v362-flow-close="1" aria-label="Cerrar detalle">×</button></header><div class="v362-flow-main"><span>Valor del escenario</span><strong>${value}</strong><p>${summary}</p></div><div class="v362-flow-list"><div class="v362-flow-row"><span>${line1}</span><b>${value1}</b></div><div class="v362-flow-row"><span>${line2}</span><b>${value2}</b></div></div><footer><button type="button" data-v362-flow-close="1">Volver al gráfico</button></footer></section>`;
    document.body.appendChild(dialog);
    document.body.classList.add('v362-flow-open');
    dialog.querySelector('.v362-flow-sheet header button')?.focus();
  }
  document.addEventListener('click',function(event){
    const close=event.target.closest('[data-v362-flow-close]');
    if(close){ event.preventDefault(); closeDetail(); return; }
    const btn=event.target.closest('[data-v362-flow-detail]');
    if(btn){ event.preventDefault(); openDetail(btn); }
  },true);
  document.addEventListener('keydown',function(event){ if(event.key==='Escape' && document.getElementById('v362-flow-detail-dialog')) closeDetail(); },true);
})();
;
