  function fixExploreAndModuleIcons(){
    document.querySelectorAll('.module-switch-tab svg, .v410-explore-grid svg, .v205-explore-grid svg, .v243-explore-return svg').forEach(svg=>{
      svg.style.width='20px'; svg.style.height='20px';
    });
  }
  function sync(){
    try{ replaceBrandText(); }catch(e){}
    stripCounterEyebrows();
    normalizeTitleBadges();
    removeWalletDetailsButton();
    /* v921: la píldora de avances se renderiza en el componente original, sin duplicarla. */
    normalizeWalletAccents();
    markHistoricalButtons();
    fixExploreAndModuleIcons();
  }
  document.addEventListener('DOMContentLoaded', sync, {once:true});
  let raf=0;
  const obs=new MutationObserver(()=>{ cancelAnimationFrame(raf); raf=requestAnimationFrame(sync); });
  const start=()=>{ const root=document.getElementById('app')||document.body; obs.observe(root,{childList:true,subtree:true}); sync(); };
