/* ==== script: v914-navigation-enforcement ==== */
/* Aplica el nivel REAL a las cápsulas que renderiza la app, incluso cuando
   componentes heredados tienen reglas más específicas o estilos dinámicos. */
(function(){
 /* Movimientos, Bancos y Presupuestos usan la misma barra plana que Inicio: sin cristal ni desenfoque dinámico. */
 const shells='.universe-switch-wrap,.universe-switch,.inner-menu-tabs,.segmented-hist,.product-tabs,.top-tabs,.bank-tabs,.v206-bank-tabs,.v207-operation-choice,.v245-inner-tabs';
 function level(){const n=Number(document.documentElement.style.getPropertyValue('--v443-nav-level'));return Number.isFinite(n)?Math.max(0,Math.min(100,n)):0;}
 function force(){
  if(window.matchMedia('(max-width:790px)').matches)return;
  const root=document.querySelector('#app main.main');if(!root)return;
  const n=level(), r=n/100, off=n===0;
  const black=document.body.classList.contains('theme-black')||document.body.classList.contains('theme-dark');
  const col=black?'31,33,41':'255,255,255';
  const border=black?'130,147,179':'163,184,218';
  const shadow=black?'0,0,0':'49,81,136';
  const vals={
   'background': off?'transparent':`rgba(${col},${(.4*r).toFixed(3)})`,
   'background-image':'none',
   'border-color':off?'transparent':`rgba(${border},${(.75*r).toFixed(3)})`,
   'box-shadow':off?'none':`inset 0 1px 0 rgba(255,255,255,${(.68*r).toFixed(3)}),0 9px 24px rgba(${shadow},${(.09*r).toFixed(3)})`,
   'backdrop-filter':off?'none':`blur(${(26*r).toFixed(1)}px)`,
   '-webkit-backdrop-filter':off?'none':`blur(${(26*r).toFixed(1)}px)`
  };
  root.querySelectorAll(shells).forEach(el=>{
   const key=n+'|'+black;
   if(el.dataset.v914Level===key)return;
   for(const [k,v] of Object.entries(vals))el.style.setProperty(k,v,'important');
   el.dataset.v914Level=key;
  });
  /* V916: no pintar pestañas con estilos inline en cada render.
     La clase .active/aria de la vista es la fuente única del estado. */
 }
 let raf=0;
 const queue=()=>{if(raf)return;raf=requestAnimationFrame(()=>{raf=0;force();})};
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',queue,{once:true});else queue();
 document.addEventListener('input',e=>{if(e.target?.id==='v443-nav-slider')queue()},true);
 document.addEventListener('change',e=>{if(e.target?.id==='v443-nav-slider')queue()},true);
 document.addEventListener('click',e=>{if(e.target?.closest('[data-v443-nav-preset]'))queue()},true);
 const host=document.getElementById('app');
 if(host)new MutationObserver(queue).observe(host,{subtree:true,childList:true});
})();
;
/* ==== script: v916-instant-single-active-state ==== */
/* El botón activo se actualiza de manera atómica: no hay dos cápsulas
   resaltadas ni una animación del botón anterior hacia el siguiente. */
(function(){
 const groups='.universe-switch,.module-switch-tabs,.inner-menu-tabs,.v248-budget-tabs,.segmented-hist,.product-tabs,.top-tabs,.bank-tabs,.v206-bank-tabs,.v207-operation-choice,.v245-inner-tabs';
 const buttons='button,[role="tab"]';
 const accent='var(--v424-accent-strong,var(--vive-theme-color,#665fe7))';
 const ink='var(--v916-nav-muted,var(--vx-text-2))';
 function paint(group, selected){
  if(!group || matchMedia('(max-width:790px)').matches)return;
  if(group.closest('#page:has(.v58-exec)'))return; /* Ingresos web: la barra vive dentro del banner con estilo propio (CSS) */
  for(const el of group.querySelectorAll(buttons)){
   const on=el===selected;
   el.style.setProperty('transition','none','important');
   el.style.setProperty('animation','none','important');
   el.style.setProperty('transform','none','important');
   el.style.setProperty('background-color',on?accent:'transparent','important');
   el.style.setProperty('background-image','none','important');
   el.style.setProperty('border-color','transparent','important');
   el.style.setProperty('box-shadow',on?'0 5px 15px color-mix(in srgb,var(--v424-accent-strong,#7b2d57) 24%,transparent)':'none','important');
   el.style.setProperty('opacity','1','important');
   el.style.setProperty('color',on?'#fff':ink,'important');
   el.style.setProperty('-webkit-text-fill-color',on?'#fff':ink,'important');
  }
 }
 function reconcile(){
  document.querySelectorAll('#app main.main '+groups.replaceAll(',',',#app main.main ')).forEach(group=>{
   const selected=Array.from(group.querySelectorAll(buttons)).find(el=>el.classList.contains('active')||el.getAttribute('aria-selected')==='true'||el.getAttribute('aria-current')==='page');
   if(selected)paint(group,selected);
  });
 }
 document.addEventListener('click',function(e){
  if(matchMedia('(max-width:790px)').matches)return;
  const el=e.target.closest('#app main.main :is('+groups+') > button, #app main.main :is('+groups+') > [role="tab"]');
  if(!el||el.disabled)return;
  const group=el.parentElement;
  if(!group || group.querySelectorAll(buttons).length < 2)return;
  for(const button of group.querySelectorAll(buttons)){
   const selected=button===el;
   button.classList.toggle('active',selected);
   if(button.getAttribute('role')==='tab'||button.hasAttribute('aria-selected')) button.setAttribute('aria-selected',String(selected));
   if(selected)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');
  }
  paint(group,el);
 },true);
 let scheduled=false;
 const queue=()=>{if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{scheduled=false;reconcile()});};
 const start=()=>{reconcile();const host=document.getElementById('app');if(host)new MutationObserver(queue).observe(host,{childList:true,subtree:true});};
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
;
